L.STRINGS = {
	["120 Merchant's Favor"] = "120 상인의 호의",
	["1200 Merchant's Favor"] = "1200 상인의 호의",
	["1500 Merchant's Favor"] = "1500 상인의 호의",
	["180 Merchant's Favor"] = "180 상인의 호의",
	["200 Merchant's Favor"] = "200 상인의 호의",
	["240 Merchant's Favor"] = "240 상인의 호의",
	["270 Merchant's Favor"] = "270 상인의 호의",
	["360 Merchant's Favor"] = "360 상인의 호의",
	["60 Merchant's Favor"] = "60 상인의 호의",
	["6000 Merchant's Favor"] = "6000 상인의 호의",
	["90 Merchant's Favor"] = "90 상인의 호의",
	["A 1.5-second cast: a 3-minute curse that hurts the player now and then when they attack. Remove it."] = "시전 시간 1.5초. 3분 동안 지속되는 저주로, 걸린 플레이어가 공격할 때 이따금 피해를 입힙니다. 해제하십시오.",
	["A 2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged players, stay beyond 25 yards; melee, step out during the cast."] = "2초 동안 시전한 뒤, 6초 동안 2초마다 비전 에너지가 25미터 내의 모두에게 매번 약 140의 피해를 줍니다. 원거리 공격수는 25미터 밖에 머무르고, 근접 공격수는 시전 중에 빠져나오십시오.",
	["A 2-second cast: a hit, then Nature damage for a minute. Cure the poison."] = "2초 시전: 공격을 가한 뒤 1분 동안 자연 피해를 입힙니다. 독을 해독하십시오.",
	["A 2-second cast: arcane power drains up to 200 mana from everyone within 45 yards of him."] = "시전 시간 2초. 비전의 힘으로 주위 45미터 내의 모두에게서 마나를 최대 200까지 흡수합니다.",
	["A 3-second Shadow bolt on the tank, over and over. Interrupt it."] = "방어 전담에게 3초짜리 암흑 화살을 계속 시전합니다. 차단하십시오.",
	["A Better Ingredient"] = "더욱 강력한 재료",
	["A Binding Contract"] = "대장조합 계약서",
	["A Blackrock orc who can be found in one of four cells."] = "검은바위부족 오크로, 네 개의 감방 중 한 곳에서 찾을 수 있습니다.",
	["A Broken Trap"] = "부서진 함정",
	["A Crumpled Up Note"] = "꼬깃꼬깃한 쪽지",
	["A Crumpled Up Note, dropped by foes inside the dungeon"] = "꼬깃꼬깃한 쪽지, 던전 내부의 적에게서 획득",
	["A Curious Pair"] = "기묘한 한 쌍",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "탄돌 교각 습격에 가담하여 수감된 검은무쇠단 드워프입니다.",
	["A Dull and Flat Elven Blade"] = "납작하고 무딘 엘프 검",
	["A dust storm hits the whole group now and then, and he slows the tank."] = "이따금 먼지 폭풍으로 파티 전체를 공격하고, 방어 전담을 느려지게 합니다.",
	["A Dynamite Plan"] = "다이너마이트 작전",
	["A fallen paladin who heals himself and shields himself from harm."] = "자신을 치유하고 보호막으로 피해를 막는 타락한 성기사입니다.",
	["A Fanglord who turns into a serpent partway through the fight."] = "전투 도중 뱀으로 변신하는 송곳니의 드루이드 우두머리입니다.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "용암 호수 한가운데에 서 있는 지옥수호병으로, 이곳의 우두머리 중 가장 강하게 공격합니다.",
	["A Fine Mess"] = "곤경에 빠진 케르노비",
	["A Frightened Request"] = "겁에 질린 부탁",
	["A giant turtle in the first great pool."] = "첫 번째 큰 웅덩이에 있는 거대한 거북입니다.",
	["A giant turtle that will not attack first; killing him is optional."] = "먼저 공격하지 않는 거대한 거북입니다. 처치하지 않아도 됩니다.",
	["A Green Sample"] = "녹색 견본",
	["A Grim Fate"] = "암울한 운명",
	["A heavy blow that knocks the tank back."] = "방어 전담을 뒤로 밀쳐내는 강력한 일격입니다.",
	["A heavy swing at everyone in front of him. Only the tank should stand there."] = "앞에 있는 모두를 향해 무겁게 휘두릅니다. 방어 전담만 정면에 서야 합니다.",
	["A hidden elite you summon yourself."] = "직접 소환해야 하는 숨겨진 정예 몬스터입니다.",
	["A Host of Evil"] = "악의 무리",
	["A huge violet raptor, the leader of Stalker's Thicket."] = "추적자의 숲을 이끄는 거대한 보랏빛 랩터입니다.",
	["A large health pool"] = "많은 생명력",
	["A lightning bolt that jumps to a second player. Interrupt it."] = "다른 플레이어 한 명에게 옮겨 가는 번개입니다. 차단하십시오.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "죽음의 손짓은 발동하기 전에 마법사나 드루이드가 해제할 수 있습니다. 공포를 걸며, 생명력이 절반 아래로 떨어지면 플레이어 둘의 생명력을 흡수합니다.",
	["A mage quest. The Obsidian Sentinel inside Uldaman carries the power source."] = "마법사 퀘스트입니다. 울다만 내부의 흑요석 파수꾼이 마력원천을 지니고 있습니다.",
	["A mage trainer in a capital"] = "대도시의 마법사 상급자",
	["A magic debuff on the tank: around 65 Arcane damage every 2 seconds for 10 seconds. Dispel it."] = "방어 전담에게 거는 마법 약화 효과로, 10초 동안 2초마다 약 65의 비전 피해를 줍니다. 해제하십시오.",
	["A magic dispel removes his Shadow Word: Pain."] = "어둠의 권능: 고통은 마법 해제로 제거할 수 있습니다.",
	["A massive plant creature; optional."] = "거대한 식물 괴물입니다. 처치하지 않아도 됩니다.",
	["A Moon-Kissed Blade"] = "달빛이 깃든 검",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "자신의 제단에 있는 멀록 족장입니다. 추종자들은 생명력이 낮아지면 도움을 청하러 도망치므로 끝까지 처치하십시오.",
	["A naga sorceress in a side cavern off the pool; optional."] = "웅덩이 옆 동굴에 있는 나가 여마법사입니다. 처치하지 않아도 됩니다.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Jordan's Smithing Hammer, picked up from Jordan's Hammer in the courtyard. The rest: Whitestone Oak Lumber in the Deadmines, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "인간과 드워프 성기사 퀘스트로, 여러 곳에서 재료를 모아야 합니다. 이곳에서는 안뜰에 있는 조던의 망치에서 조던의 대장장이 망치를 얻습니다. 나머지는 죽음의 폐광의 흰돌참나무 재목, 검은심연 나락의 코르석, 모단 호수의 조던의 광석 상자입니다.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The rest: Jordan's Smithing Hammer in Shadowfang Keep, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "인간과 드워프 성기사 퀘스트로, 여러 곳에서 재료를 모아야 합니다. 이곳에서는 고블린 목공이 떨어뜨리는 흰돌참나무 재목을 얻습니다. 나머지는 그림자송곳니 성채의 조던의 대장장이 망치, 검은심연 나락의 코르석, 모단 호수의 조던의 광석 상자입니다.",
	["A patrol"] = "순찰 무리",
	["A Pawn on the Eternal Board"] = "장기판 위의 졸",
	["A pillar of flame where a player stands (3-second cast): Fire damage, then more every 3 seconds for 9 seconds. Step out of it."] = "플레이어가 서 있는 곳에 불기둥을 일으킵니다(시전 시간 3초). 화염 피해를 준 뒤 9초 동안 3초마다 추가 피해를 줍니다. 그 자리에서 벗어나십시오.",
	["A player takes more Physical damage for 10 minutes (2-second cast). A mage or a druid can remove it."] = "10분 동안 플레이어 한 명이 받는 물리 피해가 증가합니다(시전 시간 2초). 마법사나 드루이드가 해제할 수 있습니다.",
	["A Portable Power Source"] = "휴대용 에너지원",
	["A priest or a shaman can remove his Bloodlust."] = "피의 욕망은 사제나 주술사가 해제할 수 있습니다.",
	["A quilboar geomancer close to the Kraul's entrance."] = "가시덩굴 우리 입구 가까이에 있는 멧돼지인간 흙점쟁이입니다.",
	["A raid new in WoW: Forever, on Mount Hyjal. Its bosses and loot are not known yet."] = "월드 오브 워크래프트: 포에버에 새로 추가된 하이잘 산의 공격대입니다. 우두머리와 전리품은 아직 알려지지 않았습니다.",
	["A raid new in WoW: Forever. Its bosses and loot are not known yet."] = "월드 오브 워크래프트: 포에버에 새로 추가된 공격대입니다. 우두머리와 전리품은 아직 알려지지 않았습니다.",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "서슬깃 차를가 근처에 있는 박쥐 동굴 벽의 작게 움푹 들어간 곳에 있는 희귀 박쥐입니다. 매번 만날 수 있는 것은 아닙니다.",
	["A rare bat, not there on every run. When it is, it waits in a small recess in the wall of the bat cave near Charlga Razorflank."] = "희귀 박쥐로, 매번 나타나지는 않습니다. 나타날 때는 서슬깃 차를가 근처에 있는 박쥐 동굴 벽의 작게 움푹 들어간 곳에서 기다리고 있습니다.",
	["A rare spawn: not every run meets him."] = "희귀 몬스터라서 매번 나타나지는 않습니다.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "희귀 몬스터라서 매번 만날 수 있는 것은 아닙니다. 생명력이 15%가 되면 도움을 청하러 도망칩니다.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "희귀 몬스터입니다. 바위 정령이 함께 싸웁니다. 번개 화살을 차단하고, 생명력이 15%가 되어 도움을 청하러 도망치기 전에 처치하십시오.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "희귀 몬스터입니다. 불타는 하수인 둘을 불러냅니다. 화염구를 차단하십시오. 화염 보호막은 사제나 주술사가 해제할 수 있습니다.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "희귀 몬스터입니다. 방어 전담의 방어도를 4분의 3만큼 깎으며, 생명력이 15%가 되면 도움을 청하러 달아납니다. 달아나기 전에 처치하십시오.",
	["A Reliquary of Purity"] = "정화의 성물함",
	["A satyr on the walkway above Jergosh's chamber."] = "제로쉬의 방 위쪽 통로에 있는 사티로스입니다.",
	["A Searing Blade warlock; clear the cultists around him first."] = "이글거리는 칼날단 흑마법사입니다. 주위의 이교도부터 처치하십시오.",
	["A Shifty Merchant"] = "별난 상인",
	["A Shred of Hope"] = "잔존하는 희망",
	["A Sign of Hope"] = "희망의 전조",
	["A slow heal (3.5 seconds) on himself or an ally. Interrupt it."] = "자신이나 아군에게 시전하는 느린 치유입니다(3.5초). 차단하십시오.",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "바위 정령이 곁에서 함께 싸웁니다. 번개 화살은 차단하십시오.",
	["A Stone Rumbler stands with him and fights at his side."] = "바위 정령이 함께 있다가 곁에서 싸웁니다.",
	["A storm of dust that hits the group for about 160 to 330 nature damage. Healers, be ready for it."] = "먼지 폭풍이 파티 전체에 약 160~330의 자연 피해를 줍니다. 치유 전담은 미리 대비하십시오.",
	["A Taste of Flame"] = "화염의 맛",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "방어 전담의 실력을 시험하는 우두머리입니다. 강하게 공격하고 무장을 해제시키며, 부정의 광기로 20초 동안 공격 속도가 75% 빨라집니다. 광기는 정화나 해제로 없애고, 방어 전담은 방패를 착용하십시오.",
	["A threshadon in the underwater cave; optional. He only melees."] = "수중 동굴에 있는 트레샤돈입니다. 처치하지 않아도 됩니다. 근접 공격만 합니다.",
	["A thunder lizard in the water; killing him is optional."] = "물속에 있는 천둥도마뱀입니다. 처치하지 않아도 됩니다.",
	["A Titan dig site above Whelgar's Excavation, caught out of time, where the Titans' constructs answer to no one now. Inside: the Lost Marsh, Stalker's Thicket, the Site of the Guardian and the Lost Dig Site."] = "웰가르의 발굴현장 위쪽에 있는 티탄의 발굴지로, 시간의 흐름에서 벗어난 이곳에서는 티탄의 피조물들이 더 이상 누구의 명령도 따르지 않습니다. 내부: 잃어버린 늪, 추적자의 숲, 수호자의 터, 잃어버린 발굴 현장.",
	["A titan site hidden in Un'Goro Crater, guarding secrets of the makers among the crater's dinosaurs."] = "운고로 분화구에 숨겨진 티탄의 유적으로, 분화구의 공룡들 사이에서 창조주의 비밀을 지키고 있습니다.",
	["A Titan vault buried under the Badlands, where Dark Iron dwarves and troggs dig for the secrets of the earthen, and the stone keeper Archaedas guards the deepest hall."] = "황야의 땅 아래 묻힌 티탄의 금고입니다. 검은무쇠 드워프와 트로그가 토석인의 비밀을 찾아 땅을 파헤치고 있으며, 바위 문지기 아카에다스가 가장 깊은 전당을 지키고 있습니다.",
	["A treant twisted by fel magic, among the Suffused Treants in the streets."] = "지옥 마력에 뒤틀린 나무정령으로, 거리의 마력 스민 나무정령들 사이에 있습니다.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "중앙 통로에 있는 트로그 난폭자입니다. 다른 무리가 끼어들지 않는다면 어렵지 않은 전투입니다.",
	["A troll city that sank into the ocean long ago has risen again, and naga, pirates and stranger things from the deep have claimed its streets."] = "오래전 바닷속으로 가라앉았던 트롤 도시가 다시 떠올랐습니다. 이제 나가와 해적, 그리고 심해에서 올라온 더 기이한 존재들이 그 거리를 차지하고 있습니다.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "통로를 순찰하는 황혼의 망치단 주술사입니다.",
	["A vast cavern under Desolace, sacred to the centaur, where Princess Theradras, daughter of Therazane, has fouled the waters and the resting place of Zaetar."] = "잊혀진 땅 아래에 펼쳐진 거대한 동굴로, 켄타우로스의 성지입니다. 테라제인의 딸 공주 테라드라스가 이곳의 물과 재타르의 안식처를 더럽혔습니다.",
	["A Vengeful Fate"] = "운명의 복수",
	["A Visit to Gregan"] = "그레간 방문",
	["A ward closes his cave. Kill the two Death's Head Ward Keepers standing in front of it: the ward goes down when both are dead."] = "결계가 그의 동굴을 막고 있습니다. 결계 앞에 서 있는 죽음의 머리교 문지기 둘을 처치하십시오. 둘 다 죽으면 결계가 사라집니다.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "결계가 그의 동굴을 봉인하고 있습니다. 그 앞에 있는 죽음의 머리교 문지기 둘을 처치하면 결계가 사라집니다.",
	["A warlock quest. The 3 Soran'ruk Fragments drop from Twilight Acolytes here; the Large Soran'ruk Fragment comes from Shadowfang Darksouls in Shadowfang Keep."] = "흑마법사 퀘스트입니다. 소랜루크 조각 3개는 이곳의 황혼의망치단 수행사제에게서 획득하고, 큰 소랜루크 조각은 그림자송곳니 성채의 그림자송곳니일족 검은영혼에게서 획득합니다.",
	["A way to remove a curse or cure a disease comes in handy. Otherwise an easy fight: clear the room before the pull."] = "저주를 해제하거나 질병을 치료할 수단이 있으면 유용합니다. 그 외에는 쉬운 전투이니 전투 개시 전에 방을 정리하십시오.",
	["A white crocolisk of the marsh."] = "늪에 사는 하얀 악어입니다.",
	["Abandoned Hope"] = "실망",
	["Abominable Creatures"] = "흉측한 피조물",
	["Abominable Head"] = "흉측한 머리",
	["About every 20 seconds he fears up to three players near him: a shaman's Tremor Totem helps. Late in the fight he enrages."] = "약 20초마다 주위의 플레이어를 최대 3명까지 공포에 빠뜨립니다. 주술사의 진동의 토템이 도움이 됩니다. 전투 후반에는 격노합니다.",
	["About every 20 seconds he roars and fears up to three players near him. A shaman's Tremor Totem helps."] = "약 20초마다 포효하여 주위의 플레이어를 최대 3명까지 공포에 빠뜨립니다. 주술사의 진동의 토템이 도움이 됩니다.",
	["About one run in three, one of the graveyard's three rares stands at one of six places: Azshir the Sleepless, the Fallen Champion or Ironspine."] = "대략 세 번에 한 번꼴로 묘지의 희귀 몬스터 셋 중 하나가 여섯 곳 중 한 곳에 나타납니다. 잠들지 않는 아즈쉬르, 타락한 용사, 무쇠해골입니다.",
	["About one run in three, one of the graveyard's three rares stands at one of the six places on the map: Azshir the Sleepless, Fallen Champion or Ironspine."] = "대략 세 번에 한 번꼴로 묘지의 희귀 몬스터 셋 중 하나가 지도의 여섯 곳 중 한 곳에 나타납니다. 잠들지 않는 아즈쉬르, 타락한 용사, 무쇠해골입니다.",
	["Above and Beyond"] = "뛰어난 존재",
	["Accept Rig Wars from Nogg first; you need not finish it. If Nogg no longer offers Rig Wars, abandon this quest and Rig Wars comes back. Leads to Gnomer-gooooone!, the goblins' transporter to Gnomeregan."] = "먼저 노그에게서 '기술 전쟁'을 수락하십시오. 완료할 필요는 없습니다. 노그가 더 이상 '기술 전쟁'을 주지 않으면 이 퀘스트를 포기하십시오. 그러면 '기술 전쟁'을 다시 받을 수 있습니다. 놈리건으로 가는 고블린 순간이동기를 쓸 수 있게 되는 '놈리거어어어언!'으로 이어집니다.",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "산성 물질 끼얹기로 주위의 모두에게 지속 피해를 입힙니다. 생명력이 절반 미만일 때 쓰는 치유를 차단하십시오. 생명력이 15%가 되면 도움을 청하러 달아납니다.",
	["Advisor Belgrum"] = "조언자 벨그룸",
	["Advisor Belgrum, Hall of Explorers, Ironforge"] = "조언자 벨그룸, 탐험가의 전당, 아이언포지",
	["Afadra Dunwall, Ironforge"] = "아파드라 던월, 아이언포지",
	["After 60 seconds, Shadow damage to the player (2-second cast). A mage or a druid can remove it before then."] = "60초 후 플레이어에게 암흑 피해를 줍니다(시전 시간 2초). 그 전에 마법사나 드루이드가 해제할 수 있습니다.",
	["After a 3-second cast, a beam comes out in front of it for 6 seconds and hits four times a second. Get out of its path as soon as the cast starts."] = "3초 동안 시전한 뒤, 6초 동안 정면으로 광선을 뿜어 초당 네 번 공격합니다. 시전이 시작되자마자 경로에서 벗어나십시오.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "전투가 끝나면 방의 금고를 여십시오. '중요한 가보'에 필요한 드워프 가보 약 24개와 '상호 이해 조약' 퀘스트를 시작하는 석판이 들어 있습니다.",
	["After the fight, open the vaults of the room: about 24 Dwarven Heirlooms for Important Heirlooms, and the tablet of The Treaty of Understanding."] = "전투가 끝나면 방의 금고를 여십시오. '중요한 가보'에 필요한 드워프 가보 약 24개와 '상호 이해 조약'의 석판이 들어 있습니다.",
	["Agmond's Fate"] = "아그몬드의 운명",
	["Aku'mai's Lair"] = "아쿠마이의 둥지",
	["Alba Fairmoon"] = "알바 페어문",
	["Alba Fairmoon gives it at Sentinel Hill at the end of her chain, after a trip to Stormwind for ten Coarse Dynamite for Sprite Jumpsprocket. The forge is in the foundry, where Gilnid is fought; she then waits at the dungeon's exit with the detonator."] = "알바 페어문이 연계 퀘스트 마지막에 감시의 언덕에서 줍니다. 그 전에 스톰윈드에 다녀와 스프라이트 점프스프로켓을 위해 일반 다이너마이트 10개를 마련해야 합니다. 용광로는 길니드와 싸우는 주물 공장에 있으며, 이후 알바 페어문이 기폭 장치를 들고 던전 출구에서 기다립니다.",
	["Alba Fairmoon, at the Deadmines' exit"] = "알바 페어문, 죽음의 폐광 출구",
	["Alba Fairmoon, at the Deadmines' exit, Westfall"] = "알바 페어문, 서부 몰락지대 죽음의 폐광 출구",
	["Alba Fairmoon, Sentinel Hill, Westfall"] = "알바 페어문, 서부 몰락지대 감시의 언덕",
	["Alcaz Island, Dustwallow Marsh"] = "알카즈 섬, 먼지진흙 습지대",
	["Alexi Barov, Tirisfal Glades"] = "알렉시 바로브, 티리스팔 숲",
	["Allegiance to the Old Gods"] = "고대 신들에 대한 충성",
	["Also needs your side's Bodley's Unfortunate Fate, after your class's Anthion's Parting Words."] = "자신의 직업에 맞는 안시온의 작별 인사를 마친 뒤 이어지는, 자기 진영의 보들리의 불행한 운명도 완료해야 합니다.",
	["Altar of Hakkar, inside the dungeon"] = "학카르 제단, 던전 내부",
	["Alterac Mountains"] = "알터랙 산맥",
	["Altered Beings"] = "변화된 생물",
	["Amongst the Ruins"] = "폐허 사이로",
	["Amulet of Secrets"] = "비밀의 아뮬렛",
	["An Alarming Request"] = "심상치 않은 부탁",
	["An Ambassador of Evil"] = "악의 사자",
	["An Ancient Grudge"] = "오래된 원한",
	["An arcane golem by the Magus Commerce Exchange, guarded by Angry Tomes. Its Malfunction hits everyone within 25 yards."] = "마법사 교역소 옆에 있는 비전 골렘으로, 성난 고서들이 지키고 있습니다. 기능 장애는 25미터 내의 모두에게 피해를 줍니다.",
	["An escort: Grark is held at the Blackrock fortress in the Burning Steppes."] = "호위 퀘스트: 그랄크는 불타는 평원의 검은바위 요새에 붙잡혀 있습니다.",
	["An ogre foreman with heavy armour who hits hard; the first boss inside."] = "두꺼운 갑옷을 입고 강력하게 공격하는 오우거 작업반장으로, 안에서 처음 만나는 우두머리입니다.",
	["An ogre stronghold packed with warriors, where the Twilight's Hammer has found willing allies."] = "전사들로 가득한 오우거 요새로, 황혼의 망치단이 기꺼이 손을 잡을 동맹을 찾아낸 곳입니다.",
	["An ogre who throws lightning that jumps between players."] = "플레이어 사이를 튀어 다니는 번개를 던지는 오우거입니다.",
	["An ooze soaked in radiation, in the Hall of Gears."] = "톱니바퀴의 전당에 있는, 방사능에 흠뻑 젖은 진흙괴물입니다.",
	["An orb flies to a random player and comes back to him. Anyone it passes through takes Arcane damage and is silenced for 6 seconds: don't stand between him and that player."] = "구슬이 무작위 플레이어에게 날아갔다가 그에게 되돌아옵니다. 구슬이 지나가는 길에 있던 플레이어는 비전 피해를 받고 6초 동안 침묵에 걸립니다. 그와 해당 플레이어 사이에 서지 마십시오.",
	["An Unholy Alliance"] = "사악한 동맹",
	["An Unsent Letter"] = "부치지 않은 편지",
	["Anachronos"] = "아나크로노스",
	["Ancient Equine Spirit"] = "고대 준마의 영혼",
	["Ancient Equine Spirit, inside the dungeon"] = "고대 준마의 영혼, 던전 내부",
	["Ancient Gurubashi Idol"] = "고대 구루바시 신상",
	["Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."] = "앤드류 브로넬이 혹한의 암네나르를 처치하고 그의 해골을 가져와 달라고 합니다.",
	["Andrew Brownell, Undercity"] = "앤드류 브로넬, 언더시티",
	["Angelas Moonbreeze"] = "안젤라스 문브리즈",
	["Angelas Moonbreeze, Feathermoon Stronghold, Feralas"] = "안젤라스 문브리즈, 페더문 요새, 페랄라스",
	["Angry Tomes"] = "성난 고서",
	["Angry Tomes come at you on the way to it. Kill them before you pull."] = "가는 길에 성난 고서들이 덤벼듭니다. 전투를 개시하기 전에 처치하십시오.",
	["Angry Tomes come out of the buildings as you approach: clear them before the fight."] = "다가가면 건물에서 성난 고서들이 나옵니다. 전투 전에 처치하십시오.",
	["Anthion Harmon"] = "안시온 하몬",
	["Anthion Harmon, Eastern Plaguelands"] = "안시온 하몬, 동부 역병지대",
	["Anthion's Old Friend"] = "안시온의 오랜 친구",
	["Anthion's Strange Request"] = "안시온의 이상한 부탁",
	["Anti-Magic Shield"] = "대마법 보호막",
	["Anti-Magic Shield guards him against spells for a while, and he hits hard: keep the tank topped up."] = "대마법 보호막으로 한동안 주문을 막아 내며, 공격이 강력합니다. 방어 전담의 생명력을 가득 채워 두십시오.",
	["Apothecary Zamah — Pools of Vision, Thunder Bluff"] = "연금술사 자마 — 썬더 블러프 예언의 웅덩이",
	["Apothecary Zamah, Thunder Bluff"] = "연금술사 자마, 썬더 블러프",
	["Apothecary Zinge, Undercity"] = "연금술사 진게, 언더시티",
	["Arcane Explosion"] = "신비한 폭발",
	["Arcane Refreshment"] = "신비의 원기 회복 주문",
	["Arcanite"] = "아케이나이트",
	["Arch Druid Hamuul Runetotem, Elder Rise, Thunder Bluff"] = "대드루이드 하뮬 룬토템, 썬더 블러프 장로의 봉우리",
	["Arch Druid Hamuul Runetotem, Thunder Bluff"] = "대드루이드 하뮬 룬토템, 썬더 블러프",
	["Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs."] = "대주교 베네딕투스가 가시덩굴 구릉에 있는 혹한의 암네나르를 처치해 달라고 합니다.",
	["Archbishop Benedictus, Stormwind City"] = "대주교 베네딕투스, 스톰윈드",
	["Archmage Modera opens the Portal to the Violet Chamber for the group: it leads to him."] = "대마법사 모데라가 파티를 위해 보랏빛 방으로 가는 차원문을 열어 줍니다. 그 차원문을 지나면 그에게 갈 수 있습니다.",
	["Archmage Tervosh, Dustwallow Marsh"] = "대마법사 테르보쉬, 먼지진흙 습지대",
	["Archmage Xylem, Azshara"] = "대마법사 실렘, 아즈샤라",
	["Ardin Grassman, inside Excavation Site: Wetlands"] = "아르딘 그라스만, 발굴 현장: 저습지 내부",
	["Area damage on the group, worse when many of you fight in melee."] = "파티에 광역 피해를 입히며, 근접 전투를 벌이는 인원이 많을수록 피해가 커집니다.",
	["Argent Guard Manados"] = "은빛경비병 마나도스",
	["Argent Guard Manados, Craftsmen's Terrace, Darnassus"] = "은빛경비병 마나도스, 다르나서스 장인의 정원",
	["Argent Guard Manados, Craftsmen's Terrace, Darnassus (55, 24)"] = "은빛경비병 마나도스, 다르나서스 장인의 정원 (55, 24)",
	["Argent Guard Thaelrid, inside Blackfathom Deeps"] = "은빛경비병 타엘리드, 검은심연 나락 안",
	["Arrives with three goblin helpers."] = "고블린 조수 셋을 데리고 나타납니다.",
	["Artist Renfray, Western Plaguelands"] = "화가 렌프레이, 서부 역병지대",
	["Arugal Must Die"] = "아루갈의 최후",
	["Arugal's Curse turns a player into a worgen who attacks their own group."] = "아루갈의 저주는 플레이어를 늑대인간으로 바꿔 자기 파티를 공격하게 만듭니다.",
	["Ascension..."] = "진급",
	["Assist Celebras the Redeemed while he creates the Scepter of Celebras."] = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.",
	["At 15% health he runs off to bring help. Finish him before he gets away."] = "생명력이 15%가 되면 도움을 청하러 달아납니다. 도망치기 전에 처치하십시오.",
	["At 30% health he attacks 30% faster for the rest of the fight."] = "생명력이 30%가 되면 전투가 끝날 때까지 공격 속도가 30% 빨라집니다.",
	["At 30% health he attacks 60% faster and hits harder for 2 minutes."] = "생명력이 30%가 되면 2분 동안 공격 속도가 60% 빨라지고 더 강하게 공격합니다.",
	["At 30% health he heals himself (3-second cast). Interrupt it."] = "생명력이 30%가 되면 자신을 치유합니다(시전 시간 3초). 차단하십시오.",
	["At 30% health he turns into a serpent: slower but heavier blows, and he starts putting players to sleep."] = "생명력이 30%가 되면 뱀으로 변신합니다. 공격은 느려지지만 더 묵직해지고, 플레이어를 잠재우기 시작합니다.",
	["At 60% health, and again at 40%, he attacks 60% faster and hits harder for 2 minutes."] = "생명력이 60%일 때와 40%일 때, 2분 동안 공격 속도가 60% 빨라지고 더 강하게 공격합니다.",
	["At 60%, 40% and 20% health his blows grow stronger."] = "생명력이 60%, 40%, 20%가 될 때마다 공격이 강해집니다.",
	["At 66% and again at 33% health he stomps, stunning everyone around him, then walks to his chest to change weapons."] = "생명력이 66%일 때와 다시 33%일 때 발을 굴러 주위의 모두를 기절시킨 뒤, 무기를 바꾸러 상자로 걸어갑니다.",
	["At 66% and again at 33% health he stuns everyone around him, then walks to his chest to change weapons."] = "생명력이 66%일 때와 다시 33%일 때 주위의 모두를 기절시킨 뒤, 무기를 바꾸러 상자로 걸어갑니다.",
	["At half health Divine Shield makes him immune for 12 seconds. He stuns with Hammer of Justice, and his aura hurts whoever strikes him in melee."] = "생명력이 절반이 되면 천상의 보호막으로 12초 동안 무적이 됩니다. 심판의 망치로 기절시키며, 그를 근접 공격하면 오라에 의해 피해를 입습니다.",
	["At half health he becomes immune to all damage and spells for 12 seconds."] = "생명력이 절반이 되면 12초 동안 모든 피해와 주문에 면역이 됩니다.",
	["At half health he calls two Defias Blackguards."] = "생명력이 절반이 되면 데피아즈단 검은자객 둘을 부릅니다.",
	["At half health he shuts himself in an Arcane Bubble for 8 seconds and casts it (5-second cast): heavy Fire damage to everyone within 30 yards. Get out of range before it goes off, then come back."] = "생명력이 절반이 되면 8초 동안 비전 거품 안에 들어가 시전합니다(시전 시간 5초). 30미터 내의 모든 대상에게 큰 화염 피해를 줍니다. 터지기 전에 범위 밖으로 나갔다가 다시 돌아오십시오.",
	["At half health she puts everyone in the room to sleep for up to 10 seconds, runs to Mograine and raises him. He heals her fully with Lay on Hands, and the two fight you together."] = "생명력이 절반이 되면 방 안의 모두를 최대 10초 동안 잠재우고 모그레인에게 달려가 그를 되살립니다. 모그레인은 신의 축복으로 그녀의 생명력을 완전히 회복시키고, 둘이 함께 공격해 옵니다.",
	["At half health she puts the room to sleep and raises Mograine, who heals her fully: the two fight together."] = "생명력이 절반이 되면 방 안의 모두를 잠재우고 모그레인을 되살립니다. 모그레인이 그녀의 생명력을 완전히 회복시키고, 둘이 함께 싸웁니다.",
	["At low health he fears the whole group: clear the room first, and bring a way to break fear."] = "생명력이 낮아지면 파티 전체에 공포를 겁니다. 먼저 방을 정리하고, 공포를 풀 수단을 챙기십시오.",
	["At the ritual circle in the sewers, with Kirin Tor Necromancers around him."] = "하수구의 의식 마법진에 있으며, 주위에 키린 토 강령술사들이 있습니다.",
	["At the ritual circle in the Underbelly, among Kirin Tor Necromancers and rising skeletons. He disarms his target."] = "마법의 뒤안길의 의식 마법진에서 키린 토 강령술사들과 되살아나는 해골들 사이에 있습니다. 대상을 무장 해제시킵니다.",
	["Atal'ai Exile, The Hinterlands"] = "추방된 아탈라이트롤, 동부 내륙지",
	["Athenaeum"] = "도서관",
	["Attunement to the Core"] = "심장부와의 조화",
	["Auberdine"] = "아우버다인",
	["Auld Stonespire — Thunder Bluff"] = "아울드 스톤스파이어 — 썬더 블러프",
	["Auld Stonespire, Thunder Bluff"] = "아울드 스톤스파이어, 썬더 블러프",
	["Aurius' Reckoning"] = "아우리우스의 복수",
	["Aurius, inside Stratholme"] = "아우리우스, 스트라솔름 내부",
	["Awbee, inside the dungeon"] = "아우비, 던전 내부",
	["Azj'Tordin, Feralas"] = "아즈토르딘, 페랄라스",
	["Back to Uldaman"] = "울다만으로 돌아가기",
	["Badlands"] = "황야의 땅",
	["Badlands Reagent Run"] = "황야의 땅에서 재료 찾기",
	["Baelog, inside Uldaman"] = "밸로그, 울다만 내부",
	["Baron Aquanis"] = "군주 아쿠아니스",
	["Baron Silverlaine's keep above Pyrewood fell to Archmage Arugal, who summoned the worgen to fight the Scourge and lost control of them. Now the keep belongs to Arugal and his pack."] = "장작나무 마을 위에 자리한 남작 실버레인의 성채는 대마법사 아루갈의 손에 넘어갔습니다. 아루갈은 스컬지와 싸우려고 늑대인간을 소환했지만 그들을 통제하지 못했습니다. 이제 성채는 아루갈과 그의 무리가 차지하고 있습니다.",
	["Baros Alexston, City Hall, Cathedral Square, Stormwind"] = "바로스 알렉스턴, 스톰윈드 대성당 광장 시청",
	["Barov Family Fortune"] = "바로브 가의 유산",
	["Bashana Runetotem — Elder Rise, Thunder Bluff"] = "바샤나 룬토템 — 썬더 블러프 장로의 봉우리",
	["Bashana Runetotem, Elder Rise, Thunder Bluff"] = "바샤나 룬토템, 썬더 블러프 장로의 봉우리",
	["Bath'rah the Windwatcher"] = "바람의감시자 바스라",
	["Bath'rah the Windwatcher, Alterac Mountains"] = "바람의감시자 바스라, 알터랙 산맥",
	["Bazil Thredd"] = "바질 스레드",
	["Behind the furbolg gates in the far north of Azshara lies one of the largest furbolg dens, and something is corrupting it from the depths."] = "아즈샤라 최북단의 펄볼그 관문 너머에는 가장 큰 펄볼그 소굴 중 하나가 있으며, 무언가가 그 깊은 곳에서부터 소굴을 타락시키고 있습니다.",
	["Bell of Dethmoora"] = "데스무라의 종",
	["Belnistrasz's Brazier, inside Razorfen Downs"] = "벨리스트라즈의 화로, 가시덩굴 구릉 내부",
	["Belnistrasz, inside Razorfen Downs"] = "벨리스트라즈, 가시덩굴 구릉 내부",
	["Below 30% health he attacks faster for the rest of the fight."] = "생명력이 30% 아래로 떨어지면 전투가 끝날 때까지 공격 속도가 빨라집니다.",
	["Below 30% health: bursts of attacks 75% faster, over and over."] = "생명력 30% 미만: 공격 속도가 75% 빨라지는 효과가 반복해서 발동합니다.",
	["Below 75% health he heals himself, and the heal jumps to two allies near him (2.5-second cast). Interrupt it."] = "생명력이 75% 아래로 떨어지면 자신을 치유하며, 치유 효과가 근처의 아군 둘에게 튑니다(시전 시간 2.5초). 차단하십시오.",
	["Below half health he drains a player and the player nearest to them for 12 seconds, and heals himself."] = "생명력이 절반 아래로 떨어지면 12초 동안 플레이어 하나와 그에게 가장 가까운 플레이어의 생명력을 흡수해 자신을 치유합니다.",
	["Below half health he heals himself (2-second cast). Interrupt it."] = "생명력이 절반 미만이 되면 자신을 치유합니다(2초 시전). 차단하십시오.",
	["Below half health the faces come faster, and his Knock Away hits everyone around him."] = "생명력이 절반 아래로 떨어지면 얼굴 장치가 더 빨리 작동하며, 날려버리기가 주위의 모든 대상에게 적중합니다.",
	["Bena Winterhoof, Thunder Bluff"] = "베나 윈터후프, 썬더 블러프",
	["Beneath Ironforge, Dun Morogh"] = "던 모로 아이언포지 지하",
	["Beneath Ironforge, someone has broken into the tomb of the dwarven kings."] = "아이언포지 지하에서 누군가 드워프 왕들의 무덤에 침입했습니다.",
	["Beneath Moonbrook lie the gold mines Stormwind abandoned during the First War. Edwin VanCleef's Defias Brotherhood has made them its stronghold, and deep inside, in a hidden sea cave, his crew is finishing a warship meant for Stormwind."] = "문브룩 지하에는 1차 대전쟁 때 스톰윈드가 버린 금광이 있습니다. 에드윈 밴클리프의 데피아즈단이 이곳을 근거지로 삼았으며, 깊숙한 곳의 숨겨진 바다 동굴에서는 그의 일당이 스톰윈드를 노린 전함을 완성해 가고 있습니다.",
	["Beneath Orgrimmar's Cleft of Shadow runs a chasm of lava and stone where troggs, fire elementals and the Searing Blade, a cult of demon-worshippers, have taken root under the Horde's capital."] = "오그리마 어둠의 틈 아래로는 용암과 바위로 이루어진 협곡이 뻗어 있습니다. 호드의 수도 밑에 트로그와 불의 정령, 그리고 악마를 숭배하는 이교 집단인 이글거리는 칼날단이 자리를 잡았습니다.",
	["Betina Bigglezink"] = "베티나 비글징크",
	["Betina Bigglezink, Eastern Plaguelands"] = "베티나 비글징크, 동부 역병지대",
	["Bijou's Belongings"] = "비쥬의 물건들",
	["Bijou's Reconnaissance Report"] = "비쥬의 정찰 보고",
	["Bijou, inside Lower Blackrock Spire"] = "비쥬, 검은바위 첨탑 하층 내부",
	["Bijou, inside the dungeon"] = "비쥬, 던전 내부",
	["Blackfathom Villainy"] = "검은심연의 음모",
	["Blackhand's Command"] = "블랙핸드의 명령서",
	["Blackhand's Command, dropped by the Scarshield Quartermaster in Blackrock Mountain"] = "블랙핸드의 명령서, 검은바위 산의 방패부대 병참장교에게서 획득",
	["Blackrock Mountain"] = "검은바위 산",
	["Blasts everyone nearby with arcane energy."] = "비전 기운을 터뜨려 주위의 모두에게 피해를 입힙니다.",
	["Blessed Arcanite Barding"] = "축복받은 아케이나이트 마갑",
	["Blisters on The Land"] = "대지의 상처",
	["Blood in the Streets"] = "피로 물든 거리",
	["Blood of Morphaz"] = "몰파즈의 피",
	["Blood of the Black Dragon Champion"] = "검은용 용사의 피",
	["Blood Tinged Skies"] = "핏빛 하늘",
	["Blood-Stained Parchment"] = "피로 얼룩진 양피지",
	["Blood-Stained Parchment, found inside Ruins of Lordaeron"] = "피로 얼룩진 양피지, 로데론의 폐허 안에서 발견",
	["Bloodied Insignia"] = "피투성이 휘장",
	["Bloodpetal Poison"] = "붉은꽃잎 독",
	["Bloodpetal Zapper"] = "붉은꽃잎 구제장치",
	["Blueleaf Tubers"] = "청엽수 줄기",
	["Booty Bay"] = "무법항",
	["Borstan — The Drag, Orgrimmar"] = "보르스탄 — 오그리마 골목길",
	["Borstan, The Drag, Orgrimmar"] = "보르스탄, 오그리마 골목길",
	["Bounding Mana flies to a player and back, silencing anyone it passes through: don't stand between him and its target. Casters stay 20 yards away from his Arcane Explosion."] = "튕기는 마나는 플레이어에게 날아갔다가 되돌아오며, 지나가는 길에 있는 모두를 침묵시킵니다. 우두머리와 그 대상 사이에 서지 마십시오. 주문시전자는 신비한 폭발을 피해 20미터 떨어져 있으십시오.",
	["Bring 1 pile of Kraul Guano from the Kraul bats to Master Apothecary Faranell."] = "동굴박쥐에게서 얻은 가시덩굴 조분석 1개를 수석 연금술사 파라넬에게 가져가야 합니다.",
	["Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge."] = "아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다.",
	["Bring 12 Magenta Fungus Caps from inside Uldaman to Jarkal Mossmeld in Kargath."] = "울다만 내부에서 자홍버섯 12개를 구해 카르가스에 있는 자칼 모스멜드에게 가져가야 합니다.",
	["Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar."] = "자홍버섯 12개를 텔사마에 있는 가크 힐터치에게 가져가야 합니다.",
	["Bring 20 Deviate Hides to Nalpak."] = "돌연변이 통가죽 20개를 날팍에게 가져가야 합니다.",
	["Bring 20 Hearts of Zeal from the Scarlet Monastery to Master Apothecary Faranell."] = "붉은십자군 수도원에서 열정의 증거 20개를 모아 수석 연금술사 파라넬에게 가져가야 합니다.",
	["Bring 20 Hearts of Zeal to Master Apothecary Faranell in the Undercity."] = "열정의 증거 20개를 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다.",
	["Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan."] = "트롤 경화제 20병을 가젯잔에 있는 트렌튼 라이트해머에게 가져가야 합니다.",
	["Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul."] = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다.",
	["Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan."] = "돌조각 단지 4개를 모단 호수에 있는 발굴조사단장 아이언밴드에게 가져가야 합니다.",
	["Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths."] = "검은바위 나락에 있는 지배인 나그마라에게 그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 가져가야 합니다.",
	["Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan."] = "온전한 왕쇠똥구리 껍질 5개를 가젯잔에 있는 트란렉에게 가져가야 합니다.",
	["Bring 6 Wailing Essence to Mebok Mizzyrix."] = "통곡의 정수 6개를 메보크 미지릭스에게 가져가야 합니다.",
	["Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes."] = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 수집한 용의 알 8개와 수집전자 모듈을 가져가야 합니다.",
	["Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."] = "덴트리움 마법석 8개와 안알레움 마법석 8개를 황야의 땅에 있는 리글퍼즈에게 가져가야 합니다.",
	["Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge."] = "아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다.",
	["Bring Ambassador Malcin's Head to Varimathras in the Undercity."] = "언더시티에 있는 바리마트라스에게 사절 말킨의 머리카락을 가져가야 합니다.",
	["Bring Ashlam Valorfist voodoo feathers from the temple's troll leaders."] = "신전의 트롤 우두머리들에게서 부두 깃털을 모아 아쉬람 발러피스트에게 가져가야 합니다.",
	["Bring Bath'rah voodoo feathers from the temple's troll leaders."] = "신전의 트롤 우두머리들에게서 부두 깃털을 모아 바스라에게 가져가야 합니다.",
	["Bring Bodley 40 Blackrock Bracers, taken from the orcs of Blackrock Spire, and a Flask of Supreme Power."] = "검은바위 첨탑의 오크에게서 얻은 검은바위 팔보호구 40개와 강력한 마력의 영약 1개를 보들리에게 가져가야 합니다.",
	["Bring Bodley the Incendicite of Incendius (Lord Incendius, Blackrock Depths), the Ember of Emberseer (Pyroguard Emberseer, Upper Blackrock Spire) and the Cinder of Cynders (the Duke of Cynders, Silithus), with a Hallowed Brazier."] = "인센디우스의 발연석(불의군주 인센디우스, 검은바위 나락), 엠버시어의 불씨(불의수호자 엠버시어, 검은바위 첨탑 상층), 불꽃 군주의 불꽃(불꽃의 군주, 실리더스)을 성스러운 화로와 함께 보들리에게 가져가야 합니다.",
	["Bring Daio 15 Satyr Blood from the Wildspawn satyrs of the Warpwood Quarter."] = "굽이나무 지구의 야생혈족 사티로스에게서 사티로스의 피 15개를 모아 다이오에게 가져가야 합니다.",
	["Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes."] = "불타는 평원에 있는 마야라 브라이트윙에게 파멸의 기념물을 가져가야 합니다.",
	["Bring five silver bars to Talvash del Kissel in Ironforge."] = "은괴 5개를 아이언포지에 있는 탈바쉬 델 키젤에게 가져가야 합니다.",
	["Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats."] = "가즈릴라의 전기 비늘을 소금 평원에 있는 위즐 브라스볼츠에게 가져가야 합니다.",
	["Bring High Potency Radioactive Fallout and the Heavy Leaden Collection Phial back to Ozzie. The fallout collapses quickly."] = "고농축 방사성 폐기물과 빈 대형 가연채집병을 오지에게 가져가야 합니다. 폐기물은 금방 붕괴합니다.",
	["Bring Impsy six voodoo feathers from the temple's troll leaders."] = "신전의 트롤 우두머리들에게서 부두 깃털 6개를 모아 임프시에게 가져가야 합니다.",
	["Bring Knot 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Thread and Ogre Tannin to get a Gordok Ogre Suit."] = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 오우거 타닌을 노트에게 가져가 고르독 오우거 위장복을 받아야 합니다.",
	["Bring Knot Thimblejack a Gordok Shackle Key to free him."] = "고르독 족쇄 열쇠를 노트 팀블잭에게 가져가 그를 풀어 주어야 합니다.",
	["Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas."] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다.",
	["Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache."] = "모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.",
	["Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands."] = "네크룸의 메달을 저주받은 땅에 있는 샤디우스 그림섀이드에게 가져가야 합니다.",
	["Bring Private Rocknot 2 Dark Iron Ale Mugs."] = "병사 락노트에게 검은무쇠단 에일 맥주잔 2개를 가져가야 합니다.",
	["Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff."] = "썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다.",
	["Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar."] = "탈라나르에 있는 팔핀델 웨이워더에게 차를가의 메달을 가져가야 합니다.",
	["Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes."] = "리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다.",
	["Bring Ridgewell's Crate to Remington Ridgewell in Stormwind."] = "스톰윈드에 있는 레밍턴 리지웰에게 리지웰의 상자를 가져가야 합니다.",
	["Bring Tabetha in Dustwallow Marsh an Obsidian Power Source."] = "흑요석 마력원천을 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.",
	["Bring Talvash a Mana Potion, Coal and Sweet Nectar to get a new Phial of Scrying."] = "탈바쉬에게 마나 물약, 석탄, 달콤한 과즙을 가져가 새 수정점의 유리병을 받아야 합니다.",
	["Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge."] = "아이언포지에 있는 수석땜장이 오버스파크에게 첨단로봇의 기억회로를 가져가야 합니다.",
	["Bring the Blood-Stained Letter to Orphan Matron Nightingale."] = "보육원 원장님 나이팅게일에게 피로 얼룩진 편지를 가져가야 합니다.",
	["Bring the Book of Ur from Shadowfang Keep to Keeper Bel'dugur."] = "그림자송곳니 성채에서 우르의 책을 찾아 관리인 벨두거에게 가져가야 합니다.",
	["Bring the book Rituals of Power, from the Library, to Tabetha in Dustwallow Marsh."] = "도서관에서 마력의 의식 책을 찾아 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.",
	["Bring the book to Lorekeeper Lydros in Dire Maul."] = "혈투의 전장에 있는 현자 리드로스에게 책을 가져가야 합니다.",
	["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar."] = "오그리마에 있는 노그에게 반짝이는 금반지, 은괴 1개, 태마노 1개, 30실버를 가져가야 합니다.",
	["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge."] = "아이언포지에 있는 탈바쉬 델 키젤에게 반짝이는 금반지, 은괴 1개, 태마노 1개, 30실버를 가져가야 합니다.",
	["Bring the Crest of Lordaeron to the Undercity."] = "로데론의 문장을 언더시티로 가져가야 합니다.",
	["Bring the Damp Note to Je'neu Sancrea in Ashenvale."] = "잿빛 골짜기에 있는 제네우 생크리에게 축축한 쪽지를 가져가야 합니다.",
	["Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath."] = "카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다.",
	["Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan."] = "자동 탐사막대를 가젯잔에 있는 선임기술자 빌지위즐에게 가져가야 합니다.",
	["Bring the End"] = "암네나르 처치",
	["Bring the Fallen Hero of the Horde voodoo feathers from the temple's troll leaders."] = "신전의 트롤 우두머리들에게서 부두 깃털을 모아 호드 영웅의 넋에게 가져가야 합니다.",
	["Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris."] = "다섯번째 모쉬아루 서판과 여섯번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에게 가져가야 합니다.",
	["Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris."] = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다.",
	["Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris."] = "첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 타나리스에 있는 예킨야에게 가져가야 합니다.",
	["Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards."] = "혈투의 전장에 있는 팔린 트리셰이퍼에게 다음 물품을 가져가야 합니다: 엘드레스 영혼의 정수 1개, 암흑의 룬 4개, 눈부신 큰 결정 8개.",
	["Bring the Frozen Eggs to Betina Bigglezink."] = "베티나 비글징크에게 얼어붙은 알을 가져가야 합니다.",
	["Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane."] = "코브란의 보석, 아나콘드라의 보석, 피타스의 보석, 서펜티스의 보석을 나라 와일드메인에게 가져가야 합니다.",
	["Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."] = "불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다.",
	["Bring the Libram of Focus, a Pristine Black Diamond, 4 Large Brilliant Shards and 2 Skin of Shadow to Lorekeeper Lydros for an Arcanum of Focus."] = "집중의 영석을 받으려면 집중의 성서와 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 4개, 어둠의 허물 2개를 현자 리드로스에게 가져가야 합니다.",
	["Bring the Libram of Protection, a Pristine Black Diamond, 2 Large Brilliant Shards and a Frayed Abomination Stitching to Lorekeeper Lydros for an Arcanum of Protection."] = "보호의 영석을 받으려면 보호의 성서와 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 닳아해진 누더기골렘 조각 1개를 현자 리드로스에게 가져가야 합니다.",
	["Bring the Libram of Rapidity, a Pristine Black Diamond, 2 Large Brilliant Shards and 2 Blood of Heroes to Lorekeeper Lydros for an Arcanum of Rapidity."] = "신속의 영석을 받으려면 신속의 성서와 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 영웅의 피 2개를 현자 리드로스에게 가져가야 합니다.",
	["Bring the Light"] = "빛의 힘",
	["Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos."] = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다.",
	["Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath."] = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가야 합니다.",
	["Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."] = "이상한 물구슬을 잿빛 골짜기 조람가르 전초기지에 있는 제네우 생크리에게 가져가야 합니다.",
	["Bring the Tablet of Ryun'eh to Theldurin the Lost."] = "류네의 서판을 실성한 텔두린에게 가져가야 합니다.",
	["Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh."] = "심연의 티아라를 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.",
	["Bring the Titan Relic to Prospector Whelgar at his excavation in the Wetlands."] = "티탄의 유물을 저습지의 발굴현장에 있는 발굴조사단장 웰가르에게 가져가야 합니다.",
	["Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston."] = "툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.",
	["Bring Torwa Pathfinder a Putrid Vine from Atal'alarion, the guardian at the bottom of the Sunken Temple."] = "가라앉은 사원 하층부의 수호병 아탈알라리온에게서 썩은 덩굴을 얻어 토르와 패스파인더에게 가져가야 합니다.",
	["Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind."] = "스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다.",
	["Bring Ysida's Locket to Anthion Harmon in the Eastern Plaguelands."] = "동부 역병지대에 있는 안시온 하몬에게 이시다의 펜던트를 가져가야 합니다.",
	["Brohann Caskbelly, Stormwind City"] = "브로한 캐스크벨리, 스톰윈드",
	["Broken Trap, inside Dire Maul"] = "부서진 함정, 혈투의 전장 내부",
	["Broodling Essence"] = "새끼용의 정수",
	["Brother Sarno, Stormwind City"] = "수사 세르노, 스톰윈드",
	["Brutal Armor"] = "투사의 방어구",
	["Burns a player, then Fire damage every few seconds for 21 seconds. Interrupt the cast or dispel the burn."] = "플레이어를 불태운 뒤 21초 동안 몇 초마다 화염 피해를 입힙니다. 시전을 차단하거나 화상 효과를 해제하십시오.",
	["By the entrance to the Violet Hold. Clear his room first: anything still alive in it joins the fight."] = "보랏빛 요새 입구 옆에 있습니다. 먼저 그의 방을 정리하십시오. 살아남은 적은 모두 전투에 합류합니다.",
	["Caitlin Grassman, Menethil Harbor"] = "케이틀린 그라스만, 메네실 항구",
	["Caitlin Grassman, Menethil Harbor, Wetlands"] = "케이틀린 그라스만, 저습지 메네실 항구",
	["Caitlin Grassman, Wetlands"] = "케이틀린 그라스만, 저습지",
	["Calls a Boar Spirit to fight beside him every 30 to 45 seconds (1.5-second cast). Kill each one before the next comes."] = "30~45초마다 멧돼지 정령을 불러내 함께 싸웁니다(시전 시간 1.5초). 다음 정령이 나오기 전에 처치하십시오.",
	["Calls Dupe Bugs to its side. Its Patch kills them and heals it."] = "복제 버그를 곁으로 불러냅니다. 패치로 복제 버그를 없애고 자신을 치유합니다.",
	["Calls for help"] = "도움 요청",
	["Calls two Burning Servants at the start of the fight."] = "전투가 시작되면 불타는 하수인 둘을 불러냅니다.",
	["Camp Mojache"] = "모자케 야영지",
	["Captain Kromcrush, inside Dire Maul"] = "대장 크롬크러쉬, 혈투의 전장 내부",
	["Captain Truman stands just inside the entrance."] = "대장 트루먼은 입구 바로 안쪽에 서 있습니다.",
	["Captain Truman, just inside Ruins of Lordaeron"] = "대장 트루먼, 로데론의 폐허 바로 안쪽",
	["Captain Truman, just inside Ruins of Lordaeron (left of the entrance)"] = "대장 트루먼, 로데론의 폐허 바로 안쪽 (입구 왼쪽)",
	["Carrion Grubbage"] = "청소부구더기",
	["Castpipe's Task"] = "캐스트파이프의 임무",
	["Cavindra, Desolace"] = "카빈드라, 잊혀진 땅",
	["Celebras the Redeemed, inside the dungeon"] = "회복된 셀레브라스, 던전 내부",
	["Cenarion Aid"] = "세나리온 의회 지원",
	["Centaur Pariah, Desolace"] = "켄타우로스 추방자, 잊혀진 땅",
	["Chamber of Atonement"] = "속죄의 방",
	["Changing Tastes"] = "달라진 입맛",
	["Charlga Razorflank drops the Tattered Note."] = "서슬깃 차를가에게서 너덜너덜한 쪽지를 획득할 수 있습니다.",
	["Chief Engineer Bilgewhizzle, Tanaris"] = "선임기술자 빌지위즐, 타나리스",
	["Chief Engineer Scooty"] = "선임기술자 스쿠티",
	["Chillwind Horns"] = "서리바람 키메라의 뿔",
	["Clear his room before the pull: a patrol walks by. His head is looted for Abominable Creatures and Unending Torment."] = "순찰 무리가 지나다니므로 전투 개시 전에 방을 정리하십시오. 그의 머리는 '흉측한 피조물'과 '끝없는 고통'에 쓰이는 전리품입니다.",
	["Clear his room before the pull: a patrol walks by. His head is looted for the quests Abominable Creatures and Unending Torment."] = "순찰 무리가 지나다니므로 전투 개시 전에 방을 정리하십시오. 그의 머리는 '흉측한 피조물'과 '끝없는 고통' 퀘스트에 쓰이는 전리품입니다.",
	["Clear the courtyard, click the statue and survive the waves: she comes after them."] = "안뜰을 정리하고 석상을 클릭한 뒤 몰려오는 적들을 버텨 내십시오. 그 뒤에 그녀가 나타납니다.",
	["Clear the cultists around him one group at a time before pulling him."] = "전투를 시작하기 전에 주변의 신도들을 한 무리씩 정리하십시오.",
	["Clear the house and the statue, click the fireplace and survive the waves. He comes after the last flesh golem."] = "집과 석상 주변을 정리하고 벽난로를 클릭한 뒤 몰려오는 적들을 버텨 내십시오. 마지막 살덩어리 골렘이 쓰러진 뒤에 그가 나타납니다.",
	["Clear the house and the statue, click the fireplace and survive the waves: he comes after the last flesh golem."] = "집과 석상 주변을 정리하고 벽난로를 클릭한 뒤 몰려오는 적들을 버텨 내십시오. 마지막 살덩어리 골렘 다음에 그가 나타납니다.",
	["Cleft of Shadow, Orgrimmar"] = "오그리마 어둠의 틈",
	["Click the Fathom Stone in the water and he rises from it. He casts Frostbolt from range, and Frost Nova roots those near him."] = "물속의 심연의 돌을 클릭하면 그 안에서 나타납니다. 멀리서 얼음 화살을 시전하며, 얼음 회오리로 주위의 대상을 묶습니다.",
	["Click the Fathom Stone in the water: he rises from it."] = "물속의 심연의 돌을 클릭하면 그 안에서 나타납니다.",
	["Coast of Stranglethorn Vale"] = "가시덤불 골짜기 해안",
	["Codex of Defense"] = "방어의 고서",
	["Collect 10 Bloodied Insignias."] = "피투성이 휘장 10개를 수집해야 합니다.",
	["Collect 10 Red Silk Bandanas from Defias inside the Deadmines."] = "죽음의 폐광 안의 데피아즈단에게서 붉은 비단 복면 10개를 수집해야 합니다.",
	["Collect 10 Red Wool Bandanas from Defias prisoners in The Stockade."] = "스톰윈드 지하감옥의 데피아즈단 죄수들에게서 붉은 양모 복면 10개를 모아야 합니다.",
	["Collect 10 Serpentbloom from Wailing Caverns."] = "통곡의 동굴에서 불뱀꽃 10개를 모아야 합니다.",
	["Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."] = "마라우돈에서 음영석 조각 10개를 모아 먼지진흙 습지대 해안의 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다.",
	["Collect 10 Shadowshard Fragments from the Shadowshard Rumblers and Smashers of Maraudon."] = "마라우돈의 우레의 음영석정령과 분쇄의 음영석정령에게서 음영석 조각 10개를 모아야 합니다.",
	["Collect 10 Twilight Pendants from Twilight's Hammer members in Blackfathom Deeps."] = "검은심연 나락의 황혼의 망치단원에게서 황혼의 펜던트 10개를 모아야 합니다.",
	["Collect 15 Theradric Crystal Carvings for Willow in Desolace."] = "잊혀진 땅에 있는 윌로우를 위해 트라드릭 수정 조각상 15개를 모아야 합니다.",
	["Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard."] = "스토나드에 있는 펠제룰에게 학카르의 우상 20개를 가져가야 합니다.",
	["Collect 20 Sapphires of Aku'Mai in Blackfathom Deeps."] = "검은심연 나락에서 아쿠마이의 사파이어 20개를 모아야 합니다.",
	["Collect 25 Intact Limbs within Ruins of Lordaeron."] = "로데론의 폐허에서 온전한 팔다리 25개를 수집해야 합니다.",
	["Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul."] = "혈투의 전장이나 검은바위 첨탑의 오우거에게서 오우거 전투 목걸이 25개를 모아 혈투의 전장 도서관에 있는 팔린 트리셰이퍼에게 돌아가야 합니다.",
	["Collect 4 Miners' Union Cards from undead miners in the tunnels outside the instance."] = "던전 밖 갱도에 있는 언데드 광부에게서 광부 조합의 명함 4장을 수집해야 합니다.",
	["Collect 4 Thicket Raptor Hides and take them to James Halloran in Menethil Harbor."] = "덤불랩터 가죽 4개를 모아 메네실 항구의 제임스 할로란에게 가져가야 합니다.",
	["Collect 5 samples of Atal'ai Haze from the Deep Lurkers, Murk Worms and Saturated Oozes of the Sunken Temple, then return to Muigin in Un'Goro Crater."] = "가라앉은 사원의 지하껍질괴물, 진흙미늘벌레, 축축한 수액괴물에게서 아탈라이 아지랑이 5개를 모은 후 운고로 분화구에 있는 무이긴에게 돌아가야 합니다.",
	["Collect 6 Cracked Sentry Cores from the constructs in Dalaran."] = "달라란의 마법 구조물에게서 금 간 보초병 핵 6개를 모아야 합니다.",
	["Collect 8 Corrupted Brain Stems from creatures in Blackfathom Deeps."] = "검은심연 나락의 몬스터에게서 변이된 뇌간 8개를 모아야 합니다.",
	["Collect 8 Dwarven Heirlooms from the Hall of Thanes."] = "영주의 전당에서 드워프 가보 8개를 수집해야 합니다.",
	["Collect Spells of Shadow and Incantations from the Nether inside Ragefire Chasm."] = "성난불길 협곡에서 어둠의 주문서와 황천의 마법서를 수집해야 합니다.",
	["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."] = "달라란 근처에 있는 대마법사 모데라의 환영을 위해 비전 티끌을 모아야 합니다.",
	["Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."] = "달라란에서 비전 티끌을 모아 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 가져가야 합니다.",
	["Collect the Head of the Baron in Ruins of Lordaeron."] = "로데론의 폐허에서 남작의 머리를 손에 넣어야 합니다.",
	["Collect the Highly Toxic Strain from Witherfang."] = "쇠퇴송곳니에게서 고독성 변종을 손에 넣어야 합니다.",
	["Collecting Memories"] = "기억을 더듬어...",
	["Collection of Goods"] = "마갑 재료 수집",
	["Combine the Top Half (King Gordok, Dire Maul North) and the Bottom Half (Goraluk Anvilcrack, Upper Blackrock Spire) of Advanced Armorsmithing: Volume I."] = "고급 방어구제작: I 하권(왕 고르독, 혈투의 전장: 고르독 광장)과 고급 방어구제작: I 상권(고랄루크 앤빌크랙, 검은바위 첨탑 상층)을 합쳐야 합니다.",
	["Comes after Allegiance to the Old Gods, the one the Damp Note starts."] = "축축한 쪽지로 시작하는 '고대 신들에 대한 충성' 퀘스트 다음에 이어집니다.",
	["Comes after Speak with Shoni."] = "쇼니와의 대화 퀘스트에 이어지는 퀘스트입니다.",
	["Commander Ashlam Valorfist, Chillwind Camp, Western Plaguelands"] = "사령관 아쉬람 발러피스트, 서리바람 야영지, 서부 역병지대",
	["Commander Gor'shak"] = "사령관 고르샤크",
	["Commander Gor'shak, inside Blackrock Depths"] = "사령관 고르샤크, 검은바위 나락 내부",
	["Compendium of the Fallen"] = "타락의 개요",
	["Components of Importance"] = "중요한 요소",
	["Confront Yeh'kinya"] = "예킨야와의 대면",
	["Consult Master Gadrin"] = "가드린 장로와 상의",
	["Corruption"] = "부패의 검",
	["Corruption of Earth and Seed"] = "대지와 씨앗의 오염",
	["Councilman Millstipe — Darkshire"] = "원로 밀스타이프 — 다크샤이어",
	["Councilman Millstipe, Darkshire, Duskwood"] = "원로 밀스타이프, 그늘숲 다크샤이어",
	["Count Remington Ridgewell, Stormwind City"] = "백작 레밍턴 리지웰, 스톰윈드",
	["Courser Antlers"] = "순록 뿔",
	["Cracked Sentry Cores drop from the Fragmented Sentries, one per sentry and one player each. A run has 12 to 15 of them, so a full group needs two or three runs."] = "금 간 보초병 핵은 파편화된 보초병에게서 획득하며, 보초병 하나당 하나씩 한 플레이어만 얻을 수 있습니다. 한 번 진행할 때 보초병이 12~15마리 있으므로, 파티 전원이 완료하려면 두세 번 진행해야 합니다.",
	["Crag of the Everliving"] = "영생의 바위굴",
	["Crane Operator Bigglefuzz"] = "기중기 기사 비글퍼즈",
	["Crane Operator Bigglefuzz, Ratchet, The Barrens"] = "기중기 기사 비글퍼즈, 불모의 땅 톱니항",
	["Crest of Lordaeron"] = "로데론의 문장",
	["Crier Goodman, Stormwind City"] = "포고꾼 굿맨, 스톰윈드",
	["Crime and Punishment"] = "죄와 벌",
	["Crocolisks in the marsh"] = "늪의 악어들",
	["Crowd Pummel hits and interrupts everyone near it: casters and healers, keep away. It also smashes in a cone and tramples."] = "고철 압축은 근처의 모든 대상을 공격하고 주문 시전을 방해합니다. 주문시전자와 치유 전담은 멀리 떨어지십시오. 전방 부채꼴 범위를 강타하고 밟아 뭉개기도 사용합니다.",
	["Cure his poison, which also drains mana."] = "마나도 흡수하는 독을 해제하십시오.",
	["Cure the poison of his harpoon; his Cleave hits beside the tank."] = "작살의 독을 해독하십시오. 회전베기는 방어 전담 옆에 있는 대상도 공격합니다.",
	["Curse of Weakness"] = "무력화 저주",
	["Curses a player: healing on them is 75% weaker for 15 seconds. Remove it, above all from the tank."] = "플레이어 한 명에게 저주를 걸어 15초 동안 받는 치유량을 75% 줄입니다. 특히 방어 전담에게서는 반드시 해제하십시오.",
	["Curses and diseases"] = "저주와 질병",
	["Curses and diseases: bring a way to remove them. Otherwise an easy fight; clear the room before the pull."] = "저주와 질병을 겁니다. 해제할 수단을 챙기십시오. 그 외에는 쉬운 전투이니 전투 개시 전에 방을 정리하십시오.",
	["Cuts the tank's armor by 75% for 20 seconds."] = "20초 동안 방어 전담의 방어도를 75% 감소시킵니다.",
	["Cyrus Therepentous, Burning Steppes"] = "키루스 테레펜터스, 불타는 평원",
	["Da Voodoo"] = "부두교 마법",
	["Daewyn is inside the dungeon. Fallen in the Fen then sends you back to Dorin Songblade in Lakeshire."] = "대윈은 던전 안에 있습니다. 이어서 '늪에서 쓰러지다' 퀘스트를 통해 레이크샤이어의 도린 송블레이드에게 돌아가게 됩니다.",
	["Daewyn Songblade, inside Excavation Site: Wetlands"] = "대윈 송블레이드, 발굴 현장: 저습지 내부",
	["Daio the Decrepit"] = "노쇠한 다이오",
	["Daio the Decrepit, The Tainted Scar, Blasted Lands"] = "노쇠한 다이오, 타락의 흉터, 저주받은 땅",
	["Dalar Dawnweaver"] = "달라 던위버",
	["Dalar Dawnweaver, The Sepulcher, Silverpine Forest"] = "달라 던위버, 은빛소나무 숲 공동묘지",
	["Dalaran"] = "달라란",
	["Dalaran Patrols"] = "달라란 순찰",
	["Dalaran, the city of the Kirin Tor, stands rebuilt in the Alterac Mountains, its magic barrier gone and its streets overrun. Go in through the sewers, to a portal at the end of a long pipe, then fight up through the streets to the Shade of the Archmage.\n\nImmunities: much of the city takes no Arcane damage. Constructs and elementals ignore bleeds and poisons, and the treants take no Nature damage, though they bleed.\n\nTrash: interrupt the Mana Phantoms' Mana Burn, and stand in the pool a Saturated Remnant leaves behind to regain mana. Every kill gives Kirin Tor reputation."] = "키린 토의 도시 달라란이 알터랙 산맥에 다시 세워졌지만, 마법 보호막은 사라지고 거리는 적들로 들끓고 있습니다. 하수구로 들어가 긴 배수관 끝에 있는 차원문을 지난 뒤, 거리를 뚫고 올라가 대마법사의 망령에게 가야 합니다.\n\n면역: 도시의 많은 적이 비전 피해를 받지 않습니다. 골렘 같은 피조물과 정령은 출혈과 독에 걸리지 않으며, 나무정령은 자연 피해를 받지 않지만 출혈에는 걸립니다.\n\n일반 몬스터: 마나 환영의 마나 연소를 차단하고, 포화된 잔재가 남기는 웅덩이에 서서 마나를 회복하십시오. 적을 처치할 때마다 키린 토 평판을 얻습니다.",
	["Damp Note"] = "축축한 쪽지",
	["Dark Iron Legacy"] = "검은무쇠단 유물",
	["Darkreaver's Fallen Charger, inside the dungeon"] = "다크리버 군마의 영혼, 던전 내부",
	["Data Rescue"] = "자료 회수",
	["Dawn's Gambit"] = "여명의 계략",
	["Dawnwatcher Selgorm, Darnassus"] = "새벽감시자 셀고름, 다르나서스",
	["Dawnwatcher Shaedlass"] = "새벽감시자 섀드라스",
	["Dawnwatcher Shaedlass, Craftsmen's Terrace, Darnassus"] = "새벽감시자 섀드라스, 다르나서스 장인의 정원",
	["Dead Man's Plea"] = "죽은 자의 부탁",
	["Deathguard Kristof — southeast of Brill"] = "죽음의경비병 크리스토프 — 브릴 남동쪽",
	["Deathguard Kristof, Brill"] = "죽음의경비병 크리스토프, 브릴",
	["Deathguard Kristof, Brill, Tirisfal Glades"] = "죽음의경비병 크리스토프, 티리스팔 숲 브릴",
	["Deathstalker Agent, above the Dragonmaw camp, Wetlands"] = "죽음의 추적자, 저습지 용아귀일족 야영지 위쪽",
	["Deathstalker Agent, in the hills above the Dragonmaw camp"] = "죽음의 추적자, 용아귀일족 야영지 위쪽 언덕",
	["Deathstalker Agent, just outside Excavation Site: Wetlands"] = "죽음의 추적자, 발굴 현장: 저습지 입구 바로 밖",
	["Deathstalker Vincent, inside Shadowfang Keep"] = "죽음의추적자 빈센트, 그림자송곳니 성채 안",
	["Deathstalkers in Shadowfang"] = "그림자송곳니 성채의 죽음의추적자",
	["Debilitate drains mana from everyone within 45 yards, and Drain Vitality wears down the tank: dispel it. A race before your mana runs out. He is immune to arcane."] = "쇠약은 45미터 내의 모두에게서 마나를 흡수하고, 활력 흡수는 방어 전담을 서서히 약화시키니 해제하십시오. 마나가 바닥나기 전에 끝내야 하는 싸움입니다. 비전 피해에 면역입니다.",
	["Defeat 2 Dragonmaw Saboteurs and 4 Dragonmaw Warders, recover the Dragonmaw Dispatch, and report to the Deathstalker Agent outside the dungeon."] = "용아귀일족 파괴공작원 2명과 용아귀일족 보초병 4명을 처치하고 용아귀일족 지령서를 회수한 뒤, 던전 밖의 죽음의 추적자에게 보고해야 합니다.",
	["Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran."] = "달라란 밖에 있는 대마법사 모데라를 위해 달라란 안에서 갈구하는 잔재 8마리, 포화된 잔재 8마리, 마나 메아리 8마리를 처치해야 합니다.",
	["Defeat Atrexis the Grave Knight in the Dalaran Underbelly."] = "달라란 마법의 뒤안길에서 무덤 기사 아트렉시스를 처치해야 합니다.",
	["Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans."] = "가시덩굴 우리에서 서슬깃 차를가를 처치하고 멧돼지인간의 계획에 관한 정보를 모아야 합니다.",
	["Defeat Edwin VanCleef and collect his head."] = "에드윈 밴클리프를 처치하고 밴클리프의 가면을 가져와야 합니다.",
	["Defeat Lorgus Jett in Blackfathom Deeps."] = "검은심연 나락에서 로구스 제트를 처치해야 합니다.",
	["Defeat Twilight Lord Kelris and recover the Head of Kelris."] = "황혼의 군주 켈리스를 처치하고 켈리스의 머리카락을 가져와야 합니다.",
	["Defeating him opens the door onward."] = "그를 쓰러뜨리면 다음으로 가는 문이 열립니다.",
	["Defend Commander Gor'shak."] = "사령관 고르샤크를 보호해야 합니다.",
	["Defias Hideout"] = "데피아즈단 은신처",
	["Deliver the Abominable Head to the Undercity."] = "흉측한 머리를 언더시티로 가져가야 합니다.",
	["Deliver the Gems"] = "보석 전달",
	["Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."] = "회수한 목걸이와 보석을 오그리마에 있는 드란 드로퍼스에게 전달해야 합니다.",
	["Deliver the Titan Relic to High Explorer Magellas in the Hall of Explorers."] = "티탄의 유물을 탐험가의 전당에 있는 선임탐험가 마겔라스에게 전달해야 합니다.",
	["Deliver the Titan Relic to Muln Earthfury on Skywatcher Plateau in northwest Mulgore."] = "티탄의 유물을 멀고어 북서쪽 하늘감시자 고원에 있는 멀른 어스퓨리에게 전달해야 합니다.",
	["Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge."] = "아이언포지에 있는 마그니 브론즈비어드에게 상호 이해 조약을 전달해야 합니다.",
	["Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge."] = "마샬의 야영지에 있는 라리온에게 충전 안 된 구제장치와 아탈라이 아지랑이 5개를 가져가야 합니다.",
	["Delivery to Ridgewell"] = "리지웰에게 가져가기",
	["Demon Dogs"] = "지옥개",
	["Desolace"] = "잊혀진 땅",
	["Destroy Morphaz"] = "몰파즈 처치",
	["Destroy the Black Guard Swordsmith in Stratholme and bring the Insignia of the Black Guard to Seril Scourgebane."] = "스트라솔름에서 검은호위대 검제작자를 처치하고 검은호위대 휘장을 세릴 스컬지베인에게 가져가야 합니다.",
	["Destruction in Deadmines"] = "죽음의 폐광 파괴 작전",
	["Detonation at a Distance"] = "원격 폭파",
	["Deviate Eradication"] = "돌연변이 짐승 섬멸",
	["Deviate Hides"] = "돌연변이 통가죽",
	["Dinita Stonemantle, the Vault, Ironforge"] = "디니타 스톤맨틀, 사설금고, 아이언포지",
	["Diplomatic Incident"] = "외교 문제",
	["Disarms the tank for 6 seconds."] = "6초 동안 방어 전담의 무장을 해제합니다.",
	["Disharmony of Fire"] = "불의 부조화",
	["Disharmony of Flame"] = "화염의 부조화",
	["Dispelling Evil"] = "악마 퇴치",
	["Divino-matic Rod"] = "자동 탐사막대",
	["Doan Karhan"] = "도안 카르한",
	["Doan Karhan, The Barrens"] = "도안 카르한, 불모의 땅",
	["Doctor Martin Felben — Undercity"] = "박사 마틴 펠벤 — 언더시티",
	["Doctor Martin Felben, Undercity"] = "박사 마틴 펠벤, 언더시티",
	["Doctor Theolen Krastinov, the Butcher"] = "도살자, 테올렌 크라스티노브",
	["Doomrigger's Clasp"] = "파멸의 기념물",
	["Doomsday Candle"] = "심판의 양초",
	["Dorin Songblade — Redridge Mountains"] = "도린 송블레이드 — 붉은마루 산맥",
	["Dorin Songblade, Lakeshire, Redridge Mountains"] = "도린 송블레이드, 붉은마루 산맥 레이크샤이어",
	["Dorin Songblade, Redridge Mountains"] = "도린 송블레이드, 붉은마루 산맥",
	["Dorn Plainstalker, Thousand Needles"] = "도른 플레인스토커, 버섯구름 봉우리",
	["Down the Scarlet Path"] = "붉은십자군의 길",
	["Dragonkin Menace"] = "용혈족의 위협",
	["Dragonmaw Rumors"] = "용아귀일족에 대한 소문",
	["Drains 350 mana from his target in melee: a tank with mana feels it."] = "근접 공격 시 대상의 마나를 350 흡수합니다. 마나를 쓰는 방어 전담에게는 부담이 됩니다.",
	["Drakefire Amulet"] = "비룡불꽃 아뮬렛",
	["Drakkisath's Brand, inside Upper Blackrock Spire"] = "드라키사스의 낙인, 검은바위 첨탑 상층 내부",
	["Dran Droffers, Orgrimmar"] = "드란 드로퍼스, 오그리마",
	["Dreadsteed of Xoroth"] = "소로스의 공포마",
	["Dreadsteed Spirit, inside the dungeon"] = "공포마 영혼, 던전 내부",
	["Dreamer's Rock"] = "꿈꾸는 자의 바위",
	["Dropped by Charlga Razorflank."] = "서슬깃 차를가에게서 획득합니다.",
	["Dropped by Dark Iron Agents in Gnomeregan."] = "놈리건의 검은무쇠단 첩보원에게서 획득합니다.",
	["Dropped by Overlord Wyrmthalak."] = "대군주 웜타라크에게서 획득합니다.",
	["Dropped by the Scarshield Quartermaster in Blackrock Mountain, outside the Spire."] = "검은바위 산의 첨탑 바깥에 있는 방패부대 병참장교에게서 획득합니다.",
	["Dropped by the Shade of Eranikus"] = "에라니쿠스의 사령에게서 획득",
	["Dropped by: Mutanus the Devourer"] = "획득처: 걸신들린 무타누스",
	["Dropped by: The Baron"] = "획득처: 남작",
	["Dropped by: undead enemies inside Ruins of Lordaeron"] = "획득처: 로데론의 폐허 안의 언데드 적",
	["Drops from Balnazzar inside Stratholme."] = "스트라솔름의 발나자르에게서 획득합니다.",
	["Drops from Baron Aquanis inside Blackfathom Deeps."] = "검은심연 나락 안의 군주 아쿠아니스에게서 획득합니다.",
	["Drops from Blackfathom Tide Priestess in the entrance tunnels leading to Blackfathom Deeps."] = "검은심연 나락 입구로 이어지는 통로의 검은심연의 바다여사제에게서 획득합니다.",
	["Drops from Charlga Razorflank in Razorfen Kraul."] = "가시덩굴 우리의 서슬깃 차를가에게서 획득합니다.",
	["Drops from foes all over Blackrock Depths."] = "검은바위 나락 곳곳의 적에게서 획득합니다.",
	["Drops from Plagued Hatchlings inside Scholomance."] = "스칼로맨스의 역병 걸린 작은 새끼용에게서 획득합니다.",
	["Drops the Titan Relic that starts each side's relic quest."] = "진영별 유물 퀘스트를 시작하는 티탄의 유물을 획득할 수 있습니다.",
	["Druids of the Cenarion Circle came to these caves to heal the land, but their leader Naralex fell into a nightmare. His disciples, the Druids of the Fang, have turned the caverns into a twisted den of deviate creatures."] = "세나리온 의회의 드루이드들은 대지를 치유하려고 이 동굴을 찾았지만, 그들의 지도자 나랄렉스는 악몽에 빠지고 말았습니다. 그의 제자들인 송곳니의 드루이드는 동굴을 뒤틀린 돌연변이 생물의 소굴로 바꿔 놓았습니다.",
	["Duke Hydraxis, Azshara"] = "군주 히드락시스, 아즈샤라",
	["Duke Nicholas Zverenhoff, Eastern Plaguelands"] = "공작 니콜라스 즈바른호프, 동부 역병지대",
	["Dun Morogh"] = "던 모로",
	["Duskwing, Oh How I Hate Thee..."] = "혐오스런 그늘날개",
	["Dustwallow Marsh"] = "먼지진흙 습지대",
	["Dwarven District"] = "드워프 지구",
	["Each go costs 3 silver."] = "한 번에 3실버가 듭니다.",
	["Earthen Echo"] = "대지의 메아리",
	["Earthseer Farsen, Dun Morogh (after Underground Map)"] = "대지예언자 파르센, 던 모로 ('지하 지도' 이후)",
	["Eastern Plaguelands"] = "동부 역병지대",
	["Ebru"] = "에브루",
	["Ebru, above the entrance to Wailing Caverns, The Barrens"] = "에브루, 불모의 땅 통곡의 동굴 입구 위",
	["Egan, Eastern Plaguelands"] = "에간, 동부 역병지대",
	["Egg Collection"] = "알 수집",
	["Egg Freezing"] = "알껍질 냉동",
	["Eitrigg's Wisdom"] = "아이트리그의 지혜",
	["Elder Knowledge"] = "장로의 지식",
	["Elemental Aid"] = "정령의 도움",
	["Elven Legends"] = "엘프의 전설",
	["Emberstrife"] = "엠버스트라이프",
	["Emissary Jacques in Southshore starts it with An Alarming Request. It gives the Dalaran Sewer Key, and Friend of the Kirin Tor follows, taking the mote to Archmage Celindra in the Violet Citadel. The mote drops from the Shade of the Archmage, the last boss."] = "사우스쇼어의 사절 자크가 '심상치 않은 부탁'으로 시작합니다. 이 퀘스트로 달라란 하수구 열쇠를 얻으며, 이어지는 '키린 토의 친구'에서 티끌을 보랏빛 성채의 대마법사 셀린드라에게 가져갑니다. 티끌은 마지막 우두머리인 대마법사의 망령이 떨어뜨립니다.",
	["Emphasis on Sacrifice"] = "희생의 중요성",
	["En-Ay-Es-Tee-Why"] = "더러운 거미알",
	["Enchanted Thorium Platemail"] = "마력깃든 토륨 갑옷",
	["Enchanted Thorium Platemail: Volume I"] = "마력깃든 토륨 갑옷 I",
	["Enchanted Thorium Platemail: Volume I, bound from its two halves"] = "마력깃든 토륨 갑옷 I, 상권과 하권을 합쳐 만든 책",
	["Encoded Fragments"] = "암호화된 페이지",
	["Enohar Thunderbrew, Blasted Lands"] = "에노하르 썬더브루, 저주받은 땅",
	["Entangle roots up to two players near him and hurts them: dispel it. Fel Timbers leaves poisonous pools: anyone rooted in one needs Blessing of Freedom or Escape Artist."] = "휘감기는 주위의 플레이어를 최대 2명까지 묶고 피해를 줍니다. 해제하십시오. 지옥 목재는 독성 웅덩이를 남깁니다. 웅덩이 안에서 묶인 플레이어에게는 자유의 축복이나 탈출의 명수가 필요합니다.",
	["Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."] = "검은바위 나락에 들어가 불의군주 인센디우스를 찾아, 그를 처치한 후 얻게 되는 모든 정보를 썬더하트에게 가져가야 합니다.",
	["Enter Hall of Thanes and claim Durgen Dirgehammer's Head."] = "영주의 전당에 들어가 드루겐 더지해머의 머리카락을 손에 넣어야 합니다.",
	["Enter the Excavation Sites in the Wetlands and bring back 4 Thicket Raptor Meat."] = "저습지의 발굴 현장에 들어가 덤불랩터 고기 4개를 가져와야 합니다.",
	["Eranikus, Tyrant of the Dream"] = "꿈의 폭군 에라니쿠스",
	["Escort Belnistrasz to the Quilboar's idol in Razorfen Downs."] = "가시덩굴 구릉에 있는 멧돼지인간의 우상까지 벨리스트라즈를 호위해야 합니다.",
	["Escort Kernobee to the Clockwerk Run exit, then report to Scooty in Booty Bay."] = "태엽장치 통로 출구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 보고해야 합니다.",
	["Escort Willix the Importer out of Razorfen Kraul."] = "수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.",
	["Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge."] = "포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다.",
	["Essence Font, inside the dungeon"] = "정수의 샘, 던전 내부",
	["Essence of Eranikus"] = "에라니쿠스의 정수",
	["Essential Artificials"] = "필수 인공장치",
	["Eva Sarkhoff, Western Plaguelands"] = "에바 사크호프, 서부 역병지대",
	["Every 15 to 25 seconds he spins for 10 seconds, hitting everyone near him. Melee, step back until it ends."] = "15~25초마다 10초 동안 회전하며 주위의 모든 대상을 공격합니다. 근접 공격수는 끝날 때까지 물러나십시오.",
	["Every 15 to 25 seconds he whirls for 10 seconds, hitting everyone near him: melee, step back until it ends."] = "15~25초마다 10초 동안 소용돌이를 일으켜 주위의 모든 대상을 공격합니다. 근접 공격수는 끝날 때까지 물러나십시오.",
	["Every 21 to 35 seconds he strikes a player other than his target, who falls as if dead and can neither attack nor cast. Moving ends it."] = "21~35초마다 대상이 아닌 플레이어 하나를 공격합니다. 맞은 플레이어는 죽은 듯이 쓰러져 공격도 주문 시전도 할 수 없습니다. 움직이면 풀립니다.",
	["Every 25 to 31 seconds: hits everyone near him and stuns them for 2.5 seconds."] = "25~31초마다: 근처의 모든 대상을 공격하고 2.5초 동안 기절시킵니다.",
	["Every 8 to 14 seconds: Nature damage to everyone near him, and their attacks and movement are slowed for 10 seconds."] = "8~14초마다: 근처의 모든 대상에게 자연 피해를 주고, 10초 동안 공격 속도와 이동 속도를 감소시킵니다.",
	["Every 9 to 15 seconds she is immune to all attacks and spells for 2 seconds."] = "9~15초마다 2초 동안 모든 공격과 주문에 면역이 됩니다.",
	["Every few seconds, Arcane damage to everyone within 10 yards. Ranged players, keep your distance."] = "몇 초마다 10미터 내의 모든 대상에게 비전 피해를 줍니다. 원거리 공격수는 거리를 유지하십시오.",
	["Exorcising Terrordale"] = "테러데일 퇴마",
	["Explosive Consultation"] = "폭발물 자문",
	["Extinguishing the Idol"] = "우상 진화",
	["Extra damage on the tank every 5 to 15 seconds."] = "5~15초마다 방어 전담에게 추가 피해를 입힙니다.",
	["Eye of the Emberseer"] = "엠버시어의 눈",
	["Falfindel Waywarder — Thalanaar"] = "팔핀델 웨이워더 — 탈라나르",
	["Falfindel Waywarder, Thalanaar, Feralas"] = "팔핀델 웨이워더, 탈라나르, 페랄라스",
	["Falla Sagewind, The Barrens"] = "팔라 세이지윈드, 불모의 땅",
	["Fallen Hero of the Horde, Swamp of Sorrows"] = "호드 영웅의 넋, 슬픔의 늪",
	["Fallen in the Fen"] = "늪에서 쓰러지다",
	["Falrin Treeshaper, inside Dire Maul"] = "팔린 트리셰이퍼, 혈투의 전장 내부",
	["Falrin Treeshaper, inside the dungeon"] = "팔린 트리셰이퍼, 던전 내부",
	["Falrin Treeshaper, the library, inside Dire Maul"] = "팔린 트리셰이퍼, 도서관, 혈투의 전장 내부",
	["Falrin's Vendetta"] = "팔린의 피의 복수",
	["Fear at low health"] = "생명력이 낮을 때 공포",
	["Feathermoon Stronghold"] = "페더문 요새",
	["Fel'zerul, Swamp of Sorrows"] = "펠제룰, 슬픔의 늪",
	["Felnok Steelspring"] = "펠노크 스틸스프링",
	["Felnok Steelspring, Winterspring"] = "펠노크 스틸스프링, 여명의 설원",
	["Feralas"] = "페랄라스",
	["Fights in the arena of the Launch Bay."] = "출격실의 투기장에서 싸웁니다.",
	["Fights with his pet Chomper in the trogg cave off the outer ring."] = "바깥 순환로에서 갈라져 나온 트로그 동굴에서 애완동물 강철이빨 바실리스크와 함께 싸웁니다.",
	["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon."] = "마라우돈의 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.",
	["Fill the Coated Cerulean Vial at the orange crystal pool, pour it on the Vylestem Vines and kill the 8 Noxxious Scions that come out."] = "주황색 수정 웅덩이에서 빈 감청석 약병을 채운 뒤 바일줄기 덩굴나무에 붓고, 나타나는 녹시온의 후예 8마리를 처치해야 합니다.",
	["Final Passage"] = "최후의 시험",
	["Final Preparations"] = "마지막 준비",
	["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan."] = "소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 도안 카르한에게 가져가야 합니다.",
	["Find a way to clean the grime off the ring: the Sparklematic 5200 in Gnomeregan will."] = "반지의 찌꺼기를 제거할 방법을 찾아야 합니다. 놈리건에 있는 삐까뻔쩍세척기 5200이면 됩니다.",
	["Find Agmond"] = "아그몬드 찾기",
	["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."] = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다. 어떻게 아느냐고요? 당신은 초능력자니까요.",
	["Find Ardin Grassman in the Excavation Site and learn what became of him."] = "발굴 현장에서 아르딘 그라스만을 찾아 그에게 무슨 일이 있었는지 알아내야 합니다.",
	["Find Argent Guard Thaelrid inside Blackfathom Deeps."] = "검은심연 나락 안에서 은빛경비병 타엘리드를 찾아야 합니다.",
	["Find Baelog inside Uldaman."] = "울다만 내부에서 밸로그를 찾아야 합니다.",
	["Find Bijou's Belongings and return them to her. Good luck!"] = "비쥬의 소지품을 찾아 그녀에게 돌려주어야 합니다. 행운을 빕니다!",
	["Find Commander Gor'shak in a prison cell in Blackrock Depths."] = "검은바위 나락의 감방에서 사령관 고르샤크를 찾아야 합니다.",
	["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = "그림자송곳니 성채 안에서 죽음의추적자 아다만트와 죽음의추적자 빈센트를 찾아야 합니다.",
	["Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete."] = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.",
	["Find Drakkisath's Brand, guarded by General Drakkisath, to get the Mark of Drakkisath."] = "사령관 드라키사스가 지키는 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 합니다.",
	["Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done."] = "스트라솔름에서 에즈라 그림의 담배 가게를 찾아 그림의 최고급 담배 한 상자를 회수해야 합니다. 임무를 완수하면 스모키 라루에게 돌아가야 합니다.",
	["Find Hammertoe Grez in the caves before Uldaman."] = "울다만 앞의 동굴에서 해머토 그레즈를 찾아야 합니다.",
	["Find Hammertoe's Amulet and return it to him in Uldaman."] = "해머토의 아뮬렛을 찾아 울다만에 있는 그에게 돌려줘야 합니다.",
	["Find Kharan Mighthammer in the Blackrock Depths prison."] = "검은바위 나락의 감옥에서 카란 마이트해머를 찾아야 합니다.",
	["Find Lord Incendius in Blackrock Depths and destroy him!"] = "검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다!",
	["Find Marvon Rivetseeker in Tanaris."] = "타나리스에서 마본 리벳시커를 찾아야 합니다.",
	["Find Maur Grimtotem's corpse in Ragefire Chasm and search it."] = "성난불길 협곡에서 마우르 그림토템의 시체를 찾아 뒤져 봐야 합니다.",
	["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."] = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 씌인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다.",
	["Find someone in Kargath (Badlands) who can translate the paladin's journal."] = "카르가스(황야의 땅)에서 성기사의 일지를 번역해 줄 사람을 찾아야 합니다.",
	["Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."] = "슬픔의 늪에 있는 가라앉은 사원에서 학카르 제단을 찾아야 합니다.",
	["Find The Beginnings of the Undead Threat in the Library and bring it to Parqual Fintallas."] = "도서관에서 언데드 위협의 기원을 찾아 파쿠알 핀탈라스에게 가져가야 합니다.",
	["Find the belongings Bijou stashed on the bottom floor of the city, and bring them back to her."] = "비쥬가 도시 맨 아래층에 숨겨 둔 소지품을 찾아 그녀에게 가져가야 합니다.",
	["Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul."] = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다.",
	["Find the Gems"] = "보석 찾기",
	["Find the Gems and Power Source"] = "보석과 마력원천 찾기",
	["Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you."] = "울다만 곳곳에 흩어져 있는 루비, 사파이어, 토파즈를 찾아야 합니다. 모두 구하면 탈바쉬 델 키젤이 전에 준 수정점의 유리병을 사용해 멀리서 그와 연락해야 합니다.",
	["Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge."] = "결의의 서판을 찾아 아이언포지에 있는 조언자 벨그룸에게 가져가야 합니다.",
	["Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan."] = "지배의 보석 세 개, 즉 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾아야 합니다. 찾은 보석을 가공하지 않은 승천의 인장과 함께 밸란에게 가져가십시오.",
	["Find Treshala's Pendant and return it to Treshala Fallowbrook in Darnassus."] = "트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 돌려주어야 합니다.",
	["Finkle Einhorn, At Your Service!"] = "핍 퀵윗, 명을 받듭니다!",
	["Finkle Einhorn, inside the dungeon"] = "핀클 에인혼, 던전 내부",
	["Fire all around"] = "사방에 퍼지는 불길",
	["Fire damage every 3 seconds for 15 seconds, with slower attacks and movement. Interrupt the 2-second cast."] = "15초 동안 3초마다 화염 피해를 입히고 공격 속도와 이동 속도를 늦춥니다. 2초의 시전을 차단하십시오.",
	["Fire damage to a player, then more every 3 seconds for 12 seconds. A Magic dispel removes it."] = "플레이어에게 화염 피해를 준 뒤 12초 동안 3초마다 추가 피해를 줍니다. 마법 해제로 제거할 수 있습니다.",
	["Fire damage to everyone near him for a minute. A priest or a shaman can remove it."] = "1분 동안 근처의 모든 대상에게 화염 피해를 줍니다. 사제나 주술사가 해제할 수 있습니다.",
	["Fire damage to everyone near him, several times a fight. Healers, keep the melee topped up."] = "전투 중 여러 번 주위의 모두에게 화염 피해를 입힙니다. 치유 전담은 근접 공격수의 생명력을 가득 채워 두십시오.",
	["Fire damage to everyone within 10 yards of him."] = "10미터 내의 모든 대상에게 화염 피해를 줍니다.",
	["Fire Hardened Mail"] = "불에 달궈 만든 갑옷",
	["Fire Nova burns everyone near him several times a fight: healers, keep the melee topped up."] = "전투 중 여러 번 불꽃 회오리로 주위의 모두를 불태웁니다. 치유 전담은 근접 공격수의 생명력을 가득 채워 두십시오.",
	["Fire Taboo"] = "화재 예방",
	["Fix the broken trap with a Thorium Widget and Frost Oil."] = "토륨 부품과 냉기 오일로 부서진 함정을 고쳐야 합니다.",
	["Flamestrike"] = "불기둥",
	["Flamestrike is his main spell, and he can be interrupted and stunned: plan your kicks and stuns."] = "주력 주문은 불기둥이며, 차단과 기절이 통합니다. 차단과 기절을 걸 순서를 미리 정해 두십시오.",
	["Focal Blast: after a 3-second cast, a beam sweeps around the room, turning counterclockwise, for 6 seconds. Get out of its path as the cast starts: it kills."] = "초점 폭발: 3초 동안 시전한 뒤, 6초 동안 광선이 시계 반대 방향으로 돌며 방을 휩씁니다. 시전이 시작되면 경로에서 벗어나십시오. 맞으면 죽습니다.",
	["Follows Operative Bijou."] = "선행 퀘스트: '요원 비쥬'.",
	["Follows The Madness Within."] = "선행 퀘스트: '내면의 광기'.",
	["For 12 seconds he takes 60% less damage, and attacks slower but harder."] = "12초 동안 받는 피해가 60% 감소하며, 공격 속도가 느려지는 대신 공격이 강해집니다.",
	["For The Horde!"] = "호드를 위하여!",
	["For warriors and paladins."] = "전사와 성기사 전용.",
	["Forest Wisp, Teldrassil"] = "숲 위습, 텔드랏실",
	["Forging the Mightstone"] = "퇴마석 만들기",
	["Forlorn Cloister"] = "쓸쓸한 회랑",
	["Found in A Dusty Tome inside Dire Maul."] = "혈투의 전장 안에 있는 더러운 고서에서 발견됩니다.",
	["Four come once Fenrus the Devourer dies, called by Arugal. They heal each other: bring them down one at a time."] = "파멸의 펜루스가 죽으면 아루갈이 넷을 불러냅니다. 서로를 치유하므로 하나씩 처치하십시오.",
	["Four of them come after Fenrus the Devourer dies: Arugal appears for a moment and calls them."] = "파멸의 펜루스가 죽으면 넷이 나타납니다. 아루갈이 잠시 모습을 드러내 이들을 부릅니다.",
	["Franclorn Forgewright, Blackrock Mountain"] = "프랑클론 포지라이트, 검은바위 산",
	["Free Knot!"] = "노트 구출 대작전",
	["Freezes everyone near her in place for up to 8 seconds."] = "주위의 모두를 최대 8초 동안 그 자리에 얼립니다.",
	["From A Dusty Tome in Dire Maul, or from Captain Kromcrush."] = "혈투의 전장의 더러운 고서나 대장 크롬크러쉬에게서 얻습니다.",
	["From A Dusty Tome in Dire Maul."] = "혈투의 전장의 더러운 고서에서 얻습니다.",
	["From A Dusty Tome inside Dire Maul."] = "혈투의 전장 내부의 더러운 고서에서 얻습니다.",
	["Frost damage to the whole group. Healers, pace your mana through the waves."] = "파티 전체에 냉기 피해를 입힙니다. 치유 전담은 몰려오는 적들을 상대하는 동안 마나를 아껴 쓰십시오.",
	["Frost Nova"] = "얼음 회오리",
	["Frost Nova hits the whole group: healers, pace your mana through the waves."] = "얼음 회오리가 파티 전체를 공격합니다. 치유 전담은 몰려오는 적들을 상대하는 동안 마나를 아껴 쓰십시오.",
	["Frost Shock and You"] = "냉기 충격과 주술",
	["Furen Longbeard"] = "푸렌 롱비어드",
	["Furen Longbeard, Stormwind City"] = "푸렌 롱비어드, 스톰윈드",
	["Gahz'rilla"] = "가즈릴라",
	["Galamav the Marksman, Badlands"] = "명사수 갈라마브, 황야의 땅",
	["Garona: A Study on Stealth and Treachery"] = "가로나: 은신과 기만에 대한 연구",
	["Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind."] = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 10개를 가져가야 합니다.",
	["Gather the materials Furen Longbeard requires, and bring them to him in Stormwind."] = "스톰윈드에 있는 푸렌 롱비어드에게 그가 필요로 하는 재료들을 모아서 가져가야 합니다.",
	["Gaxim Rustfizzle, Stonetalon Mountains"] = "각심 러스트피즐, 돌발톱 산맥",
	["General Drakkisath's Command"] = "사령관 드라키사스의 명령서",
	["General Drakkisath's Command, dropped by Overlord Wyrmthalak inside Lower Blackrock Spire"] = "사령관 드라키사스의 명령서, 검은바위 첨탑 하층의 대군주 웜타라크에게서 획득",
	["General Drakkisath's Demise"] = "사령관 드라키사스 처치",
	["General Marcus Jonathan, Stormwind City"] = "장군 마커스 조나단, 스톰윈드",
	["Gerrig Bonegrip"] = "게릭 본그립",
	["Gerrig Bonegrip, Forlorn Cavern, Ironforge"] = "게릭 본그립, 아이언포지 쓸쓸한 뒷골목",
	["Gerrig Bonegrip, Forlorn Cavern, Ironforge (50.8, 5.6)"] = "게릭 본그립, 아이언포지 쓸쓸한 뒷골목 (50.8, 5.6)",
	["Gershala Nightwhisper"] = "게르샬라 나이트위스퍼",
	["Gershala Nightwhisper, Auberdine, Darkshore"] = "게르샬라 나이트위스퍼, 어둠의 해안 아우버다인",
	["Gershala Nightwhisper, Auberdine, Darkshore (38.3, 43.1)"] = "게르샬라 나이트위스퍼, 어둠의 해안 아우버다인 (38.3, 43.1)",
	["Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."] = "울다만의 북쪽 대전당에 있는 크롬 스타우트암의 궤짝에서 그의 보물을 꺼내 아이언포지에 있는 그에게 가져가야 합니다.",
	["Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."] = "울다만의 남쪽 대전당에 있는 가레트가의 궤짝에서 패트릭 가레트의 가문 보물을 꺼내 언더시티에 있는 그에게 가져가야 합니다.",
	["Get the Medallion of Faith from Malor's Strongbox and bring it to Aurius."] = "말로의 금고에서 신념의 메달을 꺼내 아우리우스에게 가져가야 합니다.",
	["Get the Scoop"] = "주문 알아오기",
	["Get the special horse feed from Merideth Carlson in Southshore, kill Tendris Warpwood in Dire Maul to free the Ancient Equine Spirit, feed it, and give it the Arcanite Barding to bless."] = "사우스쇼어의 메리데스 칼슨에게서 특별한 말 먹이를 받고, 혈투의 전장에서 굽이나무 텐드리스를 처치해 고대 준마의 영혼을 풀어 주어야 합니다. 그런 다음 영혼에게 먹이를 주고 아케이나이트 마갑을 건네 축복을 받으십시오.",
	["Ghak Healtouch, Loch Modan"] = "가크 힐터치, 모단 호수",
	["Ghostly Attendant, inside Hall of Thanes, after the first room"] = "유령 시종, 영주의 전당 안 첫 번째 방 다음",
	["Ghostly Attendant, inside the dungeon"] = "유령 시종, 던전 내부",
	["Give Marshal Maxwell the bad news."] = "치안대장 맥스웰에게 나쁜 소식을 전해야 합니다.",
	["Give the Dull and Flat Elven Blade to Lorekeeper Lydros."] = "현자 리드로스에게 납작하고 무딘 엘프 검을 건네야 합니다.",
	["Give the Sparklematic 5200 another Grime-Encrusted Object to get a Sparklematic-Wrapped Box."] = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 하나 더 넣어 삐까뻔쩍세척기 포장 상자를 받으십시오.",
	["Given by Jennea Cannon (Stormwind), Bink (Ironforge), Deino (Orgrimmar) and Anastasia Hartwell (Undercity)."] = "제니아 캐논(스톰윈드), 빙크(아이언포지), 다이노(오그리마), 아나스타샤 하트웰(언더시티)에게서 받을 수 있습니다.",
	["Given by Lokhtos Darkbargainer, inside the dungeon."] = "던전 내부의 로크토스 다크바게이너에게서 받습니다.",
	["Glowing Shard"] = "빛나는 조각",
	["Gnoarn, Ironforge"] = "노아른, 아이언포지",
	["Gnogaine"] = "폐기물 수집",
	["Gnome Improvement"] = "노움의 실력 향상",
	["Gnomer-gooooone!"] = "놈리거어어어언!",
	["Gnomeregan, the gnomes' capital beneath Dun Morogh, fell when troggs swarmed up from the deep and the gnomes flooded the city with radiation to stop them. Most of its people died; the traitor Mekgineer Thermaplugg now rules the irradiated halls with leper gnomes, troggs and his machines."] = "던 모로 지하에 자리한 노움의 수도 놈리건은 깊은 곳에서 트로그가 몰려 올라오자, 이를 막으려던 노움들이 도시에 방사능을 퍼뜨리면서 함락되었습니다. 주민 대부분이 목숨을 잃었고, 이제는 배신자 기계박사 텔마플러그가 오염된 노움과 트로그, 그리고 자신의 기계들을 거느리고 방사능에 오염된 전당을 다스리고 있습니다.",
	["Go back to the Athenaeum, find the Treasure of the Shen'dralar and claim your reward."] = "도서관으로 돌아가 셴드랄라의 보물을 찾아 보상을 받아야 합니다.",
	["Go into Blackrock Depths and find out what happened to Marshal Windsor."] = "검은바위 나락에 들어가 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다.",
	["Go into Blackrock Spire and find out what happened to Bijou."] = "검은바위 첨탑에 들어가 비쥬에게 무슨 일이 있었는지 알아내야 합니다.",
	["Go into Stratholme and rescue Ysida Harmon from Baron Rivendare."] = "스트라솔름으로 가서 남작 리븐데어로부터 이시다 하몬을 구해야 합니다.",
	["Go to Teldrassil and find Malfurion's agent outside Darnassus."] = "텔드랏실로 가서 다르나서스 성벽 밖에서 말퓨리온의 대리인을 찾아야 합니다.",
	["Go to Thunder Bluff and talk to Arch Druid Hamuul Runetotem."] = "썬더 블러프로 가서 대드루이드 하뮬 룬토템과 대화해야 합니다.",
	["Goblin Foundry"] = "고블린 주물 공장",
	["Going, Going, Guano!"] = "조분석을 나에게!",
	["Gorzeeki Wildeyes"] = "고르지키 와일드아이즈",
	["Gorzeeki Wildeyes, Burning Steppes"] = "고르지키 와일드아이즈, 불타는 평원",
	["Grark Lorkrub"] = "그랄크 로크럽",
	["Grark Lorkrub, Burning Steppes"] = "그랄크 로크럽, 불타는 평원",
	["Gregan Brewspewer"] = "그레간 브루스퓨",
	["Gregan Brewspewer, Feralas"] = "그레간 브루스퓨, 페랄라스",
	["Greta Mosshoof, Felwood"] = "그레타 모스후프, 악령의 숲",
	["Grime-Encrusted Ring"] = "꼬질꼬질한 반지",
	["Grimtotem Satchel, taken from Maur Grimtotem's corpse inside Ragefire Chasm"] = "그림토템 가방, 성난불길 협곡 안 마우르 그림토템의 시체에서 획득",
	["Grom'gol Base Camp"] = "그롬골 주둔지",
	["Gryan Stoutmantle"] = "그라이언 스타우트맨틀",
	["Gryan Stoutmantle, Sentinel Hill tower, Westfall (56.4, 47.5)"] = "그라이언 스타우트맨틀, 서부 몰락지대 감시의 언덕 탑 (56.4, 47.5)",
	["Gryan Stoutmantle, Sentinel Hill, Westfall"] = "그라이언 스타우트맨틀, 서부 몰락지대 감시의 언덕",
	["Gryphon Master Talonaxe"] = "그리핀 조련사 탈론액스",
	["Guard Berton — Lakeshire"] = "경비병 베르턴 — 레이크샤이어",
	["Guard Berton, Lakeshire, Redridge Mountains"] = "경비병 베르턴, 붉은마루 산맥 레이크샤이어",
	["Guard the Disciple through waves of serpents and then oozes; Mutanus surfaces right after the oozes."] = "몰려오는 뱀 무리와 그 뒤의 수액괴물 무리로부터 신도를 지키십시오. 수액괴물 무리가 끝나면 곧바로 무타누스가 나타납니다.",
	["Gyrodrillmatic Excavationators"] = "회전천공식 발굴기",
	["Haleh, Winterspring"] = "헬레, 여명의 설원",
	["Hammertoe Grez"] = "해머토 그레즈",
	["Hammertoe Grez, Badlands"] = "해머토 그레즈, 황야의 땅",
	["Hamuul Runetotem"] = "하뮬 룬토템",
	["Hand the Sparklematic 5200 a Grime-Encrusted Object for a Sparklematic-Wrapped Box."] = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣고 삐까뻔쩍세척기 포장 상자를 받으십시오.",
	["Harnessing Shadows"] = "지배의 그림자",
	["Haze of Evil"] = "악의 아지랑이",
	["He calls everything within 15 yards, his two Razorfen Spearhides among them: crowd-control one. Thunderclap every 8 to 14 seconds slows those near him."] = "15미터 내의 모든 적을 불러들이며, 곁에 있는 가시덩굴일족 가시근위병 둘도 함께 옵니다. 그중 하나는 군중 제어하십시오. 8~14초마다 천둥벼락으로 근처의 대상을 느리게 합니다.",
	["He can be at one of four places. A priest or a shaman can remove his Lightning Shield; interrupt his Lightning Bolt."] = "네 곳 중 한 곳에 있을 수 있습니다. 사제나 주술사가 번개 보호막을 해제할 수 있으며, 번개 화살은 차단하십시오.",
	["He cleaves, and at 30% health enrages for 2 minutes: much faster and harder blows."] = "회전베기를 사용하며, 생명력이 30%가 되면 2분 동안 격노하여 훨씬 빠르고 강하게 공격합니다.",
	["He cleaves, and slows his target."] = "회전베기를 사용하며, 대상을 느리게 만듭니다.",
	["He cleaves, and strikes hard at a target below 20% health: keep the tank above it."] = "회전베기를 사용하며, 생명력이 20% 미만인 대상에게 강력한 일격을 날립니다. 방어 전담의 생명력을 그 이상으로 유지하십시오.",
	["He disarms the tank."] = "방어 전담의 무장을 해제합니다.",
	["He drains mana from his target: a tank who uses mana feels it."] = "대상의 마나를 흡수합니다. 마나를 쓰는 방어 전담에게는 부담이 됩니다.",
	["He hits hard: keep the tank healthy. Bring mana potions for the waves before him."] = "공격이 강력하니 방어 전담의 생명력을 유지하십시오. 그가 나오기 전에 몰려오는 적들에 대비해 마나 물약을 챙기십시오.",
	["He hits hard: keep the tank topped up."] = "공격이 강력합니다. 방어 전담의 생명력을 가득 채워 두십시오.",
	["He hurls the tank into the air, stunned for 5 seconds: damage dealers, watch your threat, the tank holds him only about half the fight."] = "방어 전담을 공중으로 내던져 5초 동안 기절시킵니다. 방어 전담이 전투의 절반 정도만 그를 붙잡고 있으므로 공격 전담은 위협 수준에 주의하십시오.",
	["He is not there at first. In the sewers, past Atrexis, clear the north-east room, the one with market stalls and a small pink Summoning Circle (not Atrexis's large one). A player carrying the Tome of Dalaran then clicks the circle, and Lyn comes out of the large round grated door. To get the tome, loot the Black Tome on the table in Archmage Arugal's room in Shadowfang Keep, after his kill, then use it at the Leyline Focus, a blue crystal in a back room at Ambermill, in Silverpine Forest."] = "처음에는 그 자리에 없습니다. 하수구에서 아트렉시스를 지나 북동쪽 방을 정리하십시오. 시장 노점들과 작은 분홍색 소환 마법진이 있는 방입니다(아트렉시스의 큰 마법진이 아닙니다). 그런 다음 달라란의 고서를 가진 플레이어가 마법진을 클릭하면, 린이 크고 둥근 쇠창살 문에서 나옵니다. 고서를 얻으려면 그림자송곳니 성채에서 대마법사 아루갈을 처치한 뒤 그의 방 탁자 위에 있는 검은 고서를 획득하고, 은빛소나무 숲 앰버밀의 뒷방에 있는 푸른 수정인 지맥 집중체에서 사용하십시오.",
	["He keeps calling Arcane Manalings: cleave them down."] = "비전 마나의 정령을 계속 불러냅니다. 광역 공격으로 쓸어버리십시오.",
	["He keeps his distance to cast it. Interrupt it."] = "거리를 두고 시전합니다. 차단하십시오.",
	["He keeps his distance to cast it: Frost damage and a slow."] = "거리를 두고 시전합니다. 냉기 피해를 입히고 속도를 늦춥니다.",
	["He knocks players across the room: clear the packs nearest him, and tank him by the tunnel so nobody lands in another pack."] = "플레이어를 방 건너편으로 날려 버립니다. 가장 가까운 무리를 먼저 정리하고, 아무도 다른 무리 속에 떨어지지 않도록 방어 전담은 터널 근처에서 그를 상대하십시오.",
	["He knocks players back: clear the packs around him first, or you land in one."] = "플레이어를 뒤로 밀쳐냅니다. 주위의 무리를 먼저 정리하십시오. 그렇지 않으면 그 무리 속으로 떨어집니다.",
	["He knocks the tank back and turns to someone else: he drops his threat. Damage dealers, slow down when the tank loses him. Tank, take him back at once."] = "방어 전담을 뒤로 날려 보내고 다른 대상에게 향합니다. 방어 전담에 대한 위협 수준이 낮아집니다. 방어 전담이 우두머리를 놓치면 공격 전담은 공격을 늦추십시오. 방어 전담은 즉시 다시 끌어오십시오.",
	["He leaves a player for dead (moving ends it), stuns everyone near him, and enrages at 60% and again at 40% health."] = "플레이어 하나를 죽은 듯이 쓰러뜨리고(움직이면 풀립니다), 근처의 모든 대상을 기절시키며, 생명력이 60%일 때와 40%일 때 격노합니다.",
	["He lies on the floor of the small room beside the altar, as if dead, and gets up when attacked."] = "제단 옆 작은 방의 바닥에 죽은 듯 누워 있다가 공격받으면 일어납니다.",
	["He lies on the floor of the small room beside the altar, as if dead, and rises when attacked."] = "제단 옆 작은 방의 바닥에 죽은 듯 누워 있다가 공격을 받으면 몸을 일으킵니다.",
	["He makes the tank bleed."] = "방어 전담에게 출혈을 일으킵니다.",
	["He nets a player in place."] = "플레이어 한 명에게 그물을 던져 그 자리에 묶습니다.",
	["He pilots Sneed's Shredder and climbs out when it is destroyed."] = "스니드의 벌목기를 조종하다가 벌목기가 파괴되면 밖으로 나옵니다.",
	["He poisons his target and hits hard. Bring mana potions for the waves before him."] = "대상을 중독시키고 강력하게 공격합니다. 그가 나오기 전에 몰려오는 적들에 대비해 마나 물약을 챙기십시오.",
	["He punts people around the room. Clear the packs closest to him and tank him near the tunnel, so nobody lands in another pack."] = "플레이어를 방 여기저기로 걷어찹니다. 가장 가까운 무리를 정리하고, 아무도 다른 무리 속에 떨어지지 않도록 방어 전담은 터널 근처에서 그를 상대하십시오.",
	["He puts everyone near him to sleep (damage wakes a sleeper), and casts Mind Blast."] = "주위의 모두를 잠재우며(피해를 입으면 깨어남), 정신 분열을 시전합니다.",
	["He roams the marsh at the start among elite crocolisks, so clear them first or pull him away from them."] = "시작 지점의 늪에서 정예 악어들 사이를 돌아다니므로, 악어들을 먼저 처치하거나 그를 따로 끌어내십시오.",
	["He roams the marsh near the start among elite crocolisks: clear them first, or pull him away from them."] = "시작 지점 근처의 늪에서 정예 악어들 사이를 돌아다닙니다. 악어들을 먼저 처치하거나, 그를 악어들에게서 떨어진 곳으로 끌어내십시오.",
	["He roots players in place. A paladin's Blessing of Freedom frees them."] = "플레이어를 제자리에 묶습니다. 성기사의 자유의 축복으로 풀어 줄 수 있습니다.",
	["He speeds up his attacks by 75% for 20 seconds. It is magic: a shaman's Purge or a priest's Dispel Magic takes it off him."] = "20초 동안 공격 속도를 75% 높입니다. 마법 효과이므로 주술사의 정화나 사제의 마법 무효화로 제거할 수 있습니다.",
	["He stands at a ritual circle in the sewers, with Kirin Tor Necromancers around him."] = "하수구의 의식 마법진에 서 있으며, 주위에 키린 토 강령술사들이 있습니다.",
	["He stands in a Dragonmaw camp. Its groups pull apart easily: take them one at a time first. The fight itself is short."] = "용아귀일족 야영지에 서 있습니다. 야영지의 무리는 쉽게 따로 끌어낼 수 있으니, 먼저 한 무리씩 처치하십시오. 전투 자체는 짧습니다.",
	["He stands still at the end of the spider trail. Click the small panel next to him to wake him."] = "거미 길 끝에 가만히 서 있습니다. 옆에 있는 작은 판을 클릭하면 깨어납니다.",
	["He stomps again and takes up his hammer."] = "다시 발을 구르고 망치를 듭니다.",
	["He stomps, stunning everyone near him, and takes up two axes."] = "발을 굴러 주위의 모두를 기절시키고 도끼 두 자루를 듭니다.",
	["He summons a Boar Spirit every 30 to 45 seconds: kill each before the next comes. Below 75% health, interrupt his Chain Heal."] = "30~45초마다 멧돼지 정령을 소환합니다. 다음 정령이 나오기 전에 처치하십시오. 생명력이 75% 아래로 떨어지면 연쇄 치유를 차단하십시오.",
	["He switches on the gnome faces around the room one by one, and each sends out Walking Bombs that explode when they reach a player. The button next to a face switches it off. Below half health he switches them on faster."] = "방 주위에 있는 노움 얼굴 장치를 하나씩 작동시키며, 장치마다 플레이어에게 닿으면 폭발하는 보행 폭탄이 나옵니다. 얼굴 장치 옆의 버튼을 누르면 장치가 꺼집니다. 생명력이 절반 아래로 떨어지면 장치를 더 빨리 작동시킵니다.",
	["He switches on the gnome faces around the room one by one, each sending out Walking Bombs: press the button beside a face to switch it off."] = "방 주위에 있는 노움 얼굴 장치를 하나씩 작동시키며, 장치마다 보행 폭탄이 나옵니다. 얼굴 장치 옆의 버튼을 눌러 끄십시오.",
	["He takes the tank's weapon away for about 6 seconds."] = "약 6초 동안 방어 전담의 무기를 빼앗습니다.",
	["He tears at the tank's legs, slowing them."] = "방어 전담의 다리를 찢어 느려지게 합니다.",
	["He teleports between his ledge, the upper ledge and the stairs."] = "자신의 난간, 위쪽 난간, 계단 사이를 순간이동합니다.",
	["He tramples everyone standing close."] = "가까이 있는 모두를 밟아 뭉갭니다.",
	["He tramples the players next to him for about 100 physical damage."] = "가까이 있는 플레이어를 짓밟아 약 100의 물리 피해를 줍니다.",
	["He waits behind a barrier in the middle of the city. Kill the Suffused Treants in front of it, then speak to Magus Fansy Goodbringer, just south of the barrier, to bring it down."] = "도시 한가운데의 보호막 뒤에서 기다립니다. 보호막 앞의 마력 스민 나무정령들을 처치한 뒤, 보호막 바로 남쪽에 있는 학자 팬시 굿브링어와 대화해 보호막을 내리십시오.",
	["He waits behind a magic barrier in the middle of the city, with Suffused Treants in front of it. Kill the treants, then talk to Magus Fansy Goodbringer, just south of the barrier: he brings it down."] = "도시 한가운데의 마법 보호막 뒤에서 기다리며, 보호막 앞에는 마력 스민 나무정령들이 있습니다. 나무정령들을 처치한 뒤 보호막 바로 남쪽에 있는 학자 팬시 굿브링어와 대화하면 보호막을 내려 줍니다.",
	["He waits in an underwater cave below Twilight Lord Kelris's temple, where groups often miss him. Swim under the temple to reach him."] = "황혼의 군주 켈리스의 신전 아래 수중 동굴에 있어 그냥 지나치는 파티가 많습니다. 신전 아래로 헤엄쳐 가면 만날 수 있습니다.",
	["He waits in an underwater cave below Twilight Lord Kelris's temple: swim under the temple to find him."] = "황혼의 군주 켈리스의 신전 아래 수중 동굴에 있습니다. 신전 아래로 헤엄쳐 가서 찾으십시오.",
	["Head of Balnazzar"] = "발나자르의 혼",
	["Head of Balnazzar, dropped by Balnazzar inside Stratholme"] = "발나자르의 혼, 스트라솔름의 발나자르에게서 획득",
	["Heals a wounded ally, or herself, over 15 seconds. A priest or a shaman can remove it."] = "부상당한 아군이나 자신을 15초에 걸쳐 치유합니다. 사제나 주술사가 해제할 수 있습니다.",
	["Heals another voidwalker. Bring them down one at a time."] = "다른 보이드워커를 치유합니다. 하나씩 처치하십시오.",
	["Heals herself or an ally. Interrupt it."] = "자신이나 아군을 치유합니다. 차단하십시오.",
	["Heals himself or an ally (2.5-second cast). Interrupt it."] = "자신이나 아군을 치유합니다(시전 시간 2.5초). 차단하십시오.",
	["Heals himself or an ally (3-second cast). Interrupt it."] = "자신이나 아군을 치유합니다(시전 시간 3초). 차단하십시오.",
	["Heals himself or an ally. Interrupt it."] = "자신이나 아군을 치유합니다. 차단하십시오.",
	["Heals the most wounded of her allies, Mograine included (3-second cast). Interrupt it."] = "모그레인을 포함해 아군 중 가장 많이 다친 대상을 치유합니다(시전 시간 3초). 차단하십시오.",
	["Healthy Dragon Scale"] = "생기 있는 용비늘",
	["Hear from Kharan Mighthammer about Princess Moira's kidnapping, then report to Thrall."] = "카란 마이트해머에게서 공주 모이라의 납치에 대한 이야기를 들은 후 스랄에게 보고해야 합니다.",
	["Heart of Disruption"] = "분열의 심장",
	["Hearts of Zeal"] = "열정의 증거",
	["Heartwoven"] = "마음으로 엮은 것",
	["Heavy blows"] = "강력한 타격",
	["Helendis Riverhorn, Burning Steppes"] = "헬렌디스 리버혼, 불타는 평원",
	["Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."] = "치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오.",
	["Heralath Fallowbrook, inside Razorfen Kraul"] = "헤랄라스 팰로우브룩, 가시덩굴 우리 내부",
	["Hidden Enemies"] = "내부의 배신자",
	["Hidden Secrets"] = "숨겨진 비밀",
	["High Executor Hadrec"] = "고위집행관 하드렉",
	["High Executor Hadrec, The Sepulcher, Silverpine Forest"] = "고위집행관 하드렉, 은빛소나무 숲 공동묘지",
	["High Explorer Magellas"] = "선임탐험가 마겔라스",
	["High Explorer Magellas, Hall of Explorers, Ironforge"] = "선임탐험가 마겔라스, 아이언포지 탐험가의 전당",
	["High Sorcerer Andromath — Stormwind City"] = "고위마술사 안드로매스 — 스톰윈드",
	["High Sorcerer Andromath, Stormwind City"] = "고위마술사 안드로매스, 스톰윈드",
	["High Tinker Mekkatorque — Tinker Town, Ironforge"] = "땜장이왕 멕카토크 — 땜장이 마을, 아이언포지",
	["High Tinker Mekkatorque, Ironforge"] = "땜장이왕 멕카토크, 아이언포지",
	["Highland Hides"] = "고원의 가죽",
	["Highland Venom"] = "고원 독액",
	["His Arcane Explosion hits everyone close to him, and Detonation hits harder still: keep your distance when he readies it."] = "신비한 폭발은 가까이 있는 모든 대상에게 피해를 주며, 폭발은 그보다 더 강력합니다. 그가 폭발을 준비하면 거리를 벌리십시오.",
	["His blows poison: cure it if you can. Sinister Strike adds damage on the tank."] = "공격에 독이 묻어 있으니 가능하면 해독하십시오. 사악한 일격으로 방어 전담에게 추가 피해를 입힙니다.",
	["His blows poison: Nature damage over time. Cure it if you can."] = "공격에 독이 묻어 있어 지속적으로 자연 피해를 입힙니다. 가능하면 해독하십시오.",
	["His Cleave also hits the player nearest his target: stand apart from the tank."] = "회전베기는 대상과 가장 가까이 있는 플레이어도 함께 공격합니다. 방어 전담과 떨어져 서십시오.",
	["His Curse of Weakness reaches everyone within 30 yards (a mage or a druid can remove it), and he leaves a poison cloud."] = "무력화 저주는 30미터 내의 모든 대상에게 걸리며(마법사나 드루이드가 해제할 수 있습니다), 독구름을 남깁니다.",
	["His fire hits the whole group, and harder the more of you fight in melee."] = "화염 공격이 파티 전체를 덮치며, 근접 전투를 벌이는 인원이 많을수록 피해가 커집니다.",
	["His Knock Away throws the tank back and drops his threat: damage dealers, ease off when the tank loses him; tank, take him back at once."] = "날려버리기로 방어 전담을 뒤로 날려 보내고 방어 전담에 대한 위협 수준을 낮춥니다. 방어 전담이 우두머리를 놓치면 공격 전담은 공격을 늦추고, 방어 전담은 즉시 다시 끌어오십시오.",
	["His main spell. He can be interrupted and stunned: plan your kicks and stuns."] = "주력 주문입니다. 차단과 기절이 통하니 차단과 기절을 걸 순서를 미리 정해 두십시오.",
	["His room"] = "그의 방",
	["His Scarlet Tracking Hounds fight beside him: kill them first. He uses Bloodlust."] = "붉은십자군 추적용 하이에나가 곁에서 함께 싸웁니다. 먼저 처치하십시오. 피의 욕망을 사용합니다.",
	["His shout sends nearby players fleeing in fear."] = "외침으로 주위의 플레이어를 공포에 질려 도망치게 합니다.",
	["His Slam stuns the tank for 3 seconds."] = "라크조르의 격돌로 방어 전담을 3초 동안 기절시킵니다.",
	["His Smoke Bomb stuns everyone near him; at 15% health he runs for help."] = "연막탄으로 주위의 모두를 기절시킵니다. 생명력이 15%가 되면 도움을 청하러 도망칩니다.",
	["His Uppercut can throw a player back into lava or into nearby enemies."] = "올려치기에 맞은 플레이어는 용암 속이나 근처의 적에게 날아갈 수 있습니다.",
	["Hits everyone in a cone in front of it."] = "전방 부채꼴 범위의 모든 대상을 공격합니다.",
	["Hits everyone near him and slows their attacks."] = "주위의 모두를 공격하고 공격 속도를 늦춥니다.",
	["Hits everyone near it and interrupts their spells. Casters and healers, keep your distance."] = "근처의 모든 대상을 공격하고 주문 시전을 방해합니다. 주문시전자와 치유 전담은 거리를 유지하십시오.",
	["Hits everyone standing close."] = "가까이 있는 모두를 공격합니다.",
	["Hits his target and the player nearest to it."] = "대상과 그 대상에게 가장 가까운 플레이어를 공격합니다.",
	["Hits the tank and stuns them for 2 seconds."] = "방어 전담을 공격하여 2초 동안 기절시킵니다.",
	["Hits the tank hard and stuns them for 3 seconds."] = "방어 전담을 강하게 내리쳐 3초 동안 기절시킵니다.",
	["Holds the top of the ship with two of his crew."] = "선원 두 명과 함께 배 위쪽을 지키고 있습니다.",
	["Holy Bologna: What the Light Won't Tell You"] = "성스러운 볼로냐: 빛이 알려주지 않는 것들",
	["Holy damage to her target (2.5-second cast). Interrupt it."] = "대상에게 신성 피해를 줍니다(시전 시간 2.5초). 차단하십시오.",
	["Holy damage to whoever strikes him in melee."] = "그를 근접 공격하는 대상에게 신성 피해를 줍니다.",
	["Honor's Tomb"] = "명예의 무덤",
	["Horrors in the Highland"] = "고원의 공포",
	["Hot Fiery Death"] = "뜨거운 화형",
	["Houses of the Holy"] = "성스러운 집",
	["Human Remains"] = "인간 해골",
	["Human Remains, inside the dungeon"] = "인간 해골, 던전 내부",
	["Hunting for Ectoplasm"] = "심령체 수집",
	["Huntsman's Cloister"] = "사냥꾼의 회랑",
	["Hurled into the air"] = "공중으로 내던지기",
	["Hurley Blackbreath"] = "헐레이 블랙브레스",
	["I See Alcaz Island In Your Future..."] = "예언 속의 알카즈 섬",
	["Idol of Hakkar, inside the dungeon"] = "학카르 신상, 던전 내부",
	["If someone leaves the room during the fight, he resets to full health."] = "전투 중에 누군가 방을 벗어나면 그의 생명력이 최대로 초기화됩니다.",
	["If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."] = "벨리스트라즈를 돕기로 했다면 그에게 다시 말을 걸어 그가 준 서약의 돌을 돌려줘야 합니다.",
	["Image of Archmage Modera — Lordamere Lake"] = "대마법사 모데라의 환영 — 로다미어 호수",
	["Image of Archmage Modera — Lordamere Lake near Dalaran"] = "대마법사 모데라의 환영 — 달라란 근처 로다미어 호수",
	["Image of Archmage Modera, Lordamere Lake near Dalaran"] = "대마법사 모데라의 환영, 달라란 근처 로다미어 호수",
	["Imp Delivery"] = "임프 배달",
	["Important Heirlooms"] = "중요한 가보",
	["Impsy, Felwood"] = "임프시, 악령의 숲",
	["In Gnomeregan, once the ring is clean."] = "반지를 세척한 후, 놈리건에서.",
	["In Nightmares"] = "악몽",
	["In Search of Thaelrid"] = "타엘리드 찾기",
	["In Search of The Temple"] = "신전을 찾아서",
	["In the Chamber of Atonement."] = "속죄의 방에 있습니다.",
	["In the Engineering Labs. He drops the Workshop Key."] = "기계공학 연구소에 있습니다. 작업장 열쇠를 획득할 수 있습니다.",
	["In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you."] = "검은바위 첨탑 깊숙한 곳에 여왕 불그물거미가 있습니다. 여왕 불그물거미와 싸워 그 독에 중독되어야 합니다. 아마 여왕 불그물거미도 처치해야 할 것입니다. 중독되면 털보 존에게 돌아가 그가 독을 '짜낼' 수 있게 하십시오.",
	["In the Huntsman's Cloister."] = "사냥꾼의 회랑에 있습니다.",
	["In the Name of the Light"] = "빛의 이름으로!",
	["In the thorny barrows of the southern Barrens the Scourge has struck a pact with the quilboar: Amnennar the Coldbringer rules the Razorfen's burial grounds."] = "불모의 땅 남부, 가시덩굴로 뒤덮인 무덤 언덕에서 스컬지가 멧돼지인간과 손을 잡았습니다. 혹한의 암네나르가 가시덩굴일족의 매장지를 지배하고 있습니다.",
	["Incendius!"] = "인센디우스!",
	["Inert Scourgestones"] = "마력을 잃은 스컬지석",
	["Infected Wound"] = "상처 감염",
	["Insert a Grime-Encrusted Object into the Sparklematic 5200, with three silver coins to start the machine."] = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.",
	["Inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = "왕가의 성물 보관소(드루겐 더지해머의 방) 금고 안",
	["Inside Stratholme, where the Keepsake of Remembrance is placed."] = "스트라솔름 내부, 추억의 유품을 두는 곳.",
	["Inside the dungeon."] = "던전 내부.",
	["Inside the dungeon; needs Mining 230."] = "던전 내부. 채광 230 필요.",
	["Interrupt her Chain Bolt. Every so often she is immune for 2 seconds, and a priest or a shaman can remove her Renew."] = "연쇄 벼락을 차단하십시오. 때때로 2초 동안 면역 상태가 되며, 소생은 사제나 주술사가 해제할 수 있습니다.",
	["Interrupt her Holy Smite and her heals; a priest or a shaman can remove her shield."] = "성스러운 일격과 치유 주문을 차단하십시오. 그녀의 보호막은 사제나 주술사가 해제할 수 있습니다.",
	["Interrupt his Chain Lightning. A priest or a shaman can remove his Bloodlust."] = "연쇄 번개를 차단하십시오. 피의 욕망은 사제나 주술사가 제거할 수 있습니다.",
	["Interrupt his Chained Bolt, which jumps to a second player."] = "다른 플레이어 한 명에게 옮겨 가는 사슬 번개를 차단하십시오.",
	["Interrupt his Fear and, at 30% health, his heal. He puts everyone near him to sleep (damage wakes a sleeper), and a mage or a druid can remove his Curse of Blood."] = "공포를 차단하고, 생명력이 30%가 되면 쓰는 치유도 차단하십시오. 주위의 모든 대상을 잠재우며(피해를 입으면 깨어납니다), 피의 저주는 마법사나 드루이드가 해제할 수 있습니다.",
	["Interrupt his Healing Touch. Thunderclap slows everyone near him."] = "치유의 손길을 차단하십시오. 천둥벼락은 주위의 모두를 느리게 만듭니다.",
	["Interrupt his Holy Light. Divine Shield makes him immune for 10 seconds, and he stuns with Hammer of Justice."] = "성스러운 빛을 차단하십시오. 천상의 보호막으로 10초 동안 무적이 되며, 심판의 망치로 기절시킵니다.",
	["Interrupt his Immolate or dispel the burn. A mage or a druid can remove his Curse of Weakness."] = "제물을 차단하거나 화상 효과를 해제하십시오. 무력화 저주는 마법사나 드루이드가 해제할 수 있습니다.",
	["Interrupt his Lightning Bolt and Healing Touch. Below 30% health his serpent form hits harder and puts players to sleep."] = "번개 화살과 치유의 손길을 차단하십시오. 생명력이 30% 아래로 떨어지면 뱀 형상으로 변해 더 강하게 공격하고 플레이어를 잠재웁니다.",
	["Interrupt his Molten Metal, which burns and slows."] = "화상을 입히고 속도를 늦추는 용해된 금속을 차단하십시오.",
	["Interrupt his slow Healing Touch and his Lightning Bolt."] = "시전이 느린 치유의 손길과 번개 화살을 차단하십시오.",
	["Interrupt his Void Bolt. He teleports between his ledges, and stuns everyone around him when the tank reaches him."] = "공허의 화살을 차단하십시오. 여러 난간 사이를 순간이동하며, 방어 전담이 다가오면 주위의 모두를 기절시킵니다.",
	["Interrupt or dispel his Dominate Mind, which takes over a player; interrupt his Shadow Bolt."] = "플레이어를 조종하는 정신 지배는 차단하거나 해제하십시오. 어둠의 화살도 차단하십시오.",
	["Interrupt or dispel his Polymorph. His Silence reaches 15 yards: healers, stand back."] = "변이는 차단하거나 해제하십시오. 침묵은 15미터까지 미칩니다. 치유 전담은 뒤로 물러나 있으십시오.",
	["Interrupt or dispel his Soul Drain, which roots a player and drains their health."] = "플레이어를 묶고 생명력을 흡수하는 영혼 흡수를 차단하거나 해제하십시오.",
	["Into Fenris Keep"] = "펜리스 요새로",
	["Into the Depths"] = "심연의 늪",
	["Into The Scarlet Monastery"] = "붉은십자군 수도원으로",
	["Into The Temple of Atal'Hakkar"] = "아탈학카르 신전으로",
	["Investigate the disappearance of Edward Heartweaver in Ruins of Lordaeron."] = "로데론의 폐허에서 에드워드 하트위버의 실종을 조사해야 합니다.",
	["Ironclad Cove"] = "철갑 동굴",
	["Ironforge"] = "아이언포지",
	["It fears a player and slows another's casting."] = "한 플레이어에게 공포를 걸고, 다른 플레이어의 시전 속도를 늦춥니다.",
	["It keeps calling small Arcane Manalings. Kill them with area damage."] = "작은 비전 마나의 정령을 계속 불러냅니다. 광역 공격으로 처치하십시오.",
	["It roots everyone near it, slows and stuns, and calls Dupe Bugs that its Patch turns into healing."] = "근처의 모든 대상을 묶고, 느리게 하거나 기절시키며, 복제 버그를 불러낸 뒤 패치로 이를 치유로 바꿉니다.",
	["It whirls at everyone close, and its thorns hurt whoever strikes it or an ally nearby, Ramtusk included."] = "근처의 모든 대상에게 회오리 공격을 하며, 자신이나 근처의 아군(램터스크 포함)을 공격하는 대상은 가시에 피해를 입습니다.",
	["Its attack on the tank between the beams, a 1.5-second cast."] = "광선 사이사이에 방어 전담에게 쓰는 공격입니다. 시전 시간 1.5초.",
	["Its Fathom Stone also calls up Baron Aquanis, an optional fight."] = "심연의 돌을 사용하면 군주 아쿠아니스도 나타납니다. 그와의 전투는 선택 사항입니다.",
	["Jail Break!"] = "탈옥!",
	["Jalinda Sprig, Burning Steppes"] = "잘린다 스프리그, 불타는 평원",
	["James Halloran — Menethil Harbor"] = "제임스 할로란 — 메네실 항구",
	["James Halloran, Menethil Harbor, Wetlands"] = "제임스 할로란, 저습지 메네실 항구",
	["Jammal'an the Prophet"] = "예언자 잠말란",
	["Jarkal Mossmeld"] = "자칼 모스멜드",
	["Jarkal Mossmeld, Badlands"] = "자칼 모스멜드, 황야의 땅",
	["Jarkal Mossmeld, Kargath, Badlands"] = "자칼 모스멜드, 카르가스, 황야의 땅",
	["Je'neu Sancrea"] = "제네우 생크리",
	["Je'neu Sancrea, Zoram'gar Outpost, Ashenvale"] = "제네우 생크리, 잿빛 골짜기 조람가르 전초기지",
	["Je'neu Sancrea, Zoram'gar Outpost, Ashenvale (12, 34)"] = "제네우 생크리, 잿빛 골짜기 조람가르 전초기지 (12, 34)",
	["Jordan Stilwell — Gates of Ironforge"] = "조던 스틸웰 — 아이언포지 성문",
	["Jordan Stilwell, Gates of Ironforge, Dun Morogh"] = "조던 스틸웰, 던 모로 아이언포지 성문",
	["Journey to the Marsh"] = "습지대로의 여행",
	["Judgment and Redemption"] = "심판과 구원의 손길",
	["Keep the ring, or find whoever made the mark engraved inside its band."] = "반지를 그냥 가지거나, 반지 안쪽에 새겨진 인장 자국의 주인을 찾아야 합니다.",
	["Keeper Bel'dugur"] = "관리인 벨두거",
	["Keeper Bel'dugur, Apothecarium, Undercity"] = "관리인 벨두거, 언더시티 연금술 실험실",
	["Keeper Marandis, Desolace"] = "수호자 마란디스, 잊혀진 땅",
	["Keeper Remulos, Moonglade"] = "수호자 레물로스, 달의 숲",
	["Kernobee, inside Gnomeregan"] = "케르노비, 놈리건 내부",
	["Key to the City"] = "도시로 통하는 열쇠",
	["Kharan Mighthammer"] = "카란 마이트해머",
	["Kharan Mighthammer, inside Blackrock Depths"] = "카란 마이트해머, 검은바위 나락 내부",
	["Kharan's Tale"] = "카란의 이야기",
	["Kibler's Exotic Pets"] = "키블러의 진귀한 애완동물",
	["Kibler, Burning Steppes"] = "키블러, 불타는 평원",
	["Kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents inside The Stockade."] = "스톰윈드 지하감옥 안에서 데피아즈단 복역수 10명, 데피아즈단 무기징역수 8명, 데피아즈단 반역자 8명을 처치해야 합니다.",
	["Kill 15 Enraged Apparitions and 10 Tormented Souls, then put Anvilmar's spirit to rest."] = "분노한 원혼 15마리와 고통받는 영혼 10마리를 처치한 다음, 앤빌마의 영혼을 잠재워야 합니다.",
	["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."] = "역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다.",
	["Kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."] = "돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해야 합니다.",
	["Kill 8 Ragefire Troggs and 8 Ragefire Shamans inside Ragefire Chasm."] = "성난불길 협곡에서 성난불길 트로그 8마리와 성난불길일족 주술사 8마리를 처치해야 합니다.",
	["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."] = "가시덩굴일족 전투호위병, 가시덩굴일족 가시마술사, 죽음의 머리교 신도를 각각 8명씩 처치한 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다.",
	["Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."] = "발굴 현장 안에서 고원 공포를 처치하고 그 뿌리핵을 저습지의 신록의수호자 레시엘에게 가져가야 합니다.",
	["Kill Archmage Arugal and bring his head to Dalar Dawnweaver."] = "대마법사 아루갈을 처치하고 아루갈의 머리카락을 달라 던위버에게 가져가야 합니다.",
	["Kill Bazil Thredd in The Stockade and bring his head back to Warden Thelwater."] = "스톰윈드 지하감옥에 있는 바질 스레드를 처치하고 그의 머리를 교도소장 델워터에게 가져가야 합니다.",
	["Kill Bazzalan and Jergosh the Invoker inside Ragefire Chasm."] = "성난불길 협곡에서 바잘란과 기원사 제로쉬를 처치해야 합니다.",
	["Kill Dextren Ward in The Stockade and bring his hand to Councilman Millstipe."] = "스톰윈드 지하감옥에 있는 덱스트렌 워드를 처치하고 그의 손을 원로 밀스타이프에게 가져가야 합니다.",
	["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod and Houndmaster Loksey, then report to Raleigh the Devout in Southshore."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 사냥개조련사 록시를 처치한 후 사우스쇼어에 있는 경건한 신자 랄레이에게 보고해야 합니다.",
	["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod and Houndmaster Loksey, then report to Varimathras in the Undercity."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 보고해야 합니다.",
	["Kill Kam Deepfury in The Stockade and bring his head to Motley Garmason."] = "스톰윈드 지하감옥에 있는 캄 딥퓨리를 처치하고 그의 머리를 모틀리 가마슨에게 가져가야 합니다.",
	["Kill Lady Anacondra, Lord Cobrahn, Lord Pythas and Lord Serpentis, then talk to the Disciple of Naralex at the entrance and escort him to Naralex. Protect him during the ritual: Mutanus comes at the end."] = "여군주 아나콘드라, 군주 코브란, 군주 피타스, 군주 서펜티스를 처치한 뒤 입구에 있는 나랄렉스의 신도와 대화하고 나랄렉스에게까지 호위하십시오. 의식 도중 신도를 보호하십시오. 마지막에 무타누스가 나타납니다.",
	["Kill Mekgineer Thermaplugg and return to High Tinker Mekkatorque."] = "기계박사 텔마플러그를 처치한 다음 땜장이왕 멕카토크에게 돌아가야 합니다.",
	["Kill Morphaz and take his blood to Greta Mosshoof in Felwood."] = "몰파즈를 처치하고 그의 피를 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.",
	["KILL ON SIGHT, Badlands"] = "사살 지령, 황야의 땅",
	["KILL ON SIGHT: Dark Iron Dwarves"] = "죽음의 본보기: 검은무쇠단 드워프",
	["KILL ON SIGHT: High Ranking Dark Iron Officials"] = "죽음의 본보기: 검은무쇠단 고위 관리",
	["Kill Princess Theradras."] = "공주 테라드라스를 처치해야 합니다.",
	["Kill Rath'mael in Ruins of Lordaeron."] = "로데론의 폐허에서 라스마엘을 처치해야 합니다.",
	["Kill Shadow Hunter Vosh'gajin and bring her Snakestone to Kilram."] = "어둠사냥꾼 보쉬가진을 처치하고 보쉬가진의 뱀돌을 킬램에게 가져가야 합니다.",
	["Kill Targorr the Dread in The Stockade and bring his head to Guard Berton."] = "스톰윈드 지하감옥에 있는 흉악범 타고르를 처치하고 그의 머리를 경비병 베르턴에게 가져가야 합니다.",
	["Kill the Dark Iron Summoner first: he keeps bringing adds. Then turn on the elemental."] = "검은무쇠단 소환사부터 처치하십시오. 계속해서 추가 몬스터를 불러냅니다. 그다음 정령을 공격하십시오.",
	["Kill the green drake Morphaz and bring his tooth to Ogtinc."] = "녹색 비룡 몰파즈를 처치하고 몰파즈의 이빨을 오그틴크에게 가져가야 합니다.",
	["Kill the raptor matriarch in the tall grass. A wave of raptors comes when she dies, and Shadetooth runs in once they are dead."] = "키 큰 풀숲에 있는 우두머리랩터를 처치하십시오. 우두머리랩터가 죽으면 랩터 무리가 몰려오고, 이들을 모두 처치하면 그늘이빨이 달려옵니다.",
	["Kill the raptor matriarch in the tall grass. Her death brings a wave of raptors, and Shadetooth comes once they are dead: finish the whole wave before he arrives."] = "키 큰 풀숲에 있는 우두머리랩터를 처치하십시오. 우두머리랩터가 죽으면 랩터 무리가 몰려오고, 이들이 모두 죽으면 그늘이빨이 나타납니다. 그가 도착하기 전에 무리를 모두 처치하십시오.",
	["Kill the summoner first: he keeps bringing adds. Then turn on the elemental."] = "소환사부터 처치하십시오. 계속해서 추가 몬스터를 불러냅니다. 그다음 정령을 공격하십시오.",
	["Kilram, Everlook, Winterspring"] = "킬램, 눈망루 마을, 여명의 설원",
