	["King Magni Bronzebeard, Ironforge"] = "국왕 마그니 브론즈비어드, 아이언포지",
	["Kirtonos the Herald"] = "사자 키르토노스",
	["Klockmort Spannerspan — Tinker Town, Ironforge"] = "클락몰트 스패너스판 — 땜장이 마을, 아이언포지",
