	["Knockback"] = "밀쳐내기",
	["Knocked across the room"] = "방 건너편으로 날려 보내기",
	["Knocks the tank back. Below half health it hits everyone around him."] = "방어 전담을 뒤로 밀쳐냅니다. 생명력이 절반 아래로 떨어지면 주위의 모든 대상에게 적중합니다.",
	["Knocks you back: clear the packs around him first, or you land in one."] = "뒤로 밀쳐냅니다. 주위의 무리를 먼저 정리하십시오. 그렇지 않으면 그 무리 속으로 떨어집니다.",
	["Knot Thimblejack, inside Dire Maul"] = "노트 팀블잭, 혈투의 전장 내부",
