	["Krazek, Stranglethorn Vale"] = "크라젝, 가시덤불 골짜기",
	["Krom Stoutarm"] = "크롬 스타우트암",
	["Krom Stoutarm, Hall of Explorers, Ironforge"] = "크롬 스타우트암, 탐험가의 전당, 아이언포지",
