	["Larion, Un'Goro Crater"] = "라리온, 운고로 분화구",
	["Late in the fight he enrages and hits harder: keep the tank's health up to the end."] = "전투 후반에 격노하여 더 강하게 공격합니다. 끝까지 방어 전담의 생명력을 높게 유지하십시오.",
	["Latronicus Moonspear, Feralas"] = "라트로니쿠스 문스피어, 페랄라스",
	["Leaders of the Fang"] = "송곳니의 드루이드 우두머리",
	["Leads to Return of the Ring."] = "'반지의 귀환'으로 이어집니다.",
	["Leads to Returning the Lost Satchel."] = "'잃어버린 가방 돌려주기' 퀘스트로 이어집니다.",
	["Legends of Maraudon"] = "마라우돈의 전설",
