	["Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."] = "자칼에게 목걸이를 빌려줘야 합니다. 그 대가로 자칼이 일지를 번역해 줄 것입니다.",
	["Lethtendris's Web"] = "레스텐드리스의 그물",
