	["Light's Justice"] = "빛의 정의",
	["Lightning strikes whoever hits him. A priest or a shaman can remove it."] = "자신을 공격하는 대상에게 번개를 내리칩니다. 사제나 주술사가 해제할 수 있습니다.",
	["Lightning that jumps from player to player (2-second cast). Interrupt it."] = "플레이어에서 플레이어로 튀어 다니는 번개입니다(시전 시간 2초). 차단하십시오.",
	["Lightning that jumps to nearby players (2.5-second cast). Interrupt it."] = "근처의 플레이어에게 튀는 번개입니다(시전 시간 2.5초). 차단하십시오.",
	["Lilith the Lithe, Everlook, Winterspring"] = "호리호리한 릴리스, 여명의 설원 눈망루 마을",
	["Listen to Kharan Mighthammer tell his story."] = "카란 마이트해머의 이야기를 들어야 합니다.",
