	["Llana"] = "라나",
	["Llana, Astranaar, Ashenvale"] = "라나, 잿빛 골짜기 아스트라나르",
	["Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."] = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다.",
	["Lokhtos Darkbargainer, inside the dungeon"] = "로크토스 다크바게이너, 던전 내부",
	["Lonebrow's Journal"] = "론브로우의 일지",
	["Long Forgotten Memories"] = "잊혀진 오랜 기억",
	["Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."] = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져가야 합니다. 목걸이는 손상되었을 수도 있습니다.",
	["Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site."] = "웰가르의 발굴현장에서 도린 송블레이드의 형제 대윈을 찾아야 합니다.",
	["Look in Dire Maul for Kariel Winthalus and report back to Sage Korolusk."] = "혈투의 전장에서 텔미우스 드림시커를 찾은 후 현자 코로루스크에게 보고해야 합니다.",
	["Look in Dire Maul for Kariel Winthalus and report back to Scholar Runethorn."] = "혈투의 전장에서 텔미우스 드림시커를 찾은 후 학자 룬쏜에게 보고해야 합니다.",
	["Look in Dire Maul for Telmius Dreamseeker and report back to Sage Korolusk."] = "혈투의 전장에서 텔미우스 드림시커를 찾은 후 현자 코로루스크에게 보고해야 합니다.",
	["Look in Dire Maul for Telmius Dreamseeker and report back to Scholar Runethorn."] = "혈투의 전장에서 텔미우스 드림시커를 찾은 후 학자 룬쏜에게 보고해야 합니다.",
	["Look in Uldaman for the dead paladin who last had Talvash's necklace."] = "탈바쉬의 목걸이를 마지막으로 가지고 있던 죽은 성기사를 울다만에서 찾아야 합니다.",
	["Looted from Edwin VanCleef"] = "에드윈 밴클리프에게서 획득",
	["Looted inside the Excavation Site."] = "발굴 현장 안에서 획득합니다.",
	["Lorax's Tale"] = "로락스의 이야기",
