	["Lowers a player's Physical damage for 30 seconds. A mage or a druid can remove it."] = "30초 동안 플레이어의 물리 피해를 감소시킵니다. 마법사나 드루이드가 해제할 수 있습니다.",
	["Lowers the Physical damage of everyone within 30 yards for 2 minutes. A mage or a druid can remove it."] = "2분 동안 30미터 내 모든 대상의 물리 피해를 감소시킵니다. 마법사나 드루이드가 해제할 수 있습니다.",
