	["Magus Tirth, Shimmering Flats, Thousand Needles"] = "학자 틸스, 소금 평원, 버섯구름 봉우리",
	["Magus Wordeen Voidglare, Tarren Mill, Hillsbrad Foothills"] = "학자 워딘 보이드글레어, 타렌 밀농장, 힐스브래드 구릉지",
	["Makes a player flee in fear for 4 seconds."] = "플레이어 하나를 4초 동안 공포에 질려 도망치게 합니다.",
	["Makes a player flee in terror for up to 8 seconds (1.5-second cast). Interrupt it."] = "플레이어 한 명을 최대 8초 동안 공포에 질려 도망치게 합니다(시전 시간 1.5초). 차단하십시오.",
	["Makes him immune to all damage and spells for 10 seconds."] = "10초 동안 모든 피해와 주문에 면역이 됩니다.",
	["Malfunction winds up for 2 seconds, then hits everyone within 25 yards every 2 seconds for 6 seconds: ranged stay beyond 25 yards, melee step out as the cast starts."] = "기능 장애는 2초 동안 준비한 뒤, 6초 동안 2초마다 25미터 내의 모두에게 피해를 줍니다. 원거리 공격수는 25미터 밖에 머무르고, 근접 공격수는 시전이 시작되면 빠져나오십시오.",
	["Malfurion Stormrage, inside the Sunken Temple"] = "말퓨리온 스톰레이지, 가라앉은 사원 내부",
	["Malyfous Darkhammer, Winterspring"] = "말리퍼스 다크해머, 여명의 설원",
	["Manamorph takes a player out of the fight for 8 seconds: dispel it. His Silence hits those close to him, so healers keep their distance."] = "마나변이체는 8초 동안 플레이어 한 명을 전투에서 이탈시킵니다. 해제하십시오. 침묵은 가까이 있는 플레이어에게 걸리므로 치유 전담은 거리를 두십시오.",
	["Marshal Maxwell, Burning Steppes"] = "치안대장 맥스웰, 불타는 평원",
	["Marshal Windsor"] = "치안대장 윈저",
