	["Master Apothecary Faranell — Apothecarium"] = "수석 연금술사 파라넬 — 연금술 실험실",
	["Master Apothecary Faranell, the Apothecarium, Undercity"] = "수석 연금술사 파라넬, 연금술 실험실, 언더시티",
