	["Megavolt hits a cone in front of it: only the tank should stand there. Interrupt its Chain Bolt."] = "100만 볼트는 전방 부채꼴 범위에 피해를 줍니다. 방어 전담만 앞에 서십시오. 연쇄 벼락은 차단하십시오.",
