	["Mistress Nagmara, inside the dungeon"] = "지배인 나그마라, 던전 내부",
	["Monika Sengutz, Tarren Mill, Hillsbrad Foothills"] = "모니카 센구츠, 타렌 밀농장, 힐스브래드 구릉지",
	["Monument of Franclorn Forgewright, inside the dungeon"] = "프랑클론 포지라이트의 기념비, 던전 내부",
	["Moonbrook Espionage"] = "문브룩 첩보 작전",
	["Moonbrook, Westfall"] = "서부 몰락지대 문브룩",
	["Moonshrine Sanctum"] = "달의 제단 성소",
	["Mor'zul Bloodbringer"] = "모르줄 블러드브링어",
	["Mor'zul Bloodbringer, Burning Steppes"] = "모르줄 블러드브링어, 불타는 평원",
	["Morbin Lightbane — Royal Quarter"] = "모빈 라이트베인 — 왕실",
	["Morbin Lightbane, Undercity"] = "모빈 라이트베인, 언더시티",
	["More attack power for him and his allies for 2 minutes."] = "2분 동안 자신과 아군의 전투력을 높입니다.",
	["More attack power for him and his hounds for 3 minutes."] = "3분 동안 자신과 하이에나의 전투력이 증가합니다.",
	["More Components of Importance"] = "또 다른 중요한 요소",
	["More Sparklematic Action"] = "삐까뻔쩍세척기 재사용",
	["More worgs"] = "검은늑대 증원",
	["Mortality Wanes"] = "꺼져가는 생명의 불씨",
	["Most players come to Rethiel by The Greenwarden, from First Mate Fitzsimmons in Menethil Harbor: it leads to Tramping Paws but is not needed for it."] = "대부분의 플레이어는 메네실 항구의 일등항해사 피츠시몬즈가 주는 '신록의수호자' 퀘스트를 통해 레시엘을 찾아옵니다. 이 퀘스트는 '파괴의 손길'로 이어지지만, '파괴의 손길'을 받는 데 꼭 필요하지는 않습니다.",
	["Mother's Milk"] = "여왕 거미의 독",
	["Motley Garmason — Dun Modr"] = "모틀리 가마슨 — 던 모드르",
	["Motley Garmason, Dun Modr, Wetlands"] = "모틀리 가마슨, 저습지 던 모드르",
	["Mount Hyjal"] = "하이잘 산",
	["Mr. Smite opens the fight with a sword and shield."] = "미스터 스마이트는 검과 방패를 들고 전투를 시작합니다.",
	["Muculent Rot"] = "눅눅한 부패",
	["Muigin and Larion"] = "무이긴과 라리온",
	["Muigin, Marshal's Refuge, Un'Goro Crater"] = "무이긴, 마샬의 야영지, 운고로 분화구",
	["Mulgore"] = "멀고어",
	["Muln Earthfury, Skywatcher Plateau, Mulgore"] = "멀른 어스퓨리, 멀고어 하늘감시자 고원",
	["Murdaloc"] = "멀달록",
	["Murloc Gills"] = "멀록 아가미",
	["Myranda the Hag, Western Plaguelands"] = "노파 미란다, 서부 역병지대",
	["Myriam Moonsinger, The Barrens"] = "미리암 문싱어, 불모의 땅",
	["Mythology of the Titans"] = "티탄 신화",
	["Nalpak"] = "날팍",
	["Nalpak, above the entrance to Wailing Caverns, The Barrens"] = "날팍, 불모의 땅 통곡의 동굴 입구 위",
	["Nara Wildmane"] = "나라 와일드메인",
	["Nara Wildmane, Thunder Bluff"] = "나라 와일드메인, 썬더 블러프",
	["Nathanos Blightcaller, Eastern Plaguelands"] = "나타노스 블라이트콜러, 동부 역병지대",
	["Nature damage every 5 seconds for 30 seconds to everyone near him."] = "30초 동안 5초마다 주위의 모두에게 자연 피해를 입힙니다.",
	["Nature damage every 5 seconds for 45 seconds to everyone nearby."] = "45초 동안 5초마다 주위의 모두에게 자연 피해를 입힙니다.",
	["Nature damage every 6 seconds and drained mana, for 2 minutes. Cure the poison."] = "2분 동안 6초마다 자연 피해를 입히고 마나를 흡수합니다. 독을 해제하십시오.",
	["Nature damage in a cone in front of her (2-second cast). Stay out of the cone."] = "전방 부채꼴 범위에 자연 피해를 입힙니다(시전 시간 2초). 범위 밖으로 피하십시오.",
	["Nature damage in a cone in front of it (2-second cast). Only the tank in front."] = "전방 부채꼴 범위에 자연 피해를 줍니다(시전 시간 2초). 방어 전담만 앞에 서십시오.",
	["Nature damage to everyone near him and a 2.5-second stun."] = "주위의 모두에게 자연 피해를 입히고 2.5초 동안 기절시킵니다.",
	["Nature damage to everyone near him, then slower attacks and movement for 10 seconds."] = "주위의 모두에게 자연 피해를 입히고, 10초 동안 공격 속도와 이동 속도를 늦춥니다.",
	["Nature damage to whoever hits her in melee."] = "근접 공격으로 자신을 때리는 대상에게 자연 피해를 입힙니다.",
	["Necklace Recovery"] = "목걸이 회수",
	["Necklace Recovery, Take 2"] = "목걸이 회수 - 2차 시도",
	["Necklace Recovery, Take 3"] = "목걸이 회수 - 3차 시도",
	["Needs Rig Wars accepted, not finished: take it from Nogg in Orgrimmar before Chief Engineer Scooty."] = "'기술 전쟁'을 수락한 상태여야 하며, 완료할 필요는 없습니다. '선임기술자 스쿠티' 퀘스트보다 먼저 오그리마의 노그에게서 받으십시오.",
	["Needs the Barrens oasis chain first: The Forgotten Pools, The Stagnant Oasis and Altered Beings, then Hamuul Runetotem and Nara Wildmane, before Leaders of the Fang opens."] = "송곳니의 드루이드 우두머리 퀘스트를 받으려면 먼저 불모의 땅 오아시스 연계 퀘스트(잊혀진 웅덩이, 죽은 오아시스, 변화된 생물)를 완료한 뒤 하뮬 룬토템과 나라 와일드메인 퀘스트를 거쳐야 합니다.",
	["Needs the Defias Brotherhood escort step first."] = "'데피아즈단' 호위 단계를 먼저 완료해야 합니다.",
	["Neeru Fireblade"] = "네루 파이어블레이드",
	["Neeru Fireblade, Cleft of Shadow, Orgrimmar"] = "네루 파이어블레이드, 오그리마 어둠의 틈",
	["Nekrum's Medallion"] = "네크룸의 메달",
	["New in Forever: Arcanist Doan has the book."] = "포에버 신규: 신비술사 도안이 책을 가지고 있습니다.",
	["New in Forever: part 2, given in the Undercity once the Abominable Head is with Master Apothecary Faranell."] = "포에버 신규: 2단계. 흉측한 머리를 수석 연금술사 파라넬에게 전달하면 언더시티에서 받습니다.",
	["New in Forever: part 3, in the Undercity."] = "포에버 신규: 3단계, 언더시티에서 진행합니다.",
	["New in Forever: part 4, in the Undercity."] = "포에버 신규: 4단계, 언더시티에서 진행합니다.",
	["New in Forever: the last part, back to Master Apothecary Faranell in the Undercity."] = "포에버 신규: 마지막 단계. 언더시티의 수석 연금술사 파라넬에게 돌아갑니다.",
	["Nikova Raskol — Old Town"] = "니코바 라스콜 — 구 시가지",
	["Nikova Raskol, Old Town, Stormwind"] = "니코바 라스콜, 스톰윈드 구 시가지",
	["Nogg — Valley of Honor, Orgrimmar"] = "노그 — 명예의 골짜기, 오그리마",
	["Nogg's Ring Redo"] = "노그의 반지 수리",
	["Nogg, Orgrimmar"] = "노그, 오그리마",
	["Nogg, Valley of Honor, Orgrimmar"] = "노그, 명예의 골짜기, 오그리마",
	["Northern Azshara"] = "북부 아즈샤라",
	["Northern Barrens"] = "북부 불모의 땅",
	["Nostro's Compendium"] = "노스트로의 용사냥 개론",
	["Nostro's Compendium of Dragon Slaying"] = "노스트로의 용사냥 개론",
	["Not always in the same place inside Ruins of Lordaeron."] = "로데론의 폐허 안에서 위치가 항상 같지는 않습니다.",
	["Nothing special on the boss itself. Clear the other spiders of the courtyard first, or they join the fight."] = "우두머리 자체에는 특별한 것이 없습니다. 안뜰의 다른 거미들을 먼저 처치하십시오. 그렇지 않으면 전투에 합류합니다.",
	["Nothing special on the boss itself: clear the other spiders of the courtyard first, or they join the fight."] = "우두머리 자체에는 특별한 것이 없습니다. 안뜰의 다른 거미들을 먼저 처치하십시오. 그렇지 않으면 전투에 합류합니다.",
	["Now and then he swings twice more at once, and Strike adds damage to his next hit: the tank takes heavy blows."] = "이따금 한 번에 두 번을 더 공격하고, 일격으로 다음 공격의 피해를 높입니다. 방어 전담이 큰 피해를 받습니다.",
	["Now and then two extra attacks: heavy hits on the tank."] = "가끔 두 번 추가로 공격하여 방어 전담에게 큰 피해를 입힙니다.",
	["Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."] = "울다만에서 찾을 수 있는 가장 강력한 피조물에게서 마력원천을 구해 아이언포지에 있는 탈바쉬 델 키젤에게 전달해야 합니다.",
	["Oculus Illusions"] = "눈동자의 환영",
	["Of Coursers We Know"] = "순록을 찾아서",
	["Of Forgotten Memories"] = "잃어버린 기억들",
	["Of Lost Honor"] = "명예의 상징",
	["Of Love and Family"] = "가족과 사랑",
	["Offered once one of the four Right Piece of Lord Valthalak's Amulet quests is done."] = "'군주 발타라크의 아뮬렛 오른쪽 조각' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다.",
	["Ogtinc, Azshara"] = "오그틴크, 아즈샤라",
	["Oh Brother..."] = "형제여...",
	["Old Ironforge Incursion"] = "구 아이언포지 침투",
	["On a round terrace in the city streets, just out of the sewers. It casts Arcane Bolt and Focal Blast."] = "하수구를 막 빠져나온 곳, 도시 거리의 둥근 테라스에 있습니다. 비전 화살과 초점 폭발을 시전합니다.",
	["Once a temple to Elune on the Ashenvale shore, Blackfathom Deeps sank beneath the sea in the Sundering. The Twilight's Hammer now holds its flooded halls, guarding Aku'mai, a beast prized by the Old Gods, while naga and murlocs prowl its pools."] = "한때 잿빛 골짜기 해안에 있던 엘룬의 신전인 검은심연 나락은 세계의 분리 때 바다 밑으로 가라앉았습니다. 지금은 황혼의 망치단이 물에 잠긴 전당을 차지하고 고대 신이 아끼는 짐승 아쿠마이를 지키고 있으며, 나가와 멀록이 웅덩이를 배회합니다.",
	["Once Kelris is dead, light the four Fires of Aku'mai one after another; each brings a wave, and the door opens when all are dead."] = "켈리스가 죽으면 아쿠마이의 불꽃 네 개를 차례로 밝히십시오. 불꽃마다 적 무리가 몰려오며, 모두 처치하면 문이 열립니다.",
	["Once Twilight Lord Kelris is dead, light the four Fires of Aku'mai in his room, one after the other. Each one brings a wave of creatures. When all are dead, the door to Aku'mai opens."] = "황혼의 군주 켈리스가 죽으면 그의 방에 있는 아쿠마이의 불꽃 네 개를 하나씩 차례로 밝히십시오. 불꽃을 밝힐 때마다 몬스터 무리가 몰려옵니다. 모두 처치하면 아쿠마이에게 가는 문이 열립니다.",
	["One of the four Fanglords; killing all four lets the Disciple of Naralex begin the ritual."] = "송곳니의 드루이드 우두머리 넷 중 하나입니다. 넷을 모두 처치하면 나랄렉스의 신도가 의식을 시작할 수 있습니다.",
	["One of the six challengers the Ring of Law sends into the arena: only one comes each time."] = "법의 심판장이 투기장에 내보내는 도전자 여섯 중 하나로, 매번 한 명만 나옵니다.",
	["One run may not have enough of these creatures to finish it."] = "한 번의 공략으로는 이 퀘스트를 끝낼 만큼 적이 충분하지 않을 수 있습니다.",
	["Only One May Rise"] = "최후의 한 명",
	["Only the Fel Steed stomps: a 3-second stun, and more physical damage taken."] = "발 구르기는 지옥마만 사용합니다. 3초 동안 기절하고, 받는 물리 피해가 증가합니다.",
	["Open the Argent Hold and claim your reward."] = "여명회의 궤를 열고 보상을 받아야 합니다.",
	["Open the Maw"] = "아귀를 열어라",
	["Opens once The Dark Iron War is done."] = "'검은무쇠단과의 전투' 퀘스트를 완료하면 받을 수 있습니다.",
	["Operation: Death to Angerforge"] = "앵거포지 척살 작전",
	["Operative Bijou"] = "요원 비쥬",
	["Opportunistic Education"] = "기회를 틈탄 배움",
	["Oralius, Burning Steppes"] = "랄리우스, 불타는 평원",
	["Oran Snakewrithe, Undercity"] = "오란 스네이크레이드, 언더시티",
	["Orgrimmar"] = "오그리마",
	["Orphan Matron Nightingale, Stormwind City"] = "보육원 원장님 나이팅게일, 스톰윈드",
	["Overmaster Pyron"] = "멸망의 파이론",
	["Ozzie Togglevolt — Kharanos"] = "오지 토글볼트 — 카라노스",
	["Ozzie Togglevolt, Dun Morogh"] = "오지 토글볼트, 던 모로",
	["Ozzie Togglevolt, Kharanos, Dun Morogh"] = "오지 토글볼트, 카라노스, 던 모로",
	["Parqual Fintallas, The Apothecarium, Undercity"] = "파쿠알 핀탈라스, 연금술 실험실, 언더시티",
	["Parqual Fintallas, Undercity"] = "파쿠알 핀탈라스, 언더시티",
	["Part of the Test of Faith chain, which starts with Dorn Plainstalker in Thousand Needles. The book is on a table in the first room on the left past the courtyard."] = "버섯구름 봉우리의 도른 플레인스토커에게서 시작하는 믿음의 시험 연계 퀘스트의 일부입니다. 책은 안뜰을 지나 왼쪽 첫 번째 방의 탁자 위에 있습니다.",
	["Passing Word of a Threat"] = "위협의 경고",
	["Past Atrexis, clear the north-east room with the market stalls and the small pink summoning circle. Whoever carries the tome clicks the circle, and Lyn comes out of the big round grate."] = "아트렉시스를 지나 시장 노점과 작은 분홍색 소환 마법진이 있는 북동쪽 방을 정리하십시오. 고서를 가진 사람이 마법진을 클릭하면 린이 크고 둥근 쇠창살에서 나옵니다.",
	["Past Due"] = "기한 초과",
	["Patrick Garrett, Undercity"] = "패트릭 가레트, 언더시티",
	["Pit of Fangs"] = "송곳니 구덩이",
	["Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."] = "스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다.",
	["Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."] = "가라앉은 사원의 이 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다.",
	["Place the explosives beside the forge in the Deadmines."] = "죽음의 폐광의 용광로 옆에 폭발물을 설치해야 합니다.",
	["Plagued Hatchlings"] = "역병 걸린 작은 새끼용",
	["Poison"] = "독",
	["Poison Cloud hurts everyone nearby, and below 30% health he attacks much faster."] = "독구름이 주위의 모두에게 피해를 입히며, 생명력이 30% 아래로 떨어지면 공격 속도가 크게 빨라집니다.",
	["Poison on the spider trail"] = "거미 길의 독",
	["Poisoned Water"] = "독이 든 물",
	["Poisons his target. Druids and shamans (Cure Poison) and paladins (Purify or Cleanse) can take it off; otherwise, watch the health bars."] = "대상을 중독시킵니다. 드루이드와 주술사(해독), 성기사(순화 또는 정화)가 해제할 수 있습니다. 그렇지 않다면 생명력 바를 주시하십시오.",
	["Pool of Tears"] = "눈물의 연못",
	["Power in Uldaman"] = "울다만의 마력원천",
	["Power Overwhelming"] = "압도적인 힘",
	["Power Stones"] = "마법석",
	["Precarious Predicament"] = "곤경",
	["Prehistoric Prism"] = "선사 시대의 프리즘",
	["Princess Moira Bronzebeard, inside the dungeon"] = "공주 모이라 브론즈비어드, 던전 내부",
	["Prison Break In"] = "감옥 습격",
	["Private Rocknot, inside Blackrock Depths"] = "병사 락노트, 검은바위 나락 내부",
	["Proof of Life"] = "생존의 증거",
	["Prospect of Faith"] = "돈독한 믿음",
	["Prospector Ironband, Loch Modan"] = "발굴조사단장 아이언밴드, 모단 호수",
	["Prospector Ironboot, Tanaris"] = "발굴조사단장 아이언부트, 타나리스",
	["Prospector Ryedol, Badlands"] = "발굴조사단장 라이돌, 황야의 땅",
	["Prospector Stormpike, Ironforge"] = "발굴조사단장 스톰파이크, 아이언포지",
	["Prospector Whelgar, Whelgar's Excavation Site, Wetlands"] = "발굴조사단장 웰가르, 저습지 웰가르의 발굴현장",
	["Pusillin and the Elder Azj'Tordin"] = "푸실린과 노쇠한 아즈토르딘",
	["Put a Grime-Encrusted Item into the Sparklematic 5200 to have it cleaned."] = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣어 세척하십시오.",
	["Put a Grime-Encrusted Object in the Sparklematic 5200; you need 3 silver to run it."] = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 작동하려면 3실버가 필요합니다.",
	["Put Her Down"] = "검은늑대 위협의 근원 파괴",
	["Put the spirit of Faldrim Anvilmar to rest."] = "팔드림 앤빌마의 영혼을 잠재워야 합니다.",
	["Puts a player to sleep for up to 15 seconds."] = "플레이어 한 명을 최대 15초 동안 잠재웁니다.",
	["Puts a player to sleep for up to 20 seconds."] = "플레이어 한 명을 최대 20초 동안 잠재웁니다.",
	["Puts a player to sleep for up to 20 seconds. Damage wakes them, and a Magic dispel removes it."] = "플레이어 한 명을 최대 20초 동안 잠재웁니다. 피해를 입으면 깨어나며, 마법 해제로 없앨 수 있습니다.",
	["Puts a player to sleep."] = "플레이어 한 명을 잠재웁니다.",
	["Puts everyone near him to sleep for up to 10 seconds. Damage wakes a sleeper."] = "주위의 모두를 최대 10초 동안 잠재웁니다. 피해를 입으면 깨어납니다.",
	["Quell the Uprising"] = "폭동 진압",
	["Rabine Saturna, Nighthaven, Moonglade"] = "라빈 사투르나, 나이트헤이븐, 달의 숲",
	["Rage of Blood"] = "피의 광란",
	["Ragged John, Burning Steppes"] = "털보 존, 불타는 평원",
	["Ragnar Thunderbrew"] = "라그나르 썬더브루",
	["Ragnar Thunderbrew, Dun Morogh"] = "라그나르 썬더브루, 던 모로",
	["Rahauro"] = "라하우로",
	["Rahauro, Elder Rise, Thunder Bluff"] = "라하우로, 썬더 블러프 장로의 봉우리",
	["Raises skeletons through the fight: kill them, and give the tank time to build threat before using area damage."] = "전투 내내 해골을 일으킵니다. 해골을 처치하되, 광역 공격을 쓰기 전에 방어 전담이 위협 수준을 쌓을 시간을 주십시오.",
	["Raleigh the Devout, Southshore, Hillsbrad Foothills"] = "경건한 신자 랄레이, 사우스쇼어, 힐스브래드 구릉지",
	["Ramstein"] = "람스타인",
	["Raptor Horns"] = "랩터 뿔",
	["Ratchet"] = "톱니항",
	["Rau Cliffrunner"] = "라우 클리프러너",
	["Rau Cliffrunner, Thousand Needles"] = "라우 클리프러너, 버섯구름 봉우리",
	["Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike."] = "밸로그의 일지를 읽고 비밀 석실을 탐험한 후 발굴조사단장 스톰파이크에게 보고해야 합니다.",
	["Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."] = "모르줄의 지시서를 읽어야 합니다. 소로시안 공포마를 소환해 쓰러뜨린 다음, 그 영혼을 자신에게 귀속시키십시오.",
	["Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."] = "추방자의 지시서를 읽어야 합니다. 그런 다음 마라우돈에서 결속의 아뮬렛을 구해 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.",
	["Read the Tablet of Theka in Zul'Farrak to learn the spider god's name, then go back to Master Gadrin."] = "줄파락에서 데카의 서판을 읽고 거미 신의 이름을 알아낸 후 장로 가드린에게 돌아가야 합니다.",
	["Read Warosh's Scroll. Bring Warosh's Mojo to Warosh."] = "와로쉬의 두루마리를 읽고, 와로쉬의 모조를 와로쉬에게 가져가야 합니다.",
	["Reclaimed Treasures"] = "보물 되찾기",
	["Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."] = "스트라솔름에서 역병걸린 살덩어리 견본 10개를 구해 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다.",
	["Recover a Core Fragment at the Molten Core entry portal inside Blackrock Depths, then go back to Lothos Riftwaker."] = "검은바위 나락 안에 있는 화산 심장부 입구 차원문에서 핵 조각을 찾은 후 로소스 리프트웨이커에게 돌아가야 합니다.",
	["Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman."] = "울다만에서 목걸이에 쓸 보석 세 개와 마력원천을 모두 되찾아 카르가스에 있는 자칼 모스멜드에게 가져가야 합니다. 자칼은 울다만에서 가장 강력한 피조물이 마력원천을 지니고 있을 것이라고 생각합니다.",
	["Recover an Ancient Gurubashi Idol from the Drowned City."] = "가라앉은 도시에서 고대 구루바시 신상을 되찾아야 합니다.",
	["Recover the Fathom Core from the Fathom Stone in Blackfathom Deeps."] = "검은심연 나락의 심연의 돌에서 심연의 핵을 회수해야 합니다.",
	["Recover The Founding of Dalaran and deliver it to Rexxie Copperclutch."] = "달라란 건국기를 되찾아 렉시 코퍼클러치에게 전달해야 합니다.",
	["Recover the Gnoam Sprecklesprocket from Sneed's Shredder."] = "스니드의 벌목기에게서 노암 톱니구동장치를 되찾아야 합니다.",
	["Recover the Lorgalis Manuscript from Blackfathom Deeps."] = "검은심연 나락에서 로르갈리스 초본을 찾아와야 합니다.",
	["Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond."] = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다.",
	["Recover Thistlenettle's Badge from Foreman Thistlenettle in the undead side tunnel."] = "언데드가 있는 옆 갱도의 현장감독 시슬네틀에게서 시슬네틀의 배지를 되찾아야 합니다.",
	["Red Silk Bandanas"] = "붉은 비단 복면",
	["Redemption"] = "구원",
	["Remains of a Paladin, inside Uldaman"] = "성기사의 유해, 울다만 내부",
	["Remember That I Love You"] = "사랑한다는 걸 잊지 마",
	["Remove his Veil of Shadow, above all from the tank: healing on them is much weaker."] = "암흑의 장막은 특히 방어 전담에게서 반드시 해제하십시오. 걸린 대상은 받는 치유량이 크게 줄어듭니다.",
	["Repeatable."] = "반복 가능.",
	["Repeatable: for when the phial is lost."] = "반복 가능: 유리병을 잃어버렸을 때 받습니다.",
	["Replacement Phial"] = "수정점의 유리병 다시 받기",
	["Report back to Master Apothecary Faranell in the Undercity."] = "언더시티에 있는 수석 연금술사 파라넬에게 돌아가 보고해야 합니다.",
	["Report Daewyn's fate to Dorin Songblade in Lakeshire."] = "대윈의 운명을 레이크샤이어의 도린 송블레이드에게 알려야 합니다.",
	["Report to Tinkmaster Overspark in Ironforge."] = "아이언포지에 있는 수석땜장이 오버스파크에게 보고해야 합니다.",
	["Reported random spawn inside Ruins of Lordaeron; check towers, side rooms and the Bjork area"] = "로데론의 폐허 안 무작위 위치에 나타난다는 보고가 있습니다. 탑, 곁방, 비요크 주변을 확인하십시오",
	["Researching the Corruption"] = "타락에 대한 연구",
	["Restoring the Necklace"] = "목걸이 복원",
	["Rethiel the Greenwarden — Wetlands"] = "신록의수호자 레시엘 — 저습지",
	["Rethiel the Greenwarden, Wetlands"] = "신록의수호자 레시엘, 저습지",
	["Retrieve a Fel Infused Blossom from Dalaran's central garden."] = "달라란 중앙 정원에서 지옥 마력이 주입된 꽃을 가져와야 합니다.",
	-- A Green Sample's note (the owner, 2026-11-11; drafted, to be checked)
	["The Fel Infused Blossom grows on the ground near the Fel Ancient, in the central garden: pick it up there."] = "지옥 마력이 주입된 꽃은 중앙 정원의 지옥의 고대정령 근처 땅에서 자랍니다. 그곳에서 주우세요.",
	["Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge."] = "수도원에서 티탄 신화를 찾아 아이언포지에 있는 사서 메이 페일더스트에게 가져가야 합니다.",
	["Retrieve the 99-Year-Old Port from Mad Magglish in Wailing Caverns."] = "통곡의 동굴에 있는 광기의 매글리시에게서 99년 묵은 포트 와인을 되찾아야 합니다.",
	["Retrieve the Compendium of the Fallen from the Monastery and return to Sage Truthseeker in Thunder Bluff."] = "수도원에서 타락의 개요를 찾아 썬더 블러프에 있는 현자 트루스시커에게 돌아가야 합니다.",
	["Retrieve The Lost Magic of the Runemasters from the Scarlet Monastery."] = "붉은십자군 수도원에서 룬술사들의 잃어버린 마법을 찾아와야 합니다.",
	["Retrieve the Rig Blueprints and Thermaplugg's Safe Combination and bring them to Nogg in Orgrimmar."] = "장치 설계도와 텔마플러그의 금고 암호를 찾아 오그리마에 있는 노그에게 가져가야 합니다.",
	["Return Foror's Compendium of Dragon Slaying to the Athenaeum."] = "노스트로의 용사냥 개론을 도서관에 돌려주어야 합니다.",
	["Return Nostro's Compendium of Dragon Slaying to the Athenaeum."] = "노스트로의 용사냥 개론을 도서관에 돌려주어야 합니다.",
	["Return of the Ring"] = "반지의 귀환",
	["Return the book to its rightful owners."] = "책을 원래 주인에게 돌려주어야 합니다.",
	["Return the Crest of Lordaeron to Stormwind."] = "로데론의 문장을 스톰윈드로 가져가야 합니다.",
	["Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan."] = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다.",
	["Return to Bodley"] = "보들리에게 돌아가기",
	["Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning."] = "검은바위 산 안에 있는 보들리에게 돌아가 부름의 화로를 건네야 합니다.",
	["Return to Fel'Zerul"] = "펠제룰에게 돌아가기",
	["Return to Ironforge and speak with King Magni Bronzebeard."] = "아이언포지로 돌아가서 국왕 마그니 브론즈비어드와 대화해야 합니다.",
	["Return to Thrall!"] = "스랄에게 돌아가야 합니다!",
	["Return to Tinkee"] = "팅키에게 돌아가는 길",
	["Return Vorrel Sengutz's wedding ring (from Nancy Vishas) to Monika Sengutz in Tarren Mill."] = "보렐 센구츠의 결혼반지(낸시 비샤스에게서 얻음)를 타렌 밀농장에 있는 모니카 센구츠에게 돌려주어야 합니다.",
	["Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."] = "축복받은 아케이나이트 마갑을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.",
	["Returning the Lost Satchel"] = "잃어버린 가방 돌려주기",
	["Rexxar, Feralas"] = "렉사르, 페랄라스",
	["Rexxie Copperclutch, inside the dungeon, near the sewer entrance"] = "렉시 코퍼클러치, 던전 내부, 하수구 입구 근처",
	["Rhapsody Shindigger"] = "랩소디 신디거",
	["Rhapsody's Kalimdor Kocktail"] = "랩소디의 칼림도어 칵테일",
	["Rhapsody's Tale"] = "랩소디의 이야기",
	["Ribbly Screwspigot"] = "리블리 스크류스피곳",
	["Rig Wars"] = "기술 전쟁",
	["Rigglefuzz, Badlands"] = "리글퍼즈, 황야의 땅",
	["Rituals of Power"] = "마력의 의식",
	["Riverglades"] = "강물터",
	["Rocknot's Ale"] = "락노트의 에일 맥주",
	["Roogug drops the Vial of Phlogiston."] = "루구그에게서 연소 약병을 획득할 수 있습니다.",
	["Roots a player for 10 seconds and drains their health into his. Interrupt the 2-second cast or dispel it."] = "플레이어 한 명을 10초 동안 묶고 그 생명력을 흡수해 자신의 생명력을 회복합니다. 2초 시전을 차단하거나 해제하십시오.",
	["Roots a player in place for 10 seconds."] = "플레이어 한 명을 10초 동안 그 자리에 묶습니다.",
	["Roots everyone near him for up to 8 seconds."] = "주위의 모두를 최대 8초 동안 묶습니다.",
	["Roots everyone near it for 10 seconds."] = "10초 동안 근처의 모든 대상을 이동 불가 상태로 만듭니다.",
	["Roots up to two players near him for a few seconds and hurts them over time. It is magic: dispel it."] = "주위의 플레이어를 최대 2명까지 몇 초 동안 묶고 지속 피해를 줍니다. 마법 효과이므로 해제하십시오.",
	["Runs for help"] = "도움 요청",
	["Rut'theran Village"] = "루테란 마을",
	["Sage Korolusk, Feralas"] = "현자 코로루스크, 페랄라스",
	["Sage Truthseeker — Thunder Bluff"] = "현자 트루스시커 — 썬더 블러프",
	["Sage Truthseeker, Thunder Bluff"] = "현자 트루스시커, 썬더 블러프",
	["Sagorne Creststrider"] = "사고른 크레스트스트라이더",
	["Sagorne Creststrider, Valley of Wisdom, Orgrimmar"] = "사고른 크레스트스트라이더, 오그리마 지혜의 골짜기",
	["Save Techbot's Brain!"] = "고장난 첨단로봇 수리",
	["Scarab Shells"] = "왕쇠똥구리 껍질",
	["Scarlet Tracking Hounds"] = "붉은십자군 추적용 하이에나",
	["Scarlet Trainees"] = "붉은십자군 신병",
	["Scarshield Infiltrator, inside Lower Blackrock Spire"] = "방패부대 첩보원, 검은바위 첨탑 하층 내부",
	["Scarshield Infiltrator, inside the dungeon"] = "방패부대 첩보원, 던전 내부",
	["Scholar Runethorn, Feralas"] = "학자 룬쏜, 페랄라스",
	["Scooty — Booty Bay"] = "스쿠티 — 무법항",
	["Scooty, Booty Bay"] = "스쿠티, 무법항",
	["Scooty, Booty Bay, Stranglethorn Vale"] = "스쿠티, 무법항, 가시덤불 골짜기",
	["Scourge of the Downs"] = "가시덩굴 구릉의 스컬지",
	["Scout Riell"] = "정찰병 리엘",
	["Scout Riell, Sentinel Hill tower, Westfall"] = "정찰병 리엘, 서부 몰락지대 감시의 언덕 탑",
	["Screaming Gully"] = "울부짖는 협곡",
	["Screecher Spirits"] = "계곡천둥매의 영혼",
	["Seal of Ascension"] = "승천의 인장",
	["Sealed Azure Bag"] = "봉인된 하늘색 자루",
	["Search deep in Uldaman for a clue to where the necklace's gems went."] = "울다만 깊은 곳에서 목걸이의 보석이 어디로 갔는지 단서를 찾아야 합니다.",
	["Search for the original creator of the shattered necklace to learn of its potential value."] = "부서진 목걸이를 처음 만든 사람을 찾아 그 가치를 알아내야 합니다.",
	["Searching for the Lost Satchel"] = "잃어버린 가방 찾기",
	["Secret of the Circle"] = "돌무리의 비밀",
	["Seed of Life"] = "생명의 씨앗",
	["Seek out Remulos in Moonglade and give him the Seed of Life."] = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.",
	["Seeking Caitlin"] = "케이틀린을 찾아서",
	["Selendra"] = "셀렌드라",
	["Selendra, near Shadowprey Village, Desolace"] = "셀렌드라, 그늘수렵 마을 근처, 잊혀진 땅",
	["Seril Scourgebane"] = "세릴 스컬지베인",
	["Seril Scourgebane, Everlook, Winterspring"] = "세릴 스컬지베인, 여명의 설원 눈망루 마을",
	["Serpentbloom"] = "불뱀꽃",
	["Seven Dark Iron ghosts fought one after another; their loot is in the Chest of The Seven, which appears when the last of them falls."] = "검은무쇠단 유령 일곱과 차례로 싸웁니다. 전리품은 마지막 유령이 쓰러지면 나타나는 일곱 현자의 궤짝에 들어 있습니다.",
	["Shackle Grark Lorkrub in the Blackrock fortress and lead him through Blackrock Mountain to Searing Gorge."] = "검은바위 요새에서 그랄크 로크럽에게 족쇄를 채운 후, 검은바위 산을 지나 이글거리는 협곡까지 데려가야 합니다.",
	["Shadow Bolt Volley and Curse of Thorns together hurt: remove the curse, melee above all. He raises skeletons as Atrexis does."] = "연발 어둠의 화살과 가시의 저주가 겹치면 위험합니다. 저주를 해제하되, 특히 근접 공격수의 저주를 먼저 해제하십시오. 아트렉시스처럼 해골을 일으킵니다.",
	["Shadow bolts at everyone within 30 yards of him."] = "주위 30미터 내의 모두에게 어둠의 화살을 날립니다.",
	["Shadow damage on a player (1.5-second cast)."] = "플레이어 한 명에게 암흑 피해를 입힙니다(시전 시간 1.5초).",
	["Shadow damage to his target every 3 seconds for 18 seconds. A Magic dispel removes it."] = "18초 동안 3초마다 대상에게 암흑 피해를 줍니다. 마법 해제로 제거할 수 있습니다.",
	["Shadowmage Vivian Lagrave, Badlands"] = "어둠마법사 비비안 라그레이브, 황야의 땅",
	["Shadowshard Fragments"] = "음영석 조각",
	["Shards of the Felvine"] = "악령덩굴 조각",
	["She appears at one of four places. Interrupt her Healing Touch; damage or a magic dispel wakes a sleeping player, and her Thorns Aura hurts melee."] = "네 곳 중 한 곳에 나타납니다. 치유의 손길을 차단하십시오. 잠든 플레이어는 피해를 입거나 마법 해제를 받으면 깨어나며, 가시 오라는 근접 공격수에게 피해를 줍니다.",
	["She keeps her distance and casts it again and again: lightning that jumps to up to 3 players (2.5-second cast). Interrupt it."] = "거리를 유지하며 계속해서 시전합니다. 최대 3명의 플레이어에게 튀는 번개입니다(시전 시간 2.5초). 차단하십시오.",
	["Shell Shield: for 12 seconds he takes much less damage, and hits slower but harder."] = "껍질 방패: 12초 동안 받는 피해가 크게 줄고, 공격이 느려지는 대신 강해집니다.",
	["Shen'dralar Ancient, inside Dire Maul"] = "셴드랄라 고대인, 혈투의 전장 내부",
	["Shen'dralar Ancient, inside the dungeon"] = "셴드랄라 고대인, 던전 내부",
	["Shield Slam stuns the tank; at 15% health he runs for help."] = "방패 밀쳐내기로 방어 전담을 기절시킵니다. 생명력이 15%가 되면 도움을 청하러 도망칩니다.",
	["Shields her against damage for up to 30 seconds. A priest or a shaman can remove it."] = "최대 30초 동안 자신에게 피해를 막는 보호막을 씌웁니다. 사제나 주술사가 해제할 수 있습니다.",
	["Shields himself against spells for a while."] = "한동안 자신에게 주문을 막는 보호막을 두릅니다.",
	["Shoni the Shilent — Dwarven District, Stormwind"] = "소리없는 쇼니 — 스톰윈드 드워프 지구",
	["Shoni the Shilent, Stormwind"] = "소리없는 쇼니, 스톰윈드",
	["Shoni the Shilent, Stormwind City"] = "소리없는 쇼니, 스톰윈드",
	["Shoni the Shilent, the Dwarven District, Stormwind"] = "소리없는 쇼니, 스톰윈드 드워프 지구",
	["Shylamiir — Stormwind City"] = "샤이라미르 — 스톰윈드",
	["Shylamiir, Stormwind City"] = "샤이라미르, 스톰윈드",
	["Silences everyone within 15 yards for 10 seconds (1.5-second cast). Healers, stand further back."] = "15미터 내의 모든 대상을 10초 동안 침묵시킵니다(시전 시간 1.5초). 치유 전담은 더 멀리 떨어져 서십시오.",
	["Silences for 10 seconds. Healers, keep your distance from it."] = "10초 동안 침묵시킵니다. 치유 전담은 거리를 두십시오.",
	["Silverpine Forest"] = "은빛소나무 숲",
	["Site of the Guardian"] = "수호자의 터",
	["Six troll defenders on the balconies around the temple's pit: Gasher, Hukku, Loro, Mijan, Zolo and Zul'Lor. With all six dead, the way to Jammal'an opens. The pins mark where each stands."] = "신전 구덩이를 둘러싼 발코니에 트롤 수호자 여섯이 있습니다: 게이셔, 후쿠, 로로, 마이잔, 졸로, 줄로. 여섯을 모두 처치하면 잠말란에게 가는 길이 열립니다. 핀은 각 트롤이 서 있는 위치를 표시합니다.",
	["Skeletons keep rising around the circle during the fight. They are weak: kill them as they come."] = "전투 중에 마법진 주위에서 해골이 계속 일어납니다. 약하니 나오는 대로 처치하십시오.",
	["Skeletons rise and fight beside him. Kill them."] = "해골들이 일어나 그의 곁에서 싸웁니다. 처치하십시오.",
	["Skyborne only"] = "스카이본 전용",
	["Skywatcher Plateau"] = "하늘감시자 고원",
	["Slay Arcanic Enigma, the Mana Elemental in the City of Dalaran, and return to High Sorcerer Andromath in Stormwind City."] = "달라란에 있는 마나 정령 비전 수수께끼를 처치하고 스톰윈드의 고위마술사 안드로매스에게 돌아가야 합니다.",
	["Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell."] = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다.",
	["Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."] = "파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다.",
	["Slay Halycon, pack mistress of the Bloodaxe worg."] = "도끼부대 검은늑대 무리의 어미, 할리콘을 처치해야 합니다.",
	["Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."] = "대군주 오모크, 대장군 부네, 대군주 웜타라크를 처치하고 중요한 검은바위 문서를 되찾아야 합니다. 임무를 완수하면 카르가스에 있는 장군 고어투스에게 돌아가십시오.",
	["Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace."] = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다.",
	["Slay Pyroguard Emberseer in Upper Blackrock Spire and bring his eye to Duke Hydraxis in Azshara."] = "검은바위 첨탑 상층에서 불의수호자 엠버시어를 처치하고 그의 눈을 아즈샤라에 있는 군주 히드락시스에게 가져가야 합니다.",
	["Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart."] = "욕망의 타라가만을 처치하고 타라가만의 심장을 회수해야 합니다.",
	["Slaying the Beast"] = "야수 처단",
	["Sleep"] = "수면",
	["Slows a player's attacks and movement for 10 seconds, and can stun them."] = "10초 동안 플레이어의 공격 속도와 이동 속도를 감소시키며, 기절시킬 수도 있습니다.",
	["Slows a player's casting by 35% for 15 seconds."] = "15초 동안 플레이어 하나의 시전 속도를 35% 감소시킵니다.",
	["Slows a player's movement and attacks for 10 seconds."] = "10초 동안 플레이어 한 명의 이동 속도와 공격 속도를 늦춥니다.",
	["Slows everyone near him for 3 seconds: attacks and casts 30% slower, movement 70% slower."] = "주위의 모두를 3초 동안 느려지게 합니다. 공격 속도와 시전 속도가 30%, 이동 속도가 70% 감소합니다.",
	["Slows his target's movement for 10 seconds."] = "10초 동안 대상의 이동 속도를 늦춥니다.",
	["Small raptors leap out of the grass as you walk through it, and make you bleed."] = "풀숲을 지나가면 작은 랩터들이 튀어나와 출혈을 일으킵니다.",
	["Small Scroll"] = "작은 두루마리",
	["Small Scroll, dropped by Charlga Razorflank in Razorfen Kraul"] = "작은 두루마리, 가시덩굴 우리의 서슬깃 차를가에게서 획득",
	["Smart Drinks"] = "영리해지는 음료",
	["Smokey LaRue, Eastern Plaguelands"] = "스모키 라루, 동부 역병지대",
	["Snakestone of the Shadow Huntress"] = "어둠사냥꾼의 뱀돌",
	["Sneed fights from inside the shredder, and climbs out when it is destroyed."] = "스니드는 벌목기에 탄 채 싸우다가, 벌목기가 파괴되면 밖으로 나옵니다.",
	["Solution to Doom"] = "멸망의 해결책",
	["Sometimes found among the Dark Iron agents."] = "검은무쇠단 첩보원들 사이에서 가끔 나타납니다.",
	["Sometimes found in the bat caves."] = "박쥐 동굴에서 가끔 나타납니다.",
	["Sometimes found in the side passage after Rhahk'Zor."] = "라크조르 다음의 옆 통로에서 가끔 나타납니다.",
	["Songblade Search"] = "송블레이드를 찾아서",
	["Soulbound Keepsake"] = "영혼이 씌인 유품",
	["Source of Power"] = "힘의 근원",
	["Southshore"] = "사우스쇼어",
	["Sovik, Valley of Honor, Orgrimmar"] = "소빅, 명예의 골짜기, 오그리마",
	["Speak to Blastmaster Emi Shortfuse and protect her while she seals the two cave mouths: troggs come in waves, then Grubbis with Chomper."] = "폭발물전문가 에미 쇼트퓨즈에게 말을 걸고, 그녀가 동굴 입구 두 곳을 봉쇄하는 동안 보호하십시오. 트로그가 여러 차례 몰려온 뒤 그루비스가 강철이빨 바실리스크와 함께 나타납니다.",
	["Speak to Dorn Plainstalker in Thousand Needles."] = "버섯구름 봉우리에 있는 도른 플레인스토커와 대화해야 합니다.",
	["Speak to Je'neu Sancrea in Ashenvale."] = "잿빛 골짜기에 있는 제네우 생크리와 대화해야 합니다.",
	["Speak with Caitlin Grassman in Menethil Harbor."] = "메네실 항구에 있는 케이틀린 그라스만과 대화해야 합니다.",
	["Speak with Scooty in Booty Bay."] = "무법항에 있는 스쿠티와 대화하십시오.",
	["Speak with Yeh'kinya."] = "예킨야와 대화해야 합니다.",
	["Spectral Chalice"] = "유령의 성배",
	["Spectral Chalice, inside the dungeon"] = "유령의 성배, 던전 내부",
	["Speeds up his or an ally's attacks by 30% for 30 seconds. A priest or a shaman can remove it."] = "30초 동안 자신 또는 아군의 공격 속도를 30% 높입니다. 사제나 주술사가 제거할 수 있습니다.",
	["Spiders of the courtyard"] = "안뜰의 거미들",
	["Spirit of Lord Valthalak, inside the dungeon"] = "군주 발타라크의 영혼, 던전 내부",
	["Spirit Totem"] = "정기의 토템",
	["Stage One"] = "1단계",
	["Stage Three: 33% Health"] = "3단계: 생명력 33%",
	["Stage Two: 66% Health"] = "2단계: 생명력 66%",
	["Stalker's Thicket"] = "추적자의 숲",
	["Starts from the Blood-Stained Parchment (or the Last Scrawlings of Edward Heartweaver); the quest then gives you the Blood-Stained Letter to bring to Nightingale."] = "피로 얼룩진 양피지(또는 에드워드 하트위버의 마지막 휘갈김)로 시작합니다. 그러면 퀘스트에서 나이팅게일에게 가져갈 피로 얼룩진 편지를 받습니다.",
	["Starving Arcane"] = "굶주린 비전",
	["Stay in the room"] = "방 안에 머무르십시오",
	["Stay on the platform: small adds wait at the room's edge."] = "단상 위에 머무르십시오. 방 가장자리에 작은 추가 몬스터들이 기다리고 있습니다.",
	["Stay out of her Forked Lightning cone. Frost Nova freezes everyone near her, and she slows a player."] = "갈래 번개의 부채꼴 범위에서 벗어나십시오. 얼음 회오리는 주위의 모두를 얼리며, 플레이어 한 명을 느리게 만들기도 합니다.",
	["Step out of his Flame Spike. A magic dispel removes Flame Shock; interrupt his Shadow Bolt. Fire Nova burns those close to him."] = "불의 쐐기에서 벗어나십시오. 화염 충격은 마법 해제로 제거할 수 있으며, 어둠의 화살은 차단하십시오. 불꽃 회오리는 가까이 있는 대상을 불태웁니다.",
	["Steps out of his shredder once it breaks."] = "벌목기가 부서지면 밖으로 나옵니다.",
	["Stomper Kreeg, inside the dungeon"] = "천둥발 크리그, 던전 내부",
	["Stone Tablet"] = "석판",
	["Stone tablet inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = "왕가의 성물 보관소(드루겐 더지해머의 방) 금고 안의 석판",
	["Stormers and Rumblers"] = "먼지 폭풍과 우레의 모래정령",
	["Stormwind City"] = "스톰윈드",
	["Stormwind Harbor"] = "스톰윈드 항구",
	["Stormwind Rendezvous"] = "스톰윈드 회합",
	["Stormwind's prison beneath the canals has fallen to a riot. Led by Bazil Thredd of the Defias Brotherhood, the inmates have taken the cell blocks, and the Warden wants the ringleaders dealt with."] = "운하 아래에 자리한 스톰윈드의 감옥이 폭동으로 함락되었습니다. 데피아즈단의 바질 스레드가 이끄는 죄수들이 감방 구역을 장악했고, 교도소장은 주동자들을 처리해 주기를 바랍니다.",
	["Strange Water Globe"] = "이상한 물구슬",
	["Strange Water Globe, dropped by Baron Aquanis inside Blackfathom Deeps"] = "이상한 물구슬 (검은심연 나락 안의 군주 아쿠아니스에게서 획득)",
	["Strikes hard at a target down to 20% health or less. Keep the tank above it."] = "생명력이 20% 이하인 대상에게 강력한 일격을 날립니다. 방어 전담의 생명력을 그 이상으로 유지하십시오.",
	["Stuns a player for 4 seconds."] = "플레이어 한 명을 4초 동안 기절시킵니다.",
	["Stuns a player for 5 seconds."] = "플레이어 한 명을 5초 동안 기절시킵니다.",
	["Stuns everyone near him for 4 seconds."] = "주위의 모두를 4초 동안 기절시킵니다.",
	["Stuns, and calls his guards in when his health runs low."] = "기절을 걸며, 생명력이 낮아지면 호위병을 부릅니다.",
	["Swamp of Sorrows"] = "슬픔의 늪",
	["Sweet Serenity"] = "진홍십자군 작업복",
	["Tabetha"] = "타베사",
	["Tabetha's Task"] = "타베사의 임무",
	["Tabetha, Dustwallow Marsh"] = "타베사, 먼지진흙 습지대",
	["Tabitha Heartweaver — The Sepulcher"] = "타비사 하트위버 — 공동묘지",
	["Tabitha Heartweaver, Silverpine Forest / The Sepulcher"] = "타비사 하트위버, 은빛소나무 숲 / 공동묘지",
	["Tabitha Heartweaver, The Sepulcher, Silverpine Forest"] = "타비사 하트위버, 은빛소나무 숲 공동묘지",
	["Take a shard of the Felvine once Alzzin the Wildshaper falls, seal it in the Reliquary of Purity and bring it to Rabine Saturna."] = "칼날바람 알진이 쓰러지면 악령덩굴 조각을 집어 정화의 성물함에 봉인한 후 라빈 사투르나에게 가져가야 합니다.",
	["Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath."] = "카르가스에 있는 렉스로트에게 비쥬의 정찰 보고서를 가져가야 합니다.",
	["Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."] = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다.",
	["Take the Arcane Shard from Morphaz and bring it back to Archmage Xylem."] = "몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다.",
	["Take the Azure Key, which Morphaz carries, to Lord Jorach Ravenholdt."] = "몰파즈가 지니고 있는 하늘색 열쇠를 조라크 라벤홀트 경에게 가져가야 합니다.",
	["Take the bad news back to King Magni Bronzebeard in Ironforge."] = "아이언포지에 있는 국왕 마그니 브론즈비어드에게 돌아가 나쁜 소식을 전해야 합니다.",
	["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = "썬더 블러프에 있는 라하우로에게 그림토템 가방을 가져가야 합니다.",
	["Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."] = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다.",
	["Take the Healthy Dragon Scale to Betina Bigglezink at Light's Hope Chapel."] = "희망의 빛 예배당에 있는 베티나 비글징크에게 생기 있는 용비늘을 가져가야 합니다.",
	["Take the Imp in a Jar to the alchemy lab in Scholomance, then bring the jar back to Gorzeeki Wildeyes."] = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져간 후, 단지를 고르지키 와일드아이즈에게 되돌려 주어야 합니다.",
	["Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul."] = "혈투의 전장 도서관에 있는 팔린 트리셰이퍼에게 미완성된 도전의 깃발을 가져가야 합니다.",
	["Take the letter to the city architect in Stormwind."] = "스톰윈드의 도시 건축가에게 편지를 가져가야 합니다.",
	["Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."] = "노르간논의 원반 축소판을 아이언포지에 있는 탐험가 연맹에 가져가야 합니다.",
	["Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."] = "노르간논의 원반 축소판을 썬더 블러프에 있는 현자 중 한 명에게 가져가야 합니다.",
	["Take the Nightmare Shard to Hamuul Runetotem on the Elder Rise."] = "장로의 봉우리에 있는 하뮬 룬토템에게 악몽의 조각을 가져가야 합니다.",
	["Take the Nightmare Shard to Mathrengyl Bearwalker in Darnassus."] = "다르나서스에 있는 마스렌길 베어워커에게 악몽의 조각을 가져가야 합니다.",
	["Take the Reed-woven Heart back to Caitlin Grassman in Menethil Harbor."] = "갈대로 엮은 심장을 메네실 항구의 케이틀린 그라스만에게 가져가야 합니다.",
	["Take the reward voucher to Bena Winterhoof in Thunder Bluff."] = "사례 보증 서류를 썬더 블러프에 있는 베나 윈터후프에게 가져가야 합니다.",
	["Take the Small Scroll to Varimathras in the Undercity."] = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다.",
	["Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."] = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다.",
	["Take the Titan Relic to the Elder Rise in Thunder Bluff, to someone who can say more about it."] = "티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가 유물에 대해 더 알려 줄 수 있는 사람에게 보여 줘야 합니다.",
	["Take the Unfired Plate Gauntlets lying by the Human Remains to Malyfous Darkhammer in Everlook."] = "인간 해골 옆에 놓인 불타지 않은 판금 건틀릿을 눈망루 마을에 있는 말리퍼스 다크해머에게 가져가야 합니다.",
	["Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge."] = "사례 보증 서류를 아이언포지 사설금고에 있는 디니타 스톤맨틀에게 가져가야 합니다.",
	["Taken with The Prison's Casing; both lead to Suppression."] = "'감옥의 외벽'과 함께 받으며, 두 퀘스트 모두 '감옥에 가두기'로 이어집니다.",
	["Takes control of a player other than his target for 15 seconds (2-second cast). Interrupt it, or dispel it from the player."] = "대상이 아닌 플레이어 하나를 15초 동안 조종합니다(시전 시간 2초). 차단하거나 플레이어에게서 해제하십시오.",
	["Talendria, Desolace"] = "탈렌드리아, 잊혀진 땅",
	["Talk to Blastmaster Emi Shortfuse and protect her while she blows up the two cave mouths. Troggs pour out in waves, then Grubbis comes with Chomper."] = "폭발물전문가 에미 쇼트퓨즈에게 말을 걸고, 그녀가 동굴 입구 두 곳을 폭파하는 동안 보호하십시오. 트로그가 여러 차례 몰려나온 뒤 그루비스가 강철이빨 바실리스크와 함께 나타납니다.",
	["Talk to Franclorn Forgewright about getting a key to the city."] = "프랑클론 포지라이트와 대화하여 도시로 통하는 열쇠를 얻는 방법을 알아봐야 합니다.",
	["Talk to Klockmort Spannerspan in Ironforge."] = "아이언포지에 있는 클락몰트 스패너스판과 대화하십시오.",
	["Talk to Latronicus Moonspear at Feathermoon Stronghold in Feralas."] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화해야 합니다.",
	["Talk to Malyfous Darkhammer in Everlook."] = "눈망루 마을에 있는 말리퍼스 다크해머와 대화해야 합니다.",
	["Talk to Master Mechanic Castpipe in Ironforge."] = "아이언포지에 있는 수석수리공 캐스트파이프와 대화하십시오.",
	["Talk to Mayara Brightwing in the Burning Steppes."] = "불타는 평원에 있는 마야라 브라이트윙과 대화해야 합니다.",
	["Talk to Nara Wildmane nearby in Thunder Bluff."] = "썬더 블러프에서 근처에 있는 나라 와일드메인과 대화해야 합니다.",
	["Talk to Ozzie Togglevolt in Kharanos."] = "카라노스에 있는 오지 토글볼트와 대화하십시오.",
	["Talk to Ragnar Thunderbrew in Kharanos."] = "카라노스에 있는 라그나르 썬더브루와 대화해야 합니다.",
	["Talk to Shadowmage Vivian Lagrave in Kargath."] = "카르가스에 있는 어둠마법사 비비안 라그레이브와 대화해야 합니다.",
	["Talk to Tabetha in Dustwallow Marsh."] = "먼지진흙 습지대에 있는 타베사와 대화해야 합니다.",
	["Talk to Talo Thornhoof at Camp Mojache in Feralas."] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화해야 합니다.",
	["Talk to the stone watcher, then use the Discs of Norgannon."] = "바위감시자와 대화한 후 노르간논의 원반을 사용해야 합니다.",
	["Talk to Thrall to take on his mission."] = "스랄과 대화하여 그가 맡기는 임무를 받아야 합니다.",
	["Talk to Tinkee Steamboil in the Burning Steppes."] = "불타는 평원에 있는 팅키 스팀보일과 대화해야 합니다.",
	["Talk to Tran'rek in Gadgetzan."] = "가젯잔에 있는 트란렉과 대화해야 합니다.",
	["Talk to Yuka Screwspigot in the Burning Steppes."] = "불타는 평원에 있는 유카 스크류스피곳과 대화해야 합니다.",
	["Talo Thornhoof"] = "탈로 쏜후프",
	["Talo Thornhoof, Camp Mojache, Feralas"] = "탈로 쏜후프, 모자케 야영지, 페랄라스",
	["Talo Thornhoof, Feralas"] = "탈로 쏜후프, 페랄라스",
	["Talvash del Kissel"] = "탈바쉬 델 키젤",
	["Talvash del Kissel — Mystic Ward, Ironforge"] = "탈바쉬 델 키젤 — 마법 지구, 아이언포지",
	["Talvash del Kissel, Ironforge"] = "탈바쉬 델 키젤, 아이언포지",
	["Talvash del Kissel, Mystic Ward, Ironforge"] = "탈바쉬 델 키젤, 마법 지구, 아이언포지",
	["Talvash's Scrying Bowl, inside the dungeon"] = "탈바쉬의 수정점 그릇, 던전 내부",
	["Tanaris"] = "타나리스",
	["Tell Thrall in Orgrimmar what you have learned."] = "오그리마에 있는 스랄에게 알아낸 것을 보고해야 합니다.",
	["Test of Endurance"] = "인내의 시험",
	["Test of Faith"] = "믿음의 시험",
	["Test of Lore"] = "지혜의 시험",
	["Test of Strength"] = "용기의 시험",
	["Testing an Enemy's Strength"] = "성난불길 협곡의 트로그",
	["Testing the Wells"] = "우물 조사",
	["Thadius Grimshade"] = "샤디우스 그림섀이드",
	["Thadius Grimshade, Blasted Lands"] = "샤디우스 그림섀이드, 저주받은 땅",
	["The Active Agent"] = "활성 역병 인자",
	["The Altar of Zul"] = "줄의 제단",
	["The Ancient Egg"] = "고대의 알",
	["The Arcanist's Cookbook"] = "신비술사의 요리책",
	["The Archivist"] = "기록관",
	["The Argent Hold"] = "여명회의 궤",
	["The Argent Hold, Eastern Plaguelands"] = "여명회의 궤, 동부 역병지대",
	["The Atal'ai Exile"] = "추방된 아탈라이 트롤",
	["The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an."] = "잠말란을 처치하고 그 증거로 그의 머리카락을 동부 내륙지에 있는 추방된 아탈라이트롤에게 가져가야 합니다.",
	["The Azure Key"] = "하늘색 열쇠",
	["The Barrens"] = "불모의 땅",
	["The Bearer of Bad News"] = "나쁜 소식 전달",
	["The book lies at the north end of the hallway to Arcanist Doan."] = "책은 신비술사 도안에게 이어지는 복도의 북쪽 끝에 있습니다.",
	["The Book of Ur"] = "우르의 책",
	["The braziers of the sanctum open the way to Aku'mai; each one lit calls a wave of enemies, so rest between them."] = "성소의 화로를 밝히면 아쿠마이에게 가는 길이 열립니다. 화로를 하나 밝힐 때마다 적이 몰려오므로 그 사이에 휴식하십시오.",
	["The broodmother of the black dragonflight waits in her lair beneath the Wyrmbog. Forever's version is not known yet."] = "검은용군단의 어미용이 용의 둥지 아래 은신처에서 기다리고 있습니다. 포에버 버전은 아직 알려지지 않았습니다.",
	["The chain starts with the Dark Iron Map, which Dark Iron Spies and Captain Beld in Dun Morogh drop."] = "이 연계 퀘스트는 던 모로의 검은무쇠단 비밀요원과 벨드 대장이 떨어뜨리는 검은무쇠 지도로 시작됩니다.",
	["The Challenge"] = "도전",
	["The Champion of the Horde"] = "호드의 용사",
	["The Charge of the Dragonflights"] = "용군단의 임무",
	["The Color of Blood"] = "피의 색",
	["The Corpulent One"] = "뚱뚱보 괴물",
	["The creatures still alive in his room join the fight when he is pulled. Clear the room first."] = "전투가 시작되면 그의 방에 살아남은 적들이 전투에 합류합니다. 먼저 방을 정리하십시오.",
	["The crest is not always in the same place: on the floor of a tower near Bjork, or on the wall of the small temple at the far end, past him, among other spots."] = "문장의 위치는 항상 같지 않습니다. 비요크 근처 탑의 바닥이나, 그를 지나 맨 끝에 있는 작은 사원의 벽 등 여러 곳에 나타납니다.",
	["The Crone of the Kraul"] = "가시덩굴 우리의 대모",
	["The Cult of the Damned's school of necromancy in the crypts under Caer Darrow, where Darkmaster Gandling trains new servants for the Scourge."] = "카엘 다로우 지하 묘지에 자리한 저주받은 자의 교단의 강령술 학교로, 암흑스승 간들링이 스컬지의 새로운 하수인을 길러 내는 곳입니다.",
	["The Dark Iron dwarves' capital deep in Blackrock Mountain, ruled by Emperor Dagran Thaurissan in the shadow of the Firelord."] = "검은바위 산 깊은 곳에 자리한 검은무쇠 드워프의 수도로, 불의군주의 그늘 아래 제왕 다그란 타우릿산이 다스리고 있습니다.",
	["The Dark Iron War"] = "검은무쇠단과의 전투",
	["The Darkreaver Menace"] = "다크리버의 위협",
	["The Darkstone Tablet"] = "다크스톤 서판",
	["The Day After"] = "그날 이후",
	["The dead side of Stratholme: Baron Rivendare's ziggurats and slaughterhouse, where the Scourge readies its armies."] = "스트라솔름의 죽은 자들의 구역으로, 남작 리븐데어의 지구라트와 도살장이 있는 곳입니다. 스컬지가 이곳에서 군대를 정비하고 있습니다.",
	["The Debt"] = "빚",
	["The Defias Brotherhood"] = "데피아즈단",
	["The Demon Forge"] = "악마의 룬",
	["The Discs of Norgannon, inside Uldaman"] = "노르간논의 원반, 울다만 내부",
	["The Divination Scryer"] = "예언의 탐지기",
	["The Dragon's Eye"] = "용의 눈",
	["The Dragonmaw camp"] = "용아귀일족 야영지",
	["The Dragonmaw Thaumaturgists in his camp put Curse of Weakness on players. Druids (Remove Curse) and mages (Remove Lesser Curse) can take it off."] = "그의 야영지에 있는 용아귀일족 마력술사가 플레이어에게 무력화 저주를 겁니다. 드루이드(저주 해제)와 마법사(하급 저주 해제)가 해제할 수 있습니다.",
	["The Dying, Ras Frostwhisper"] = "망자, 라스 프로스트위스퍼",
	["The Eastern Kingdom"] = "동부 왕국",
	["The eastern wing of Eldre'Thalas, the ruined night elf city, overrun by satyrs and corrupted treants under Alzzin the Wildshaper."] = "폐허가 된 나이트 엘프의 도시 엘드레탈라스의 동쪽 구역으로, 칼날바람 알진이 이끄는 사티로스와 타락한 나무정령이 점령하고 있습니다.",
	["The Ectoplasmic Distiller"] = "심령체 추출기",
	["The Emerald Dream"] = "에메랄드의 꿈",
	["The Emerald Dream..."] = "에메랄드의 꿈...",
	["The Essence of Aku'Mai"] = "아쿠마이의 정수",
	["The Essence of Eranikus"] = "에라니쿠스의 정수",
	["The Exorcism"] = "악마 퇴치",
	["The Fate of the Kingdom"] = "왕국의 운명",
	["The Fel Steed stuns everyone near it for 3 seconds, and they take more Physical damage. The Shadow Charger has no ability."] = "지옥마가 주위의 모두를 3초 동안 기절시키고 받는 물리 피해를 증가시킵니다. 암흑마는 능력이 없습니다.",
	["The Final Tablets"] = "마지막 서판",
	["The Flesh Does Not Lie"] = "거짓말하지 않는 육체",
	["The foreman is in the tunnels before the portal into the dungeon."] = "현장감독은 던전으로 들어가는 차원문 앞 갱도에 있습니다.",
	["The Forging of Quel'Serrar"] = "쿠엘세라 검 만들기",
	["The Forgotten Coast"] = "잊혀진 해안",
	["The Forgotten Pool"] = "잊혀진 웅덩이",
	["The Forgotten Pools"] = "잊혀진 웅덩이",
	["The Founding of Dalaran is on the back wall, past the portal room."] = "달라란 건국기는 차원문 방을 지나 안쪽 벽에 있습니다.",
	["The Fury Runs Deep"] = "격노",
	["The gauntlet is in The Prince's Chest, in Prince Tortheldrin's wing."] = "건틀릿은 왕자 토르텔드린의 구역에 있는 왕자의 궤짝 안에 있습니다.",
	["The Glowing Shard"] = "빛나는 조각",
	["The God Hakkar"] = "학카르의 화신",
	["The Good Stuff"] = "좋은 물건",
	["The Gordok Ogre Suit"] = "고르독 오우거 위장복",
	["The Gordok Taste Test"] = "고르독 술 맛보기",
	["The Grand Betrayal"] = "대배반",
	["The Grave Knight"] = "무덤 기사",
	["The Great Ezra Grimm"] = "위대한 에즈라 그림",
	["The Great Masquerade"] = "대단한 가장무도회",
	["The Greatest Race of Hunters"] = "사냥꾼의 위대한 혈통",
	["The Green Drake"] = "녹색 비룡 몰파즈",
	["The Heart of the Mountain"] = "산의 정수",
	["The Hidden Chamber"] = "비밀 석실",
	["The Highland Lurkers also give players Highland Venom. Despite the name it's a disease: paladins (Purify or Cleanse), priests and shamans (Cure Disease) can take it off."] = "고원 잠복거미는 플레이어에게 고원 독액도 겁니다. 이름과 달리 질병이므로 성기사(순화 또는 정화), 사제와 주술사(질병 치료)가 해제할 수 있습니다.",
	["The Highland Spiders and Highland Lurkers on the trail to him poison players. Druids and shamans (Cure Poison) and paladins (Purify or Cleanse) can take it off."] = "그에게 가는 길의 고원 거미와 고원 잠복거미가 플레이어를 중독시킵니다. 드루이드와 주술사(해독), 성기사(순화 또는 정화)가 해제할 수 있습니다.",
	["The Human, Ras Frostwhisper"] = "라스 프로스트위스퍼",
	["The Hunter's Charm"] = "사냥꾼의 부적",
	["The hydra at the end of the Deeps, and the hardest fight here: keep a steady tank and healer on it."] = "검은심연 나락 가장 깊은 곳에 있는 히드라로, 이곳에서 가장 어려운 전투입니다. 방어 전담과 치유 전담이 안정적으로 버텨야 합니다.",
	["The Ichor of Undeath"] = "불사의 영액",
	["The Infernal Orb"] = "지옥의 보주",
	["The Instigator's Enchantment"] = "주동자의 마법",
	["The Kraul's leader, at the end of the thorn maze."] = "가시덩굴 우리의 지도자로, 가시덩굴 미로의 끝에 있습니다.",
	["The Last Barov"] = "최후의 상속자",
	["The last boss stands still at the end of the spider trail: click the small panel beside him to wake him."] = "마지막 우두머리는 거미 길 끝에 가만히 서 있습니다. 옆에 있는 작은 판을 클릭해 깨우십시오.",
	["The last boss, deep in the Kraul."] = "가시덩굴 우리 깊은 곳에 있는 마지막 우두머리입니다.",
	["The last boss, in Honor's Tomb."] = "명예의 무덤에 있는 마지막 우두머리입니다.",
	["The last boss, in the Athenaeum. The Scarlet Key is in Doan's Strongbox behind him."] = "도서관에 있는 마지막 우두머리입니다. 붉은십자군 열쇠는 그의 뒤에 있는 도안의 금고에 들어 있습니다.",
	["The last boss, in the Purple Parlor of the Violet Citadel."] = "마지막 우두머리로, 보랏빛 성채의 화려한 응접실에 있습니다.",
	["The last boss, in Tinkers' Court. Press the buttons on the bomb faces to stop the walking bombs."] = "땜장이 왕실에 있는 마지막 우두머리입니다. 폭탄 얼굴 장치의 버튼을 눌러 보행 폭탄을 멈추십시오.",
	["The last boss: a stone construct of the Titans."] = "마지막 우두머리로, 티탄이 만든 돌 피조물입니다.",
	["The last boss: Archmage Modera opens the Portal to the Violet Chamber, which leads to him."] = "마지막 우두머리입니다. 대마법사 모데라가 그에게로 이어지는 보랏빛 방 차원문을 열어 줍니다.",
	["The last dungeon step of the Defias Brotherhood chain: do the earlier steps first."] = "데피아즈단 연계 퀘스트의 마지막 던전 단계입니다. 앞 단계를 먼저 완료하십시오.",
	["The Last Element"] = "마지막 원소",
	["The last Fanglord, a plain melee fighter with fewer hit points than Pythas."] = "마지막 송곳니의 드루이드 우두머리로, 피타스보다 생명력이 적은 평범한 근접 전투형입니다.",
	["The last step of the Hidden Enemies chain."] = "'내부의 배신자' 연계 퀘스트의 마지막 단계입니다.",
	["The last step of the paladin's charger quests."] = "성기사 군마 퀘스트의 마지막 단계입니다.",
	["The Left Piece of Lord Valthalak's Amulet"] = "군주 발타라크의 아뮬렛 왼쪽 조각",
	["The Lich, Ras Frostwhisper"] = "리치, 라스 프로스트위스퍼",
	["The Light and How To Swing It"] = "빛과 정의에 관하여",
	["The Light and How to Swing It"] = "빛과 정의에 관하여",
	["The living side of plagued Stratholme, where the Scarlet Crusade holds out against the Scourge under Grand Crusader Dathrohan, the dreadlord Balnazzar in disguise."] = "역병에 물든 스트라솔름의 산 자들의 구역으로, 붉은십자군이 십자군사령관 다스로한의 지휘 아래 스컬지에 맞서 버티고 있습니다. 다스로한의 정체는 변장한 공포의 군주 발나자르입니다.",
	["The locked vaults"] = "잠긴 금고",
	["The longer the fight, the more worgs join him: a Bleak Worg after 30 to 45 seconds, then a Slavering Worg, then a Lupine Horror."] = "전투가 길어질수록 더 많은 검은늑대가 합류합니다. 30~45초 뒤 사나운 검은늑대가, 이어서 굶주린 검은늑대가, 그다음 늑대 망령이 나타납니다.",
	["The longer the fight, the more worgs join him: kill him quickly."] = "전투가 길어질수록 더 많은 검은늑대가 합류합니다. 빠르게 처치하십시오.",
	["The longest fight of the dungeon. Keep the interrupts going and bring him down."] = "던전에서 가장 긴 전투입니다. 쉬지 말고 차단하면서 쓰러뜨리십시오.",
	["The longest fight of the dungeon: a large health pool, so keep the interrupts going."] = "던전에서 가장 긴 전투입니다. 생명력이 많으므로 쉬지 말고 차단하십시오.",
	["The Lost Dwarves"] = "길 잃은 드워프",
	["The Lost Tablets of Mosh'aru"] = "모쉬아루의 잃어버린 서판",
	["The Lost Tablets of Will"] = "잃어버린 결의의 서판",
	["The Love Potion"] = "사랑의 묘약",
	["The lower halls of Blackrock Spire, held by the Blackrock orcs, ogres and trolls that serve Warchief Rend Blackhand."] = "검은바위 첨탑의 하층부로, 대족장 렌드 블랙핸드를 섬기는 검은바위 오크와 오우거, 트롤이 장악하고 있습니다.",
	["The Madness Within"] = "내면의 광기",
	["The manuscript lies in a Pitted Iron Chest under the water of the Pool of Ask'ar, in the north alcove past Ghamoo-ra's room."] = "초본은 가무라의 방을 지나 북쪽 구석, 아스카르 연못 물속에 있는 움푹 파인 철제 궤짝 안에 있습니다.",
	["The Marsh Skulkers on the way to him give players Muculent Rot. A paladin's Purify or Cleanse takes it off. It's either a poison or a disease, so a druid's or shaman's Cure Poison, or a priest's or shaman's Cure Disease, may work too."] = "그에게 가는 길의 늪 잠행자들이 플레이어에게 눅눅한 부패를 겁니다. 성기사의 순화나 정화로 해제할 수 있습니다. 독 또는 질병 중 하나이므로 드루이드나 주술사의 해독, 또는 사제나 주술사의 질병 치료도 통할 수 있습니다.",
	["The Matron Protectorate"] = "대섭정",
	["The Medallion of Faith"] = "신념의 메달",
	["The monastery's cathedral and the heart of the Scarlet Crusade, held by Scarlet Commander Mograine and High Inquisitor Whitemane."] = "수도원의 대성당이자 붉은십자군의 심장부로, 붉은십자군 사령관 모그레인과 종교재판관 화이트메인이 지키고 있습니다.",
	["The monastery's library wing, where the Crusade's huntsmen keep their hounds and Arcanist Doan guards the Athenaeum and the key to the rest of the monastery."] = "수도원의 도서관 구역으로, 붉은십자군의 사냥꾼들이 사냥개를 기르고 있으며 신비술사 도안이 도서관과 수도원의 나머지 구역으로 통하는 열쇠를 지키고 있습니다.",
	["The New Plague"] = "새로운 역병",
	["The northern wing, where the Gordok ogres hold court around King Gordok."] = "고르독 오우거들이 왕 고르독을 받들며 위세를 떨치는 북쪽 구역입니다.",
	["The Only Cure is More Green Glow"] = "유일한 치료법",
	["The Orb of Soran'ruk"] = "소랜루크 수정구",
	["The Pack Mistress"] = "검은늑대 무리의 어미",
	["The Pariah's Instructions"] = "추방자의 지시서",
	["The Path of the Righteous"] = "정의의 길",
	["The Platinum Discs"] = "백금 원반",
	["The Pool of Ask'ar"] = "아스카르 연못",
	["The Power to Destroy..."] = "파괴해야 할 힘",
	["The Princess Saved?"] = "구출된 공주?",
	["The Princess's Surprise"] = "브론즈비어드 공주",
	["The prison is tight: a fleeing player can easily run into another cell block and bring it along."] = "감옥은 비좁습니다. 도망치는 플레이어가 다른 감방 구역으로 뛰어들어 그곳의 적까지 끌고 오기 쉽습니다.",
	["The prison on Alcaz Island still holds Defias Brotherhood inmates, but naga have taken the island and made the prison their own."] = "알카즈 섬의 감옥에는 아직 데피아즈단 죄수들이 갇혀 있지만, 나가가 섬을 점령하고 감옥을 자신들의 소굴로 삼았습니다.",
	["The Prison's Bindings"] = "감옥벽의 재료",
	["The Prophecy of Mosh'aru"] = "모쉬아루의 예언",
	["The Ranger Lord's Behest"] = "순찰대장의 명령",
	["The raptors of Stalker's Thicket, Shadetooth's part of the dig, drop the meat: Thicket Lurkers, Hunters and Stalkers, and Shadetooth himself."] = "고기는 그늘이빨이 있는 발굴지 구역인 추적자의 숲의 랩터들, 즉 덤불 잠복꾼, 덤불 사냥꾼, 덤불 추적자와 그늘이빨 자신에게서 획득합니다.",
	["The Restless Dead"] = "잠 못 드는 망자",
	["The Restless Souls"] = "잠 못드는 영혼",
	["The Rethban Gauntlet"] = "레스밴 도전",
	["The Right Piece of Lord Valthalak's Amulet"] = "군주 발타라크의 아뮬렛 오른쪽 조각",
	["The ringleader of the uprising, found in one of three places."] = "폭동의 주동자로, 세 곳 중 한 곳에서 찾을 수 있습니다.",
	["The Rise of the Machines"] = "기계들의 봉기",
	["The Royal Rescue"] = "공주 구출",
	["The ruined city of Lordaeron"] = "폐허가 된 로데론 도시",
	["The Scarlet Crusade's armory and training halls, where Herod, the Scarlet Champion, drills the Crusade's soldiers."] = "붉은십자군의 무기고이자 훈련장으로, 붉은십자군 용사 헤로드가 십자군 병사들을 단련시키는 곳입니다.",
	["The Scarlet Crusaders of every wing carry the hearts, and so do their leaders."] = "모든 구역의 붉은십자군 병사와 그 우두머리들이 열정의 증거를 지니고 있습니다.",
	["The Scarlet Monastery was a seat of Lordaeron's priesthood until the Scarlet Crusade made it their stronghold after the Third War. In its graveyard wing the Crusade's interrogators work, and the dead buried there no longer rest."] = "붉은십자군 수도원은 로데론 성직자들의 본산이었으나, 3차 대전쟁 이후 붉은십자군이 이곳을 근거지로 삼았습니다. 묘지 구역에서는 붉은십자군의 심문관들이 일하고 있으며, 그곳에 묻힌 망자들은 더 이상 편히 잠들지 못합니다.",
	["The Scepter of Celebras"] = "셀레브라스의 홀",
	["The Scourge still holds the ruins of the old capital, where a necromancer is building his strength."] = "스컬지가 여전히 옛 수도의 폐허를 장악하고 있으며, 그곳에서 한 강령술사가 힘을 키우고 있습니다.",
	["The Shattered Necklace"] = "부서진 목걸이",
	["The Shieldsmith"] = "방패 상인",
	["The ship's cook, found aboard the juggernaut."] = "배의 요리사로, 전함 위에서 만날 수 있습니다.",
	["The shredder ignores burning, bleeding and stun-style concussion effects."] = "벌목기는 화상, 출혈 및 기절 계열의 충격 효과에 걸리지 않습니다.",
	["The Siren's Coral"] = "세이렌의 산호",
	["The Smoldering Ruins of Thaurissan"] = "불타는 타우릿산의 폐허",
	["The Sparklematic 5200"] = "삐까뻔쩍세척기 5200",
	["The Sparklematic 5200!"] = "삐까뻔쩍세척기 5200!",
	["The Sparklematic 5200, inside Gnomeregan"] = "삐까뻔쩍세척기 5200, 놈리건 내부",
	["The Spectral Chalice"] = "유령의 성배",
	["The Spider God"] = "거미 신",
	["The Stagnant Oasis"] = "죽은 오아시스",
	["The State of the Mines"] = "광산의 상황",
	["The Stockade Riots"] = "감옥 폭동",
	["The Stone Circle"] = "돌무리",
	["The stone tablet is behind the vault door in Durgen Dirgehammer's room, easy to walk past on the way to the lever that leads out."] = "석판은 드루겐 더지해머의 방 금고 문 뒤에 있어, 밖으로 나가는 레버로 향하다 보면 지나치기 쉽습니다.",
	["The summoner"] = "소환사",
	["The sun-baked city of the Sandfury trolls in northern Tanaris, ruled by Chief Ukorz Sandscalp, with the hydra Gahz'rilla in its sacred pool."] = "타나리스 북부에 자리한 성난모래부족 트롤의 햇볕에 달궈진 도시로, 족장 우코르즈 샌드스칼프가 다스리며 신성한 연못에는 히드라 가즈릴라가 살고 있습니다.",
	["The Sunken Temple"] = "가라앉은 사원",
	["The Temple of Atal'Hakkar"] = "아탈학카르 신전",
	["The temple the Atal'ai built to call their blood god Hakkar sank into the Swamp of Sorrows; his priests still try to bring him back, watched by the green dragons of Eranikus."] = "아탈라이 트롤이 혈신 학카르를 불러내려고 세운 신전은 슬픔의 늪 아래로 가라앉았습니다. 학카르의 사제들은 지금도 그를 되살리려 하고, 에라니쿠스의 녹색용들이 이들을 감시하고 있습니다.",
	["The Test of Righteousness"] = "정의의 시험",
	["The Test of Skulls, Axtroz"] = "해골 시험 - 악트로즈",
	["The Test of Skulls, Chronalis"] = "해골 시험 - 크로날리스",
	["The Test of Skulls, Scryer"] = "해골 시험 - 스크라이어",
	["The Test of Skulls, Somnus"] = "해골 시험 - 솜누스",
	["The Testament of Rexxar"] = "렉사르의 유언",
	["The Thicket Hunters, raptors on the way to him and in his fight, give players Infected Wound, a disease. Paladins (Purify or Cleanse), priests and shamans (Cure Disease) can take it off."] = "그에게 가는 길과 전투 중에 나타나는 랩터인 덤불 사냥꾼이 플레이어에게 질병인 상처 감염을 겁니다. 성기사(순화 또는 정화), 사제와 주술사(질병 치료)가 해제할 수 있습니다.",
	["The Tome of Valor"] = "용맹의 고서",
	["The top of the spire, where Warchief Rend Blackhand and General Drakkisath command the black dragonflight's armies."] = "첨탑의 꼭대기로, 대족장 렌드 블랙핸드와 사령관 드라키사스가 검은용군단의 군대를 지휘하는 곳입니다.",
	["The toughest Fanglord, with heavy melee and a large health pool."] = "가장 강한 송곳니의 드루이드 우두머리로, 근접 공격이 강력하고 생명력이 많습니다.",
	["The Treasure of the Shen'dralar"] = "셴드랄라의 보물",
	["The Treasure of the Shen'dralar, in the Athenaeum, Dire Maul"] = "셴드랄라의 보물, 혈투의 전장 도서관",
	["The Treaty of Understanding"] = "상호 이해 조약",
	["The True Masters"] = "진정한 지도자",
	["The Truth Comes Crashing Down"] = "밝혀지는 진실",
	["The undead tunnel branches off before the portal."] = "언데드가 있는 갱도는 차원문 앞에서 갈라집니다.",
	["The Unsent Letter"] = "부치지 않은 편지",
	["The vaults in Durgen Dirgehammer's room hold about 24 Dwarven Heirlooms: open them after the fight."] = "드루겐 더지해머의 방에 있는 금고에 드워프 가보가 약 24개 들어 있습니다. 전투가 끝나면 금고를 여십시오.",
	["The western wing, where the last Highborne of Eldre'Thalas keep the demon Immol'thar imprisoned to feed their magic."] = "엘드레탈라스에 마지막으로 남은 명가 일원들이 자신들의 마법에 힘을 공급하려고 악마 이몰타르를 가둬 둔 서쪽 구역입니다.",
	["The Windshaper's Wrath"] = "바람구체자의 분노",
	["The Work of Grimand Elmore"] = "그리만트 엘모어의 마갑",
	["The Wrath of Rath'mael"] = "라스마엘의 분노",
	["The Wrong Stuff"] = "인형 재료",
	["Theldurin the Lost, Badlands"] = "실성한 텔두린, 황야의 땅",
	["Theodore Griffs — Apothecarium"] = "시어도어 그리프스 — 연금술 실험실",
	["Theodore Griffs, Undercity"] = "시어도어 그리프스, 언더시티",
	["Theramore Isle"] = "테라모어 섬",
	["Thom Filch, by the bridge / vault entrance in Ironforge"] = "톰 필치, 아이언포지 다리 / 금고 입구 옆",
	["Thom Filch, near the dungeon entrance"] = "톰 필치, 던전 입구 근처",
	["Thorium Brotherhood Contract"] = "토륨 대장조합 계약서",
	["Thorium Brotherhood Contract, from Lokhtos Darkbargainer inside the dungeon"] = "토륨 대장조합 계약서, 던전 내부의 로크토스 다크바게이너에게서 받음",
	["Thrall"] = "스랄",
	["Thrall, Grommash Hold, Orgrimmar"] = "스랄, 오그리마 그롬마쉬 요새",
	["Thrall, Orgrimmar"] = "스랄, 오그리마",
	["Thrall, Valley of Wisdom, Orgrimmar"] = "스랄, 오그리마 지혜의 골짜기",
	["Three hounds stand at his side and attack with him, and he gives them Bloodlust too. Kill them first."] = "하이에나 세 마리가 곁에 서서 함께 공격하며, 하이에나에게도 피의 욕망을 걸어 줍니다. 먼저 처치하십시오.",
	["Three Kings of Flame"] = "세 고위 정령의 불꽃",
	["Throws the tank into the air and stuns him for 5 seconds. Damage dealers, watch your threat: the tank is on him only about half the fight."] = "방어 전담을 공중으로 던져 5초 동안 기절시킵니다. 공격 전담은 위협 수준에 주의하십시오. 방어 전담이 그를 상대하는 시간은 전투의 절반 정도뿐입니다.",
	["Thun'grim Firegaze"] = "툰그림 파이어게이즈",
	["Thun'grim Firegaze, The Barrens"] = "툰그림 파이어게이즈, 불모의 땅",
	["Thundercrack stuns everyone near him; he also puts players to sleep and fears them."] = "천둥균열로 주위의 모두를 기절시키며, 플레이어를 잠재우거나 공포에 빠뜨리기도 합니다.",
	["Thunderheart, Badlands"] = "썬더하트, 황야의 땅",
	["Tiara of the Deep"] = "심연의 티아라",
	["Tinkee Steamboil"] = "팅키 스팀보일",
	["Tinkee Steamboil, Burning Steppes"] = "팅키 스팀보일, 불타는 평원",
	["Tinker Town"] = "땜장이 마을",
	["Tinkmaster Overspark"] = "수석땜장이 오버스파크",
	["Tinkmaster Overspark — Tinker Town, Ironforge"] = "수석땜장이 오버스파크 — 땜장이 마을, 아이언포지",
	["Tinkmaster Overspark, Ironforge"] = "수석땜장이 오버스파크, 아이언포지",
	["Tirion Fordring, Eastern Plaguelands"] = "티리온 폴드링, 동부 역병지대",
	["Tirisfal Glades"] = "티리스팔 숲",
	["Titan Relic"] = "티탄의 유물",
	["To Kill With Purpose"] = "이유 있는 살육",
	["To Show Due Judgment"] = "희생과 심판",
	["To The Hinterlands"] = "동부 내륙지로",
	["Tonga Runetotem, The Barrens"] = "통가 룬토템, 불모의 땅",
	["Torwa Pathfinder"] = "토르와 패스파인더",
	["Torwa Pathfinder, Un'Goro Crater"] = "토르와 패스파인더, 운고로 분화구",
	["Toxic Test"] = "독성 테스트",
	["Tramping Paws"] = "파괴의 손길",
	["Tran'rek"] = "트란렉",
	["Tran'rek, Tanaris"] = "트란렉, 타나리스",
	["Translating the Journal"] = "일지 번역",
	["Travel into the Sunken Temple and discover the secret hidden in the circle of statues."] = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다.",
	["Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."] = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다.",
	["Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions."] = "검은바위 나락으로 가서 검은무쇠단 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠단 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다.",
	["Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."] = "검은바위 나락으로 가서 사령관 앵거포지를 처치하십시오! 임무를 완수하면 장군 고어투스에게 돌아가야 합니다.",
	["Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler."] = "검은바위 첨탑으로 가서 키블러에게 줄 첨탑 거미알 15개를 모아야 합니다.",
	["Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."] = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아야 합니다. 임무를 마치면 노파 미란다에게 돌아가십시오.",
	["Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done."] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다.",
	["Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."] = "검은바위 첨탑으로 가서 검은늑대 위협의 근원을 제거해야 합니다. 헬렌디스와 헤어질 때 그는 할리콘이라는 이름을 외쳤습니다. 오크들이 검은늑대를 가리킬 때 쓰는 이름입니다.",
	["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."] = "검은바위 첨탑으로 가서 대장군 부네, 대군주 오모크, 대군주 웜타라크를 처치해야 합니다. 임무를 마치면 치안대장 맥스웰에게 돌아가십시오.",
	["Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."] = "검은바위 첨탑으로 가서 도끼부대 새끼 검은늑대를 찾아야 합니다. 이 사나운 녀석들은 우리에 넣어 옮기십시오. 사로잡은 새끼 검은늑대를 키블러에게 가져가야 합니다.",
	["Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained."] = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 그의 시체에 핏물이 깃든 창을 사용하십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다.",
	["Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다.",
	["Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."] = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.",
	["Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov."] = "얼라이언스 영토인 서리바람 야영지로 가서 웰던 바로브를 암살해야 합니다. 그 증거로 그의 머리카락을 가지고 알렉시 바로브에게 돌아가십시오.",
	["Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary."] = "혈투의 전장으로 가서 임프 푸실린을 찾아야 합니다. 어떤 수단을 쓰든 푸실린이 아즈토르딘의 마법서를 내놓게 하십시오.",
	["Travel to Ratchet to find someone who can identify the Glowing Shard, then deliver it as directed."] = "톱니항으로 가서 빛나는 조각을 감정해 줄 사람을 찾은 뒤, 안내에 따라 전달해야 합니다.",
	["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."] = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다.",
	["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."] = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다.",
	["Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith."] = "스트라솔름으로 가서 진홍십자군 대장장이를 처치하고 진홍십자군 대장장이의 작업복을 가지고 릴리스에게 돌아가야 합니다.",
	["Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink."] = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 새로운 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다.",
	["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."] = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다.",
	["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."] = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다.",
	["Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world."] = "역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오. 그 뒤에 '가족과 사랑'이라는 그림이 숨겨져 있습니다.",
	["Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov."] = "호드의 영토인 보루로 가서 알렉시 바로브를 암살하십시오. 그 증거로 그의 머리카락을 가지고 웰던 바로브에게 돌아가십시오.",
	["Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."] = "불타는 평원으로 가서 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다.",
	["Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone. Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet."] = "검은바위 나락의 법의 심판장으로 가서 대법관 그림스톤에게 선고를 받는 동안 한가운데에 도전의 깃발을 설치해야 합니다. 텔드렌과 그의 검투사들을 해치운 후 군주 발타라크의 첫 번째 아뮬렛 조각을 가지고 동부 역병지대에 있는 안시온 하몬에게 돌아가야 합니다.",
	["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."] = "혈투의 전장의 굽이나무 지구로 가서 물의 정령 히드로스폰을 처치해야 합니다. 그런 다음 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가십시오.",
	["Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken."] = "먼지진흙 습지대의 용의 둥지로 가서 고대 비룡 엠버스트라이프를 찾아야 합니다. 그의 의지가 꺾일 때까지 사정없이 공격하십시오.",
	["Travel to Winterspring and find Haleh. Give her Awbee's scale."] = "여명의 설원으로 가서 헬레를 찾아 아우비의 비늘을 건네야 합니다.",
	["Trenton Lighthammer, Tanaris"] = "트렌튼 라이트해머, 타나리스",
	["Treshala Fallowbrook, Darnassus"] = "트레샬라 팰로우브룩, 다르나서스",
	["Trevan Rol, the Sepulcher, Silverpine Forest"] = "트레반 롤, 은빛소나무 숲 공동묘지",
	["Trial at the Field of Giants"] = "거인의 들판에서의 시험",
	["Troll Temper"] = "트롤 경화제",
	["Trolls of a Feather"] = "트롤의 깃털",
	["Trouble at the Docks"] = "99년 묵은 와인",
	["Trouble in the Deeps"] = "검은심연의 나락으로...",
	["Tsunaman — Sun Rock Retreat"] = "츄나만 — 해바위 야영지",
	["Tsunaman, Stonetalon Mountains"] = "츄나만, 돌발톱 산맥",
	["Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron."] = "설퍼론 도면을 받으려면 토륨 대장조합 계약서를 로크토스 다크바게이너에게 가져가야 합니다.",
	["Turns a player into an animal for 8 seconds. It is magic: dispel it."] = "플레이어 한 명을 8초 동안 동물로 변이시킵니다. 마법 효과이므로 해제하십시오.",
	["Turns a player other than his target into a sheep for up to 20 seconds (1.5-second cast). Interrupt it, or dispel it from the player."] = "현재 대상이 아닌 플레이어 한 명을 최대 20초 동안 양으로 변이시킵니다(시전 시간 1.5초). 차단하거나 해당 플레이어에게서 해제하십시오.",
	["Turns a player other than the tank into a Shadowfang Glutton that fights for him for 10 seconds. Remove the curse."] = "방어 전담이 아닌 플레이어 한 명을 그림자송곳니일족 광신도로 바꿔 10초 동안 자신을 위해 싸우게 합니다. 저주를 해제하십시오.",
	["Twilight Falls"] = "황혼의망치단의 몰락",
	["Twisted Evils"] = "뒤틀린 악마",
	["Two Mana Phantoms fight beside him: kill them first, their Mana Burn drains whoever they target."] = "마나 환영 둘이 그의 곁에서 싸웁니다. 대상의 마나를 태우는 마나 연소를 쓰므로 먼저 처치하십시오.",
	["Ulathek the Traitor"] = "배신자 울라텍",
	["Uldaman Reagent Run"] = "울다만에서 재료 찾기",
	["Un'Goro Crater"] = "운고로 분화구",
	["Un-Life's Little Annoyances"] = "성가신 녀석들",
	["Undamaged Venom Sac"] = "온전한 독주머니",
	["Undead characters cannot take this quest."] = "언데드 캐릭터는 이 퀘스트를 받을 수 없습니다.",
	["Undercity"] = "언더시티",
	["Underground Assault"] = "지하 공격",
	["Underground Map"] = "지하 지도",
	["Unending Torment"] = "끝없는 고통",
	["Unfinished Abomination, Undercity"] = "미완성 누더기골렘, 언더시티",
	["Unfinished Gordok Business"] = "고르독 일 마무리",
	["Urok Doomhowl"] = "우로크 둠하울",
	["Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로를 사용하여 자리엔과 소도스의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.",
	["Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로를 사용하여 자리엔과 소도스의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.",
	["Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로로 이살리엔의 영혼을 불러내 처치해야 합니다. 그런 다음 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
	["Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로로 이살리엔의 영혼을 불러내 처치해야 합니다. 그런 다음 다시 맞춘 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
	["Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로를 사용하여 코르모크의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.",
	["Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로를 사용하여 코르모크의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.",
	["Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로로 모르 그레이후프의 영혼을 불러내 처치해야 합니다. 그런 다음 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
	["Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning."] = "부름의 화로로 모르 그레이후프의 영혼을 불러내 처치해야 합니다. 그런 다음 다시 맞춘 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
	["Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak."] = "부름의 화로로 군주 발타라크를 소환해야 합니다. 군주 발타라크를 처치한 후 시체에 군주 발타라크의 아뮬렛을 사용하십시오. 그런 다음 군주 발타라크의 아뮬렛을 군주 발타라크의 영혼에게 돌려주어야 합니다.",
	["Use the Crate with Holes to summon a Snufflenose Gopher and the Command Stick to make it find 6 Blueleaf Tubers. Bring them, the Command Stick and the Crate back to Mebok Mizzyrix."] = "구멍 난 상자를 사용해 땅다람쥐를 소환하고, 땅다람쥐 지휘봉을 사용해 청엽수 줄기 6개를 찾게 해야 합니다. 청엽수 줄기와 땅다람쥐 지휘봉, 구멍 난 상자를 메보크 미지릭스에게 가져가야 합니다.",
	["Use the detonator."] = "기폭장치를 사용해야 합니다.",
	["Use the Divination Scryer in the Great Ossuary's basement, defeat the spirits it calls and Death Knight Darkreaver, and bring Darkreaver's Head to Sagorne Creststrider."] = "대형 납골당 지하에서 예언의 탐지기를 사용하여 나타나는 영혼들과 죽음의 기사 다크리버를 물리친 후, 다크리버의 머리카락을 사고른 크레스트스트라이더에게 가져가야 합니다.",
	["Use the Divination Scryer in the Great Ossuary's basement, defeat the spirits it calls and Death Knight Darkreaver, then give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."] = "대형 납골당 지하에서 예언의 탐지기를 사용하여 나타나는 영혼들과 죽음의 기사 다크리버를 물리친 후, 구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 건네야 합니다.",
	["Use the Eggscilloscope Prototype on an egg in the Rookery."] = "알껍질급속냉각기 견본을 부화장에 있는 알에 사용해야 합니다.",
	["Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers, then take the full phial back to Ozzie Togglevolt."] = "오염된 침략꾼이나 오염된 약탈자에게 빈 가연채집병을 사용한 다음, 가득 찬 채집병을 오지 토글볼트에게 가져가야 합니다.",
	["Uthel'nay"] = "우텔나이",
	["Uthel'nay, the Cleft of Shadow, Orgrimmar"] = "우텔나이, 어둠의 틈, 오그리마",
	["Valanaar"] = "발라나르",
	["Varimathras"] = "바리마트라스",
	["Varimathras — Royal Quarter, Undercity"] = "바리마트라스 — 왕실, 언더시티",
	["Varimathras, Royal Quarter, Undercity"] = "바리마트라스, 언더시티 왕실",
	["Varimathras, Undercity"] = "바리마트라스, 언더시티",
	["Vark Battlescar"] = "바르크 배틀스카",
	["Vark Battlescar, Shadowprey Village, Desolace"] = "바르크 배틀스카, 그늘수렵 마을, 잊혀진 땅",
	["Venom Bottles"] = "독병",
	["Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff."] = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다.",
	["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.",
	["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다.",
	["Veyric Thunderhame"] = "베이릭 썬더헤임",
	["Veyric Thunderhame, Arathi Highlands"] = "베이릭 썬더헤임, 아라시 고원",
	["Vines run to a player and hit everyone within 5 yards of them, then leave poisonous fumes on the ground. Move out of the fumes."] = "덩굴이 플레이어에게 뻗어 가 그 주위 5미터 내의 모두에게 피해를 주고, 바닥에 독성 연기를 남깁니다. 연기에서 벗어나십시오.",
	["Visit Jarkal Mossmeld in Kargath to see if he was successful."] = "카르가스에 있는 자칼 모스멜드를 찾아가 일이 잘 되었는지 확인해야 합니다.",
	["Vivian Lagrave"] = "비비안 라그레이브",
	["Vivian Lagrave and the Darkstone Tablet"] = "비비안 라그레이브와 다크스톤 서판",
	["Voodoo Feathers"] = "부두 깃털",
	["Vorrel Sengutz, inside the Graveyard"] = "보렐 센구츠, 묘지 내부",
	["Vorrel's Revenge"] = "보렐의 복수",
	["Vyletongue Corruption"] = "바일텅의 타락",
	["Wait for Jordan Stilwell to finish forging a weapon for you."] = "조던 스틸웰이 무기를 다 벼려 줄 때까지 기다려야 합니다.",
	["Wait for Scooty to calibrate the Goblin Transponder."] = "스쿠티가 고블린 응답장치를 조절하는 동안 기다려야 합니다.",
	-- Shadowfang Keep: Arugal's note (2026-11-06; drafted, to be checked)
	["Waits at the top of the keep. When Fenrus the Devourer dies, he appears for a moment to call four Voidwalkers."] = "성채 꼭대기에서 기다립니다. 파멸의 펜루스가 죽으면 잠시 모습을 드러내 보이드워커 넷을 불러냅니다.",
	["Waits in the captain's cabin at the top of the ship."] = "배 꼭대기의 선장실에서 기다리고 있습니다.",
	["Walking Bombs"] = "보행 폭탄",
	["WANTED, Badlands"] = "현상수배!, 황야의 땅",
	["War on the Shadowsworn"] = "어둠의혈맹과의 전쟁",
	["Warcaller Gorlach"] = "징집관 고를라취",
	["Warcaller Gorlach, Orgrimmar"] = "징집관 고를라취, 오그리마",
	["Warden Thelwater — The Stockade"] = "교도소장 델워터 — 스톰윈드 지하감옥",
	["Warden Thelwater, outside The Stockade, Stormwind"] = "교도소장 델워터, 스톰윈드 지하감옥 입구 밖",
	["Warlord Goretooth"] = "장군 고어투스",
	["Warlord Goretooth, Badlands"] = "장군 고어투스, 황야의 땅",
	["Warlord's Command"] = "장군의 명령",
	["Warosh, inside the dungeon"] = "와로쉬, 던전 내부",
	["Warrior Kinship"] = "전사의 일족",
	["Wavethrashing"] = "폭풍히드라 사냥",
	["Weldon Barov, Western Plaguelands"] = "웰던 바로브, 서부 역병지대",
	["Western Plaguelands"] = "서부 역병지대",
	["Wetlands"] = "저습지",
	["What Comes Around..."] = "사필귀정",
	["What Is Going On?"] = "사태 파악",
	["What the Wind Carries"] = "바람이 전해 온 소식",
	["What Tomorrow Brings"] = "미래의 운명",
	["Wheel of the Black March"] = "어둠의 물레",
	["When he dies, 20 Scarlet Trainees run in through the hall's door and attack. Stay together and use area damage."] = "헤로드가 죽으면 붉은십자군 신병 20명이 전당 문으로 달려 들어와 공격합니다. 한데 모여 광역 공격으로 처치하십시오.",
	["When he dies, twenty Scarlet Trainees rush in through the hall's door: stay together and use area damage."] = "헤로드가 죽으면 붉은십자군 신병 20명이 전당 문으로 몰려옵니다. 한데 모여 광역 공격으로 처치하십시오.",
	["When his health gets low he fears the whole group. Bring a way to break it, or clear the room first so nobody runs into more enemies."] = "생명력이 낮아지면 파티 전체에 공포를 겁니다. 공포를 풀 수단을 챙기거나, 아무도 다른 적에게 달려가지 않도록 먼저 방을 정리하십시오.",
	["When his mana runs dry he turns the whole group into animals for 8 seconds, then channels Evocation to refill it. Casters can hide behind the wall from the polymorph, but if anyone leaves the room he resets to full health."] = "마나가 바닥나면 파티 전체를 8초 동안 동물로 변이시킨 뒤, 환기를 정신 집중하여 마나를 채웁니다. 주문시전자는 벽 뒤에 숨어 변이를 피할 수 있지만, 누구든 방을 벗어나면 그의 생명력이 최대로 초기화됩니다.",
	["When his mana runs out, he turns the whole group into animals for 8 seconds, then channels Evocation for 6 seconds to refill it."] = "마나가 떨어지면 파티 전체를 8초 동안 동물로 변이시킨 뒤, 6초 동안 환기를 정신 집중하여 마나를 채웁니다.",
	["When his target is close he knocks down and roots everyone near him: ranged players, keep your distance."] = "대상이 가까이 있으면 주위의 모두를 넘어뜨리고 묶어 둡니다. 원거리 공격수는 거리를 유지하십시오.",
	["When his target is close, he knocks down and roots everyone near him for 10 seconds. Ranged players, keep your distance."] = "대상이 가까이 있으면 주위의 모두를 넘어뜨리고 10초 동안 묶어 둡니다. 원거리 공격수는 거리를 유지하십시오.",
	["When Mograine falls he is only playing dead: she runs out of the room behind the altar and attacks."] = "모그레인은 쓰러져도 죽은 척할 뿐입니다. 화이트메인이 제단 뒤의 방에서 달려 나와 공격합니다.",
	["When Mograine falls he is only playing dead: she runs out of the room behind the altar."] = "모그레인은 쓰러져도 죽은 척할 뿐입니다. 화이트메인이 제단 뒤의 방에서 달려 나옵니다.",
	["When pulled he calls every Scarlet defender within 80 yards: clear the cathedral first."] = "전투가 시작되면 80미터 내의 모든 붉은십자군 병력을 불러들입니다. 먼저 대성당을 정리하십시오.",
	["When pulled he calls everything within 30 yards: clear around him first. He hits harder at 60%, 40% and 20% health."] = "전투가 시작되면 30미터 안의 모든 적을 불러들입니다. 주변을 먼저 정리하십시오. 생명력이 60%, 40%, 20%가 될 때마다 더 강하게 공격합니다.",
	["When pulled, he calls every Scarlet defender within 80 yards to join him. Clear the cathedral before you pull him."] = "전투가 시작되면 80미터 내의 모든 붉은십자군 병력을 불러 합류시킵니다. 전투를 시작하기 전에 대성당을 정리하십시오.",
	["When pulled, he calls the creatures within 15 yards to join him, the two Razorfen Spearhides at his side among them. Crowd-control one of them."] = "전투가 시작되면 15미터 내의 몬스터를 불러들이며, 곁에 있는 가시덩굴일족 가시근위병 둘도 함께 합류합니다. 그중 하나는 군중 제어하십시오.",
	["When pulled, he calls the creatures within 30 yards to join him. Clear around him first."] = "전투가 시작되면 30미터 안의 몬스터를 불러 합류시킵니다. 주변을 먼저 정리하십시오.",
	["When the tank reaches him: Nature damage and a 5-second stun around him."] = "방어 전담이 다가오면 주위에 자연 피해를 입히고 5초 동안 기절시킵니다.",
	["Where the demigod Agamaggan fell, his blood grew into a sprawl of giant thorns, and the quilboar made it their sacred home. Undead envoys have lately been seen among them, and Charlga Razorflank rules the Kraul from its heart."] = "반신 아감마간이 쓰러진 자리에서 그의 피가 거대한 가시덩굴로 자라났고, 멧돼지인간은 이곳을 성스러운 보금자리로 삼았습니다. 최근에는 그들 사이에서 언데드 사절들이 목격되고 있으며, 서슬깃 차를가가 가시덩굴 우리의 심장부에서 이곳을 다스리고 있습니다.",
	["Whoever strikes him or an ally near him, Overlord Ramtusk included, takes Nature damage."] = "그나 근처의 아군(대군주 램터스크 포함)을 공격하는 대상은 자연 피해를 입습니다.",
	["Wilder Thistlenettle"] = "빌더 시슬네틀",
	["Wilder Thistlenettle, Stormwind"] = "빌더 시슬네틀, 스톰윈드",
	["Wilder Thistlenettle, the Dwarven District, Stormwind"] = "빌더 시슬네틀, 스톰윈드 드워프 지구",
	["Wildeyes"] = "와일드아이즈",
	["Willix the Importer"] = "수입업자 윌릭스",
	["Willix the Importer, inside Razorfen Kraul"] = "수입업자 윌릭스, 가시덩굴 우리 내부",
	["Willow, Desolace"] = "윌로우, 잊혀진 땅",
	["Witch Doctor Uzer'i, Feralas"] = "의술사 우제리, 페랄라스",
	["With all four Fanglords dead, speak to the Disciple of Naralex at the entrance and escort him to Naralex."] = "송곳니의 드루이드 우두머리 넷이 모두 죽으면 입구에 있는 나랄렉스의 신도와 대화하고 나랄렉스에게까지 호위하십시오.",
	["With his hammer, below 33% health: a heavy blow that stuns the tank for 3 seconds."] = "생명력 33% 미만에서 망치를 들고, 방어 전담을 3초 동안 기절시키는 강력한 일격을 가합니다.",
	["With his two axes, from 66% health: extra attacks on the tank."] = "생명력 66%부터 도끼 두 자루를 들고 방어 전담을 추가로 공격합니다.",
	["With two axes he strikes the tank extra times; with the hammer, below 33%, he stuns the tank."] = "도끼 두 자루를 들면 방어 전담을 추가로 공격하고, 생명력 33% 미만에서 망치를 들면 방어 전담을 기절시킵니다.",
	["Witherbark Cages"] = "마른나무껍질부족 우리",
	["Wizzle Brassbolts, Thousand Needles"] = "위즐 브라스볼츠, 버섯구름 봉우리",
	["Xorothian Stardust"] = "소로시안 별가루",
	["Yeh'kinya, Tanaris"] = "예킨야, 타나리스",
	["Yorba Screwspigot, Tanaris"] = "요르바 스크류스피곳, 타나리스",
	["You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."] = "방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을지도 모릅니다.",
	["You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire."] = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다. 드라키사스는 검은바위 첨탑의 승천의 전당 뒤에 있는 알현실에 있습니다.",
	["Young Crocolisk Skins"] = "새끼 악어 가죽",
	["Ysida Harmon, inside the dungeon"] = "이시다 하몬, 던전 내부",
	["Yuka Screwspigot"] = "유카 스크류스피곳",
	["Yuka Screwspigot, Burning Steppes"] = "유카 스크류스피곳, 불타는 평원",
	["Zaetar's Spirit, inside the dungeon"] = "재타르의 영혼, 던전 내부",
	["Zapper Fuel"] = "구제장치 연료",
	["Zaruk"] = "자루크",
	["Zaruk in the Arathi Highlands sends you to her with Dragonmaw Rumors. The Dragonmaw Dispatch comes from the Dragonmaw forces inside the dungeon."] = "아라시 고원의 자루크가 '용아귀일족에 대한 소문' 퀘스트를 통해 그녀에게 보냅니다. 용아귀일족 지령서는 던전 안의 용아귀일족 병력에게서 획득합니다.",
	["Zaruk, Hammerfall, Arathi Highlands"] = "자루크, 아라시 고원 해머폴",
	["Zephras Isle"] = "제프라스 섬",
	["Zoram Strand, Ashenvale"] = "잿빛 골짜기 조람 해안",
	-- Scholomance: the Skeleton Key's quests and Before you go's notes (2026-10-30; drafted, to be checked)
	["Clear the Way"] = "길을 열어라",
	["Scarlet Diversions"] = "붉은십자군 교란 작전",
	["All Along the Watchtowers"] = "감시탑을 따라서",
	["Scholomance"] = "스칼로맨스",
	["Skeletal Fragments"] = "해골 파편",
	["Mold Rhymes With..."] = "주형과 운이 맞는 말은...",
	["Fire Plume Forged"] = "불기둥 마루에서 벼려 낸 열쇠",
	["Araj's Scarab"] = "아라즈의 풍뎅이",
	["The Key to Scholomance"] = "스칼로맨스의 열쇠",
	["Commander Ashlam Valorfist, Western Plaguelands"] = "사령관 아쉬람 발러피스트, 서부 역병지대",
	["Alchemist Arbington, Western Plaguelands"] = "연금술사 아빙턴, 서부 역병지대",
	["Krinkle Goodsteel, Tanaris"] = "크링클 굿스틸, 타나리스",
	["High Executor Derrington, Tirisfal Glades"] = "고위 집행관 데링턴, 티리스팔 숲",
	["Apothecary Dithers, Tirisfal Glades"] = "약제사 디더스, 티리스팔 숲",
	["Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill."] = "슬픔의 언덕에서 해골 약탈자 10마리와 침 흘리는 구울 10마리를 처치하십시오.",
	["Destroy the command tent at the Scarlet Crusade's camp between Felstone Field and Dalson's Tears, and place the Scourge banner there."] = "펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군 야영지의 지휘 천막을 파괴하고 그곳에 스컬지 깃발을 꽂으십시오.",
	["Mark each of the four towers in Andorhal with the Beacon Torch: stand in each tower's doorway to mark it."] = "신호 횃불로 안도할의 탑 네 곳을 모두 표시하십시오. 탑을 표시하려면 탑 입구에 서야 합니다.",
	["Speak with Alchemist Arbington at Chillwind Camp."] = "서리바람 야영지의 연금술사 아빙턴과 대화하십시오.",
	["Speak with Apothecary Dithers at the Bulwark."] = "보루의 약제사 디더스와 대화하십시오.",
	["Bring 15 Skeletal Fragments."] = "해골 파편 15개를 가져오십시오.",
	["Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."] = "마력이 깃든 해골 파편과 금화 15개를 가젯잔의 크링클 굿스틸에게 가져가십시오.",
	["Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the mold by the lava lake to forge the Unfinished Skeleton Key."] = "해골 열쇠 주형과 토륨 주괴 2개를 운고로 분화구의 불기둥 마루 꼭대기로 가져가십시오. 용암 호수 옆에서 주형을 사용해 미완성 해골 열쇠를 벼려 내십시오.",
	["Destroy Araj the Summoner and bring back Araj's Scarab."] = "소환사 아라즈를 처치하고 아라즈의 풍뎅이를 가져오십시오.",
	["The Skeleton Key"] = "해골 열쇠",
	["Kirtonos the Herald, a hidden boss"] = "사자 키르토노스, 숨겨진 우두머리",
	["Death Knight Darkreaver, a hidden boss"] = "죽음의 기사 다크리버, 숨겨진 우두머리",
	["Kormok, a hidden boss"] = "코르모크, 숨겨진 우두머리",
	["J'eevee, for warlocks"] = "지비, 흑마법사 전용",
	["Darkmaster Gandling"] = "암흑스승 간들링",
	["Commander Ashlam Valorfist at Chillwind Camp, in the Western Plaguelands, gives the first three quests. Alchemist Arbington, beside him, sends you for Skeletal Fragments, then to Krinkle Goodsteel in Gadgetzan for a mold. Krinkle has you forge the key at Fire Plume Ridge in Un'Goro Crater and take it back to Arbington. Arbington then sends you for Araj's Scarab from Andorhal. His last quest, The Key to Scholomance, gives the {item:13704:Skeleton Key}. It opened the door in the original game. Whether Forever still locks the door is not known yet."] = "서부 역병지대 서리바람 야영지의 사령관 아쉬람 발러피스트가 처음 세 퀘스트를 줍니다. 그 옆의 연금술사 아빙턴은 해골 파편을 가져오라고 한 뒤, 주형을 받으러 가젯잔의 크링클 굿스틸에게 보냅니다. 크링클은 운고로 분화구 불기둥 마루에서 열쇠를 벼려 아빙턴에게 가져가게 합니다. 그다음 아빙턴이 안도할에서 아라즈의 풍뎅이를 가져오라고 합니다. 그의 마지막 퀘스트 '스칼로맨스의 열쇠'로 {item:13704:Skeleton Key}를 얻습니다. 원래 게임에서는 이 열쇠로 문을 열었습니다. Forever에서도 문이 잠겨 있는지는 아직 알 수 없습니다.",
	["High Executor Derrington at the Bulwark gives the first three quests. Apothecary Dithers, beside him, sends you for Skeletal Fragments, then to Krinkle Goodsteel in Gadgetzan for a mold. Krinkle has you forge the key at Fire Plume Ridge in Un'Goro Crater and take it back to Dithers. Dithers then sends you for Araj's Scarab from Andorhal. The last quest, The Key to Scholomance, is Derrington's again and gives the {item:13704:Skeleton Key}. It opened the door in the original game. Whether Forever still locks the door is not known yet."] = "보루의 고위 집행관 데링턴이 처음 세 퀘스트를 줍니다. 그 옆의 약제사 디더스는 해골 파편을 가져오라고 한 뒤, 주형을 받으러 가젯잔의 크링클 굿스틸에게 보냅니다. 크링클은 운고로 분화구 불기둥 마루에서 열쇠를 벼려 디더스에게 가져가게 합니다. 그다음 디더스가 안도할에서 아라즈의 풍뎅이를 가져오라고 합니다. 마지막 퀘스트 '스칼로맨스의 열쇠'는 다시 데링턴이 주며, {item:13704:Skeleton Key}를 얻습니다. 원래 게임에서는 이 열쇠로 문을 열었습니다. Forever에서도 문이 잠겨 있는지는 아직 알 수 없습니다.",
	["Place the {item:13523:Blood of Innocents:1} in the brazier on the porch, and he comes. Eva Sarkhoff gives you the blood when you take her quest Kirtonos the Herald. The Blood Steward of Kirtonos, Jandice Barov and Doctor Theolen Krastinov also drop it."] = "현관의 화로에 {item:13523:Blood of Innocents:1}를 놓으면 그가 나타납니다. 에바 사크호프의 퀘스트 '사자 키르토노스'를 받으면 그녀가 피를 줍니다. 키르토노스의 혈지기, 잔다이스 바로브, 학자 테올렌 크라스티노브도 피를 떨어뜨립니다.",
	["Use the Divination Scryer in the heart of the Great Ossuary's basement. Spirits come first; once they are dead, he comes. Alliance paladins need him for Judgment and Redemption, Horde shamans for The Darkreaver Menace."] = "대납골당 지하실 한가운데에서 예언의 탐지기를 사용하십시오. 먼저 영혼들이 나타나고, 그들이 죽으면 그가 나타납니다. 얼라이언스 성기사는 '심판과 구원의 손길'에, 호드 주술사는 '다크리버의 위협'에 그가 필요합니다.",
	["On Imp Delivery, take the {item:18688:Imp in a Jar} to the alchemy lab. Once the parchment is made, take the jar back to Gorzeeki Wildeyes in the Burning Steppes."] = "'임프 배달' 퀘스트 중에 {item:18688:Imp in a Jar}을 연금술 실험실로 가져가십시오. 양피지가 만들어지면 병을 불타는 평원의 고르지키 와일드아이즈에게 가져가십시오.",
	["In the original game, he came out only once the six room bosses were dead. This is not yet checked on Forever."] = "원래 게임에서는 여섯 방의 우두머리가 모두 죽어야만 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	-- City of Dalaran: Before you go's notes (2026-10-30; drafted, to be checked)
	["The Dalaran Sewer Key"] = "달라란 하수구 열쇠",
	["Emissary Jacques in Southshore starts An Alarming Request, which leads to the Image of Archmage Modera by Lordamere Lake, outside the city. Her Heart of Disruption gives the {item:277507:Dalaran Sewer Key:2}; one key in the group lets everyone in. You need level 30 to start. Heart of Disruption asks for the {item:251961:Arcane Mote}, which the Shade of the Archmage, the last boss, drops."] = "사우스쇼어의 사절 자크가 '심상치 않은 부탁'을 주며, 이 퀘스트는 도시 밖 로다미어 호숫가의 대마법사 모데라의 환영에게로 이어집니다. 그녀의 퀘스트 '분열의 심장'으로 {item:277507:Dalaran Sewer Key:2}를 얻습니다. 파티에 열쇠가 하나만 있어도 모두 들어갈 수 있습니다. 시작하려면 30레벨이 필요합니다. '분열의 심장'은 {item:251961:Arcane Mote}를 요구하며, 이 티끌은 마지막 우두머리인 대마법사의 망령이 떨어뜨립니다.",
	["Magus Wordeen Voidglare in Tarren Mill gives Prison Break In and Key to the City (the {item:279469:Grimy Key:1}, from the Warden's Footlocker at the Lordamere Internment Camp), then Dalaran Patrols and Blood in the Streets, which leads to the Image of Archmage Modera by Lordamere Lake. Her Heart of Disruption gives the {item:277507:Dalaran Sewer Key:2}; one key in the group lets everyone in. You need level 30 to start. Heart of Disruption asks for the {item:251961:Arcane Mote}, which the Shade of the Archmage, the last boss, drops."] = "타렌 밀농장의 학자 워딘 보이드글레어가 '감옥 습격'과 '도시로 통하는 열쇠'(로다미어 포로수용소 교도관의 사물함에서 나오는 {item:279469:Grimy Key:1})를 주고, 이어서 '달라란 순찰'과 '피로 물든 거리'를 줍니다. '피로 물든 거리'는 로다미어 호숫가의 대마법사 모데라의 환영에게로 이어집니다. 그녀의 퀘스트 '분열의 심장'으로 {item:277507:Dalaran Sewer Key:2}를 얻습니다. 파티에 열쇠가 하나만 있어도 모두 들어갈 수 있습니다. 시작하려면 30레벨이 필요합니다. '분열의 심장'은 {item:251961:Arcane Mote}를 요구하며, 이 티끌은 마지막 우두머리인 대마법사의 망령이 떨어뜨립니다.",
	["Lyn the Ignored, a hidden boss"] = "외면받는 린, 숨겨진 우두머리",
	["Bring the {item:275989:Tome of Dalaran:2} to summon him. Take the {item:276561:Black Tome:1} from Archmage Arugal's table in Shadowfang Keep after his kill, and use it beside the Leyline Focus in Ambermill's keep, in Silverpine Forest. In the sewers, past Atrexis, go straight on into the tunnel to the purple rune and use the tome there. It is not used up: it can be used again after 3 minutes."] = "{item:275989:Tome of Dalaran:2}를 가져가야 그를 소환할 수 있습니다. 그림자송곳니 성채에서 대마법사 아루갈을 처치한 뒤 그의 탁자에서 {item:276561:Black Tome:1}을 가져가, 은빛소나무 숲 앰버밀 성채의 지맥 집중체 옆에서 사용하십시오. 하수구에서 아트렉시스를 지나 터널로 곧장 들어가 보라색 룬까지 간 다음, 그곳에서 고서를 사용하십시오. 고서는 사라지지 않으며, 3분 뒤에 다시 사용할 수 있습니다.",
	-- Blackrock Depths: Before you go's notes and two quest notes (2026-10-30; drafted, to be checked)
	["The Shadowforge Key"] = "어둠괴철로 열쇠",
	["The Prison Cell Key"] = "감옥 열쇠",
	["High Interrogator Gerstahn drops the {item:11140:Prison Cell Key:1}. In the original game, it opened the cells of Marshal Windsor, Kharan Mighthammer and Commander Gor'shak. This is not yet checked on Forever."] = "대심문관 게르스탄이 {item:11140:Prison Cell Key:1}를 떨어뜨립니다. 원래 게임에서는 이 열쇠로 치안대장 윈저, 카란 마이트해머, 사령관 고르샤크의 감방을 열었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Molten Core attunement"] = "화산 심장부 입장 조율",
	["Lothos Riftwaker, in Blackrock Mountain, gives Attunement to the Core. Pick up a Core Fragment at the Molten Core portal inside the Depths, then take it back to him."] = "검은바위 산의 로소스 리프트웨이커가 '심장부와의 조화'를 줍니다. 검은바위 나락 안의 화산 심장부 차원문에서 핵 조각을 집어 그에게 가져가십시오.",
	["Theldren, a hidden boss"] = "텔드렌, 숨겨진 우두머리",
	["Falrin Treeshaper in Dire Maul gives you the {item:21986:Banner of Provocation} with The Challenge. Plant it in the middle of the Ring of Law as High Justice Grimstone sentences you, then kill Theldren and his gladiators. Theldren drops the {item:22047:Top Piece of Lord Valthalak's Amulet}."] = "혈투의 전장의 팔린 트리셰이퍼가 '도전' 퀘스트와 함께 {item:21986:Banner of Provocation}을 줍니다. 대법관 그림스톤이 선고하는 동안 법의 심판장 한가운데에 깃발을 꽂은 뒤, 텔드렌과 그의 검투사들을 처치하십시오. 텔드렌은 {item:22047:Top Piece of Lord Valthalak's Amulet}을 떨어뜨립니다.",
	["The earlier A Taste of Flame comes in two versions. Either one opens this quest."] = "앞선 '화염의 맛' 퀘스트는 두 가지 버전이 있습니다. 어느 쪽이든 이 퀘스트를 열어 줍니다.",
	["Overmaster Pyron is in the quarry in Blackrock Mountain, outside the dungeon."] = "멸망의 파이론은 던전 밖, 검은바위 산의 채석장에 있습니다.",
	-- Lower and Upper Blackrock Spire: Before you go's notes, two quest notes and a start item (2026-10-30; drafted, to be checked)
	["The Seal of Ascension"] = "승천의 인장",
	["Vaelan, the Scarshield Infiltrator inside Lower Blackrock Spire, gives Seal of Ascension from level 57. Bring him the Gemstones of Spirestone, Smolderthorn and Bloodaxe, from Highlord Omokk, War Master Voone and Overlord Wyrmthalak, and the {item:12219:Unadorned Seal of Ascension:1}. Many of the Spire's foes drop it, and so does the Scarshield Quartermaster outside. Vaelan's next quest gives you {item:12339:Vaelan's Gift}. Take it to Emberstrife in the Wyrmbog, in Dustwallow Marsh, beat him down and make him forge the seal. Back at Vaelan, you get the {item:12344:Seal of Ascension}. It opens the door to Upper Blackrock Spire."] = "검은바위 첨탑 하층 안의 방패부대 첩보원 밸란이 57레벨부터 '승천의 인장'을 줍니다. 대군주 오모크, 대장군 부네, 대군주 웜타라크에게서 뾰족바위일족 보석, 가시불꽃부족 보석, 도끼부대 보석을 얻고, {item:12219:Unadorned Seal of Ascension:1}과 함께 그에게 가져가십시오. 이 인장은 첨탑의 많은 적과 바깥의 방패부대 병참장교가 떨어뜨립니다. 밸란의 다음 퀘스트에서 {item:12339:Vaelan's Gift}을 받습니다. 그것을 먼지진흙 습지대의 용의 둥지에 있는 엠버스트라이프에게 가져가 그를 굴복시키고 인장을 벼리게 하십시오. 밸란에게 돌아가면 {item:12344:Seal of Ascension}을 받습니다. 이 인장으로 검은바위 첨탑 상층의 문이 열립니다.",
	["Urok Doomhowl, a hidden boss"] = "우로크 둠하울, 숨겨진 우두머리",
	["Warosh, inside, gives the quest Urok Doomhowl. Pick up a {item:12533:Roughshod Pike}, take {item:12534:Omokk's Head:1} from Highlord Omokk, and set them up at Urok's Tribute Pile to challenge him. Kill him for Warosh's Mojo."] = "던전 안의 와로쉬가 '우로크 둠하울' 퀘스트를 줍니다. {item:12533:Roughshod Pike}을 줍고 대군주 오모크에게서 {item:12534:Omokk's Head:1}를 얻은 뒤, 우로크의 공물 더미에 세워 그에게 도전하십시오. 그를 처치하면 와로쉬의 모조를 얻습니다.",
	["Lord Valthalak, a hidden boss"] = "군주 발타라크, 숨겨진 우두머리",
	["Bodley gives you the {item:22056:Brazier of Beckoning} with Mea Culpa, Lord Valthalak, near the end of the amulet's quests. Use it in Blackrock Spire to call him. Kill him, use Lord Valthalak's Amulet on his body, and give the amulet to his spirit."] = "보들리가 '군주 발타라크여, 내 탓이오.' 퀘스트와 함께 {item:22056:Brazier of Beckoning}를 줍니다. 아뮬렛 퀘스트의 거의 끝 단계입니다. 검은바위 첨탑에서 이것을 사용해 그를 부르십시오. 그를 처치하고 시체에 군주 발타라크의 아뮬렛을 사용한 뒤, 아뮬렛을 그의 영혼에게 주십시오.",
	["Mor Grayhoof, a hidden boss"] = "모르 그레이후프, 숨겨진 우두머리",
	["Bodley gives you the {item:22049:Brazier of Beckoning} with the Mor Grayhoof versions of The Left Piece and The Right Piece of Lord Valthalak's Amulet. Use it in Blackrock Spire to call his spirit, and kill him for the piece."] = "보들리가 '군주 발타라크의 아뮬렛 왼쪽 조각'과 '오른쪽 조각' 퀘스트의 모르 그레이후프 판과 함께 {item:22049:Brazier of Beckoning}를 줍니다. 검은바위 첨탑에서 이것을 사용해 그의 영혼을 부르고, 그를 처치해 조각을 얻으십시오.",
	["Onyxia attunement"] = "오닉시아 입장 조율",
	["The Alliance chain is long. Helendis Riverhorn in the Burning Steppes starts it with Dragonkin Menace. The True Masters takes you to Lakeshire in Redridge, to Highlord Bolvar in Stormwind and back to Lakeshire, then to Marshal Maxwell in the Burning Steppes, who has you find Ragged John. Maxwell sends you into Blackrock Depths to find Marshal Windsor, who sends you back with bad news. A note found on the Depths' foes sends you back to him: get his lost papers and free him (A Crumpled Up Note, A Shred of Hope, Jail Break!). In Stormwind, meet Windsor at the city gates and keep him alive on his walk to Bolvar (Stormwind Rendezvous, The Great Masquerade). Bolvar's The Dragon's Eye sends you to Haleh in Winterspring. Her quest, Drakefire Amulet, asks for General Drakkisath's blood, in Upper Blackrock Spire. That gives the {item:16309:Drakefire Amulet}. In the original game, the amulet let you into Onyxia's Lair. Whether Forever keeps this is not known yet."] = "얼라이언스 퀘스트 줄기는 깁니다. 불타는 평원의 헬렌디스 리버혼이 '용혈족의 위협'으로 시작합니다. '진정한 지도자'는 붉은마루 산맥의 레이크샤이어로, 스톰윈드의 대영주 볼바르에게 갔다가 다시 레이크샤이어로, 그다음 불타는 평원의 치안대장 맥스웰에게 데려가며, 맥스웰은 누더기 존을 찾게 합니다. 맥스웰은 치안대장 윈저를 찾으라며 검은바위 나락으로 보내고, 윈저는 나쁜 소식과 함께 돌려보냅니다. 나락의 적에게서 찾은 쪽지가 다시 그에게 이끕니다. 잃어버린 서류를 되찾고 그를 구출하십시오('꼬깃꼬깃한 쪽지', '잔존하는 희망', '탈옥!'). 스톰윈드 성문에서 윈저를 만나 볼바르에게 가는 길 내내 그를 지키십시오('스톰윈드 회합', '대단한 가장무도회'). 볼바르의 '용의 눈'이 여명의 설원의 헬레에게 보냅니다. 그녀의 퀘스트 '비룡불꽃 아뮬렛'은 검은바위 첨탑 상층에 있는 사령관 드라키사스의 피를 요구합니다. 이 퀘스트로 {item:16309:Drakefire Amulet}을 받습니다. 원래 게임에서는 이 아뮬렛으로 오닉시아의 둥지에 들어갈 수 있었습니다. Forever에서도 그런지는 아직 알려지지 않았습니다.",
	["The Horde chain is long. Warlord Goretooth in Kargath, in the Badlands, starts it with Warlord's Command: kill Highlord Omokk, War Master Voone and Overlord Wyrmthalak in Lower Blackrock Spire and bring back the Important Blackrock Documents. Eitrigg's Wisdom takes you to Eitrigg and Thrall in Orgrimmar. Thrall's For The Horde! asks for Warchief Rend Blackhand's head, in Upper Blackrock Spire. After What the Wind Carries, The Champion of the Horde sends you to find Rexxar. He sends you to Myranda the Hag in the Western Plaguelands, who wants 20 Black Dragonspawn Eyes from Upper Blackrock Spire (Oculus Illusions). Wear her amulet and speak with Emberstrife in his den in the Wyrmbog, in Dustwallow Marsh. His Test of Skulls quests send you after four drake champions: Scryer in Winterspring, Somnus in the Swamp of Sorrows, Chronalis at the Caverns of Time in Tanaris, and last Axtroz at Grim Batol, in the Wetlands. Then show the Dull Drakefire Amulet to Rexxar (Ascension...). His quest, Blood of the Black Dragon Champion, asks for General Drakkisath's blood, in Upper Blackrock Spire. That gives the {item:16309:Drakefire Amulet}. In the original game, the amulet let you into Onyxia's Lair. Whether Forever keeps this is not known yet."] = "호드 퀘스트 줄기는 깁니다. 황야의 땅 카르가스의 장군 고어투스가 '장군의 명령'으로 시작합니다. 검은바위 첨탑 하층에서 대군주 오모크, 대장군 부네, 대군주 웜타라크를 처치하고 중요한 검은바위 문서를 가져오십시오. '아이트리그의 지혜'는 오그리마의 아이트리그와 스랄에게 데려갑니다. 스랄의 '호드를 위하여!'는 검은바위 첨탑 상층에 있는 대족장 렌드 블랙핸드의 머리를 요구합니다. '바람이 전해 온 소식' 다음에 '호드의 용사'가 렉사르를 찾으라고 보냅니다. 렉사르는 서부 역병지대의 노파 미란다에게 보내고, 그녀는 검은바위 첨탑 상층의 검은 용족 눈 20개를 원합니다('눈동자의 환영'). 그녀의 아뮬렛을 차고 먼지진흙 습지대 용의 둥지에 있는 굴에서 엠버스트라이프와 대화하십시오. 그의 '해골 시험' 퀘스트들은 네 용족 용사를 쫓게 합니다. 여명의 설원의 스크라이어, 슬픔의 늪의 솜누스, 타나리스 시간의 동굴의 크로날리스, 그리고 마지막으로 저습지 그림 바톨의 악스트로즈입니다. 그다음 빛바랜 비룡불꽃 아뮬렛을 렉사르에게 보여 주십시오('진급'). 그의 퀘스트 '검은용 용사의 피'는 검은바위 첨탑 상층에 있는 사령관 드라키사스의 피를 요구합니다. 이 퀘스트로 {item:16309:Drakefire Amulet}을 받습니다. 원래 게임에서는 이 아뮬렛으로 오닉시아의 둥지에 들어갈 수 있었습니다. Forever에서도 그런지는 아직 알려지지 않았습니다.",
	["Blackwing Lair attunement"] = "검은날개 둥지 입장 조율",
	["The Scarshield Quartermaster, in Blackrock Mountain outside the Spire, drops {item:18987:Blackhand's Command}. The letter starts a quest of the same name: touch Drakkisath's Brand, guarded by General Drakkisath, for the Mark of Drakkisath. In the original game, the mark let you into Blackwing Lair. Whether Forever keeps this is not known yet."] = "첨탑 바깥 검은바위 산의 방패부대 병참장교가 {item:18987:Blackhand's Command}를 떨어뜨립니다. 이 편지로 같은 이름의 퀘스트가 시작됩니다. 사령관 드라키사스가 지키는 드라키사스의 낙인을 만져 드라키사스의 징표를 받으십시오. 원래 게임에서는 이 징표로 검은날개 둥지에 들어갈 수 있었습니다. Forever에서도 그런지는 아직 알려지지 않았습니다.",
	["Attunement to the Core, from Lothos Riftwaker in Blackrock Mountain, is done in Blackrock Depths. Here, Duke Hydraxis in Azshara asks for Pyroguard Emberseer's eye with Eye of the Emberseer. That quest leads on into Molten Core but is not the attunement."] = "검은바위 산의 로소스 리프트웨이커가 주는 '심장부와의 조화'는 검은바위 나락에서 진행합니다. 이곳에서는 아즈샤라의 군주 히드락시스가 '엠버시어의 눈' 퀘스트로 불의수호자 엠버시어의 눈을 요구합니다. 이 퀘스트는 화산 심장부로 이어지지만 입장 조율은 아닙니다.",
	["Offered once one of the four Components of Importance quests is done."] = "'중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다.",
	["Offered once one of the four More Components of Importance quests is done."] = "'또 다른 중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다.",
	["Warlord Goretooth's Command"] = "장군 고어투스의 명령서",
	-- Dire Maul East and North: Before you go's notes and two quest notes (2026-10-30; drafted, to be checked)
	["The Crescent Key"] = "초승달 열쇠",
	["Pusillin drops the {item:18249:Crescent Key:1} every time. Chase him through Warpwood Quarter and kill him. In the original game, the key opened the doors into Gordok Commons and Capital Gardens. This is not yet checked on Forever."] = "푸실린은 언제나 {item:18249:Crescent Key:1}를 떨어뜨립니다. 굽이나무 지구에서 그를 쫓아가 처치하십시오. 원래 게임에서는 이 열쇠로 고르독 광장과 수도 정원의 문을 열었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Isalien, a hidden boss"] = "이살리엔, 숨겨진 우두머리",
	["Bodley, inside Blackrock Mountain, gives you the {item:22050:Brazier of Beckoning} with the Isalien versions of The Left Piece and The Right Piece of Lord Valthalak's Amulet. Use it in the Shrine of Eldretharr to call her spirit, and kill her."] = "검은바위 산 안의 보들리가 '군주 발타라크의 아뮬렛 왼쪽 조각'과 '오른쪽 조각' 퀘스트의 이살리엔 판과 함께 {item:22050:Brazier of Beckoning}을 줍니다. 엘드레사르 제단에서 이것을 사용해 그녀의 영혼을 부르고, 그녀를 처치하십시오.",
	["The Gordok door keys"] = "고르독 문 열쇠",
	["Guard Mol'dar drops the {item:18268:Gordok Inner Door Key:1}. The {item:18266:Gordok Courtyard Key:1} is in Fengus's Chest. In the original game, they opened the inner door and the courtyard door of Gordok Commons. This is not yet checked on Forever."] = "경비병 몰다르는 {item:18268:Gordok Inner Door Key:1}를 떨어뜨립니다. {item:18266:Gordok Courtyard Key:1}는 펜구스의 상자에 있습니다. 원래 게임에서는 이 열쇠들로 고르독 광장의 안쪽 문과 안뜰 문을 열었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Offered once one of the four Components of Importance quests is done. In the original game, Isalien's was the one that asks for a Starbreeze Village Relic."] = "'중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다. 원래 게임에서는 별바람 마을 유물을 요구하는 퀘스트가 이살리엔의 것이었습니다.",
	["Offered once one of the four More Components of Importance quests is done. In the original game, Isalien's was the one that asks for a Starbreeze Village Relic."] = "'또 다른 중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다. 원래 게임에서는 별바람 마을 유물을 요구하는 퀘스트가 이살리엔의 것이었습니다.",
	-- Dire Maul West and the rest of Dire Maul: Before you go's notes and Volume II (2026-10-30; drafted, to be checked)
	["Immol'thar's prison"] = "이몰타르의 감옥",
	["A force field holds Immol'thar in his prison. Kill the guardians at the five pylons that power it, and the field goes down. The Shen'dralar Ancient in the courtyard asks this of you in The Madness Within."] = "이몰타르는 감옥 안에서 보호막에 갇혀 있습니다. 보호막에 힘을 주는 다섯 수정탑의 수호자를 처치하면 보호막이 사라집니다. 뜰에 있는 셴드랄라 고대인이 '내면의 광기' 퀘스트로 이 일을 부탁합니다.",
	["Lord Hel'nurath, a hidden boss"] = "군주 헬누라스, 숨겨진 우두머리",
	["Mor'zul Bloodbringer's quest Dreadsteed of Xoroth is done in the Prison of Immol'thar. It needs {item:18663:J'eevee's Jar}, a {item:18629:Black Lodestone} and {item:18670:Xorothian Glyphs}. Gorzeeki Wildeyes in the Burning Steppes sells all three. In the original game, a warlock who already had the Dreadsteed could do the ritual again, and Lord Hel'nurath came instead of the steed. This is not yet checked on Forever."] = "모르줄 블러드브링어의 퀘스트 '소로스의 공포마'는 이몰타르의 감옥에서 진행합니다. 이 퀘스트에는 {item:18663:J'eevee's Jar}, {item:18629:Black Lodestone}, {item:18670:Xorothian Glyphs}이 필요합니다. 불타는 평원의 고르지키 와일드아이즈가 세 가지를 모두 팝니다. 원래 게임에서는 이미 공포마를 얻은 흑마법사가 의식을 다시 하면 공포마 대신 군주 헬누라스가 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Enchanted Thorium Platemail: Volume II"] = "마력깃든 토륨 갑옷 II",
	["Enchanted Thorium Platemail: Volume II, bound from its two halves"] = "마력깃든 토륨 갑옷 II, 상권과 하권을 합쳐 만든 책",
	["Combine the Top Half (Rattlegore, Scholomance) and the Bottom Half (Crimson Hammersmith, Stratholme) of Advanced Armorsmithing: Volume II."] = "고급 방어구제작: II 상권(들창어금니, 스칼로맨스)과 고급 방어구제작: II 하권(진홍십자군 대장장이, 스트라솔름)을 합쳐야 합니다.",
	["For blacksmiths (skill 300)."] = "대장기술 숙련도 300 필요.",
	-- Scarlet Monastery: Before you go's notes and two quest notes (2026-10-30; drafted, to be checked)
	["The Scarlet Key"] = "붉은십자군 열쇠",
	["{item:7146:The Scarlet Key:2} is in Doan's Strongbox, behind Arcanist Doan in the Library. In the original game, it opened the doors to the Armory and the Cathedral. This is not yet checked on Forever."] = "{item:7146:The Scarlet Key:2}는 도서관에 있는 신비술사 도안의 뒤, 도안의 금고에 들어 있습니다. 원래 게임에서는 이 열쇠로 무기고와 대성당의 문을 열었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["The road to In the Name of the Light"] = "'빛의 이름으로!'까지 가는 길",
	["Brother Crowley in Stormwind sends you to Brother Anton at Nijel's Point, in Desolace. Anton's Down the Scarlet Path asks you to kill 30 Undead Ravagers. He then gives you a letter for Raleigh the Devout in Southshore, who gives In the Name of the Light."] = "스톰윈드의 수도사 크로울리가 잊혀진 땅 나이젤의 야영지에 있는 수도사 안톤에게 보냅니다. 안톤의 '붉은십자군의 길'은 언데드 약탈자 30마리를 처치하라고 합니다. 그다음 안톤이 사우스쇼어의 경건한 신자 랄레이에게 갈 편지를 주고, 랄레이가 '빛의 이름으로!'를 줍니다.",
	["Nancy Vishas has the ring, in Alterac Mountains, outside the dungeon. Interrogator Vishas does not drop it."] = "반지는 던전 밖, 알터랙 산맥에 있는 낸시 비샤스가 가지고 있습니다. 심문관 비샤스는 반지를 떨어뜨리지 않습니다.",
	["The book lies at the north end of the hallway to Arcanist Doan. Once this and Items of Power are done, Tabetha gives Mage's Wand: speak with her after her ritual and choose one of three wands."] = "책은 신비술사 도안에게 이어지는 복도의 북쪽 끝에 있습니다. 이 퀘스트와 '힘의 물건'을 마치면 타베사가 '마법사의 마법봉'을 줍니다. 의식이 끝난 뒤 그녀에게 말을 걸고 마법봉 세 개 중 하나를 고르십시오.",
	-- City of Dalaran and Shadowfang Keep: Before you go's notes, two quests and their notes (2026-10-30; drafted, to be checked)
	["Friend of the Kirin Tor"] = "키린 토의 친구",
	["Shrewd Negotiations"] = "기민한 협상",
	["Archmage Celindra, City of Dalaran"] = "대마법사 셀린드라, 달라란",
	["Speak to Archmage Celindra in the City of Dalaran."] = "달라란에 있는 대마법사 셀린드라와 대화해야 합니다.",
	["Speak with Archmage Celindra in the City of Dalaran."] = "달라란에 있는 대마법사 셀린드라와 대화해야 합니다.",
	["The quest hands you the Arcane Mote to take to her."] = "퀘스트를 받으면 그녀에게 가져갈 비전 티끌을 받습니다.",
	["Magus Wordeen Voidglare — Tarren Mill"] = "학자 워딘 보이드글레어 — 타렌 밀농장",
	["The courtyard door"] = "안뜰 문",
	["Deathstalker Adamant is held prisoner inside the keep. In the original game, freeing him opened the courtyard door, the way on. This is not yet checked on Forever."] = "죽음의추적자 아다만트가 성채 안에 갇혀 있습니다. 원래 게임에서는 그를 풀어 주면 앞으로 나아가는 길인 안뜰 문이 열렸습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Sorcerer Ashcrombe is held prisoner inside the keep. In the original game, freeing him opened the courtyard door, the way on. This is not yet checked on Forever."] = "마법사 애쉬크롬이 성채 안에 갇혀 있습니다. 원래 게임에서는 그를 풀어 주면 앞으로 나아가는 길인 안뜰 문이 열렸습니다. Forever에서는 아직 확인되지 않았습니다.",
	["The Black Tome"] = "검은 고서",
	["After Archmage Arugal dies, take the {item:276561:Black Tome:1} from his table. It leads to the {item:275989:Tome of Dalaran:2}, which summons Lyn the Ignored, a hidden boss in the City of Dalaran. That dungeon's Before you go says how."] = "대마법사 아루갈이 죽은 뒤 그의 탁자에서 {item:276561:Black Tome:1}을 가져가십시오. 이 고서는 달라란의 숨은 우두머리 외면받는 린을 소환하는 {item:275989:Tome of Dalaran:2}로 이어집니다. 방법은 그 던전의 '출발 전에'에 나와 있습니다.",
	-- Blackfathom Deeps and Gnomeregan: Before you go's notes, Seeking the Kor Gem, Techbot and the ring quests' notes (2026-10-30; drafted, to be checked)
	["Seeking the Kor Gem"] = "코르석을 찾아서",
	["Ulric Frostveil, Zoram'gar Outpost, Ashenvale"] = "울릭 프로스트베일, 잿빛 골짜기 조람가르 전초기지",
	["Ulric Frostveil — Zoram'gar Outpost"] = "울릭 프로스트베일 — 조람가르 전초기지",
	["Bring a Kor Gem to Ulric Frostveil in Ashenvale."] = "잿빛 골짜기의 울릭 프로스트베일에게 코르석을 가져가야 합니다.",
	["Baron Aquanis, a hidden boss"] = "군주 아쿠아니스, 숨겨진 우두머리",
	["Je'neu Sancrea at Zoram'gar Outpost gives Amongst the Ruins. In the dungeon, click the Fathom Stone in the water: it gives the {item:16762:Fathom Core} and Baron Aquanis rises from it. He drops the {item:16782:Strange Water Globe:2}, which starts the quest Baron Aquanis."] = "조람가르 전초기지의 제네우 생크리가 '폐허 사이로' 퀘스트를 줍니다. 던전 안에서 물속의 심연의 돌을 클릭하면 {item:16762:Fathom Core}를 얻고 군주 아쿠아니스가 나타납니다. 그는 {item:16782:Strange Water Globe:2}를 떨어뜨리며, 이것으로 '군주 아쿠아니스' 퀘스트가 시작됩니다.",
	["The Workshop Key"] = "작업장 열쇠",
	["Electrocutioner 6000 drops the {item:6893:Workshop Key:1}. In the original game, it opened the Workshop doors to the back entrance. This is not yet checked on Forever."] = "기계화 문지기 6000이 {item:6893:Workshop Key:1}를 떨어뜨립니다. 원래 게임에서는 이 열쇠로 뒤쪽 입구로 이어지는 작업장 문을 열었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["The Goblin Transponder"] = "고블린 응답장치",
	["Outside the instance, in Dun Morogh."] = "인스턴스 밖, 던 모로에 있습니다.",
	-- Razorfen Kraul and Razorfen Downs: Before you go's notes and the An Unholy Alliance notes (2026-10-30; drafted, to be checked)
	["Blueleaf Tubers: the tools in Ratchet"] = "청엽수 줄기: 톱니항에서 챙길 도구",
	["Mebok Mizzyrix in Ratchet gives Blueleaf Tubers. Before you go, take the {item:5880:Crate With Holes}, the {item:6684:Snufflenose Command Stick} and the {item:5897:Snufflenose Owner's Manual} from beside him, and read the manual. In the Kraul, the crate calls a Snufflenose Gopher and the stick makes it find the tubers."] = "톱니항의 메보크 미지릭스가 '청엽수 줄기' 퀘스트를 줍니다. 출발하기 전에 그 옆에 있는 {item:5880:Crate With Holes}, {item:6684:Snufflenose Command Stick}, {item:5897:Snufflenose Owner's Manual}을 챙기고 설명서를 읽으세요. 우리 안에서 상자로 땅다람쥐를 부르고, 지휘봉으로 줄기를 찾게 합니다.",
	["Belnistrasz and the idol"] = "벨리스트라즈와 우상",
	["Talk to Belnistrasz first; he is inside. Scourge of the Downs asks you to hand back his Oathstone. He then gives Extinguishing the Idol: take him to the quilboar's idol near the entrance and keep him alive while he does the ritual. When he is gone, his brazier stays behind: click it to hand the quest in. In the original game, waves of quilboar came at him during the ritual. This is not yet checked on Forever."] = "먼저 벨리스트라즈와 대화하세요. 그는 던전 안에 있습니다. '가시덩굴 구릉의 스컬지'에서는 그의 서약의 돌을 돌려줍니다. 그다음 그가 '우상 진화'를 줍니다: 입구 근처에 있는 멧돼지인간의 우상까지 그를 데려가고, 의식을 치르는 동안 그를 지켜야 합니다. 그가 떠나면 화로가 남습니다. 화로를 클릭해 퀘스트를 완료하세요. 원래 게임에서는 의식 중에 멧돼지인간이 여러 차례 몰려와 그를 공격했습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Tuten'kash, a hidden boss"] = "투텐카쉬, 숨겨진 우두머리",
	["Ring the Gong in the dungeon to call him. In the original game, each ring brought a wave of foes, and Tuten'kash came with the last. This is not yet checked on Forever."] = "던전 안의 징을 울려 그를 부릅니다. 원래 게임에서는 징을 울릴 때마다 적이 한 무리씩 나왔고, 마지막에 투텐카쉬가 나왔습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Ambassador Malcin stands outside the instance, in the Barrens near the entrance."] = "사절 말킨은 인스턴스 밖, 불모의 땅의 입구 근처에 있습니다.",
	-- Razorfen Kraul: An Unholy Alliance listed after the Small Scroll quest, its note saying where Malcin stands (2026-11-03; drafted, to be checked)
	["Ambassador Malcin stands outside Razorfen Downs, in the Barrens near its entrance."] = "사절 말킨은 가시덩굴 구릉 밖, 불모의 땅의 입구 근처에 있습니다.",
	-- Uldaman, Zul'Farrak and Maraudon: Before you go's notes, Indurium Ore and its chain, the lead-in notes and the Shattered Necklace (2026-10-30; drafted, to be checked)
	["Quests to take first, and the dig site"] = "먼저 받을 퀘스트와 발굴지",
	["Take these before you go in: Back to Uldaman, from Talvash del Kissel in Ironforge, and The Lost Dwarves, from Prospector Stormpike. Uldaman Reagent Run comes after Badlands Reagent Run. Keep the {item:7667:Talvash's Phial of Scrying} that Back to Uldaman gives you: you hand in Find the Gems with it. Some quests are finished in the dig-site caves, outside the instance: Solution to Doom (the Ancient Chest), Agmond's Fate (the urns), Reclaimed Treasures (Krom Stoutarm's Chest), and A Sign of Hope and Amulet of Secrets."] = "들어가기 전에 다음 퀘스트를 받으세요: 아이언포지의 탈바쉬 델 키젤이 주는 '울다만으로 돌아가기', 발굴조사단장 스톰파이크가 주는 '길 잃은 드워프'. '울다만에서 재료 찾기'는 '황야의 땅에서 재료 찾기' 다음에 받습니다. '울다만으로 돌아가기'에서 받는 {item:7667:Talvash's Phial of Scrying}을 버리지 마세요. '보석 찾기'를 이것으로 완료합니다. 일부 퀘스트는 인스턴스 밖 발굴지 동굴에서 완료합니다: '멸망의 해결책'(고대의 상자), '아그몬드의 운명'(단지), '보물 되찾기'(크롬 스타우트암의 궤짝), 그리고 '희망의 전조'와 '비밀의 아뮬렛'.",
	["Take Necklace Recovery, Take 2 from Dran Droffers in Orgrimmar before you go in. Uldaman Reagent Run comes after Badlands Reagent Run. Some quests are finished in the dig-site caves, outside the instance: Solution to Doom (the Ancient Chest) and Reclaimed Treasures (the Garrett Family Chest)."] = "들어가기 전에 오그리마의 드란 드로퍼스에게서 '목걸이 회수 - 2차 시도'를 받으세요. '울다만에서 재료 찾기'는 '황야의 땅에서 재료 찾기' 다음에 받습니다. 일부 퀘스트는 인스턴스 밖 발굴지 동굴에서 완료합니다: '멸망의 해결책'(고대의 상자)과 '보물 되찾기'(가레트가의 궤짝).",
	["Indurium Ore"] = "인듀리움 광석",
	["Pozzik, Thousand Needles"] = "포직, 버섯구름 봉우리",
	["Bring 4 Indurium Ore to Pozzik on the Shimmering Flats."] = "인듀리움 광석 4개를 소금 평원에 있는 포직에게 가져가야 합니다.",
	["Repeatable. The ore is found only in Uldaman: many of its foes drop it, and so does the Indurium Mineral Vein."] = "반복 가능. 광석은 울다만에서만 구할 수 있습니다. 그곳의 많은 적과 인듀리움 광맥에서 얻습니다.",
	["Salt Flat Venom"] = "소금 평원의 독",
	["Hardened Shells"] = "단단한 등껍질",
	["Martek the Exiled"] = "추방자 마르텍",
	["Indurium"] = "인듀리움",
	["News for Fizzle"] = "피즐에게 전할 소식",
	["Keeping Pace"] = "속도 맞추기",
	["Rizzle's Schematics"] = "리즐의 설계도",
	["Shattered Necklace"] = "부서진 목걸이",
	["Optional: it leads to The Hidden Chamber."] = "선택 사항: '비밀 석실'로 이어집니다.",
	["The Executioner's Key"] = "사형집행인의 열쇠",
	["The Sandfury Executioner drops the {item:8444:Executioner's Key:1}. In the original game, it opened the prisoners' cages on the pyramid, and freeing them started the fight on the stairs. This is not yet checked on Forever. Sergeant Bly drops the rod Chief Engineer Bilgewhizzle asks for."] = "성난모래부족 사형집행인이 {item:8444:Executioner's Key:1}를 떨어뜨립니다. 원래 게임에서는 이 열쇠로 피라미드 위 포로들의 우리를 열었고, 포로를 풀어 주면 계단 전투가 시작되었습니다. Forever에서는 아직 확인되지 않았습니다. 하사관 블라이는 선임기술자 빌지위즐이 찾는 탐사막대를 떨어뜨립니다.",
	["Gahz'rilla, a hidden boss"] = "가즈릴라, 숨겨진 우두머리",
	["Strike the Gong of Zul'Farrak with the {item:9240:Mallet of Zul'Farrak} to call him. Qiaga the Keeper, in the Hinterlands, drops the {item:9241:Sacred Mallet}. In the original game, you used it at the altar atop Jintha'Alor to make the Mallet of Zul'Farrak. This is not yet checked on Forever."] = "{item:9240:Mallet of Zul'Farrak}로 줄파락의 징을 쳐서 그를 부릅니다. 동부 내륙지의 수호자 키아가가 {item:9241:Sacred Mallet}를 떨어뜨립니다. 원래 게임에서는 이것을 진타알로 꼭대기의 제단에서 사용해 줄파락의 망치를 만들었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Given by Jennea Cannon (Stormwind), Bink (Ironforge), Deino (Orgrimmar) and Anastasia Hartwell (Undercity). Optional: it leads to Tiara of the Deep."] = "제니아 캐논(스톰윈드), 빙크(아이언포지), 다이노(오그리마), 아나스타샤 하트웰(언더시티)에게서 받을 수 있습니다. 선택 사항: '심연의 티아라'로 이어집니다.",
	["Optional: it leads to Scarab Shells."] = "선택 사항: '왕쇠똥구리 껍질'로 이어집니다.",
	["Cavindra in Desolace gives Legends of Maraudon: bring back the Celebrian Rod, which Noxxion drops, and the Celebrian Diamond, which Lord Vyletongue drops, and find a way to speak with Celebras. Celebras the Redeemed, inside, then gives The Scepter of Celebras: help him with the ritual, and he gives you the {item:17191:Scepter of Celebras}. In the original game, it let you use the portal near the entrance to go straight to inner Maraudon. This is not yet checked on Forever."] = "잊혀진 땅의 카빈드라가 '마라우돈의 전설'을 줍니다: 녹시온이 떨어뜨리는 셀레브리안 마법봉과 군주 바일텅이 떨어뜨리는 셀레브리안 다이아몬드를 가져오고, 셀레브라스와 대화할 방법을 찾아야 합니다. 그다음 던전 안의 회복된 셀레브라스가 '셀레브라스의 홀'을 줍니다: 의식을 도우면 {item:17191:Scepter of Celebras}을 줍니다. 원래 게임에서는 이것으로 입구 근처의 차원문을 사용해 마라우돈 안쪽으로 바로 갈 수 있었습니다. Forever에서는 아직 확인되지 않았습니다.",
	-- The Temple of Atal'Hakkar and Stratholme: Before you go's notes (Atal'alarion, the Avatar of Hakkar, Jarien and Sothos, Stratholme's Key to the City) and the quest notes (the Bloodpetal quests, Dead Man's Plea, the amulet's pieces, Above and Beyond) (2026-10-30; drafted, to be checked)
	["Atal'alarion, a hidden boss"] = "아탈알라리온, 숨겨진 우두머리",
	["Marvon Rivetseeker in Tanaris gives The Stone Circle, then Secret of the Circle, which ends at the Idol of Hakkar in the temple's circle of statues. In the original game, touching the statues in the order the Stone Circle shows called Atal'alarion, the idol's guardian. This is not yet checked on Forever."] = "타나리스의 마본 리벳시커가 '돌무리'를 준 뒤 '돌무리의 비밀'을 줍니다. 이 퀘스트는 사원의 석상 원 안에 있는 학카르 신상에서 끝납니다. 원래 게임에서는 돌무리가 보여 주는 순서대로 석상을 만지면 신상의 수호자 아탈알라리온이 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Avatar of Hakkar, a hidden boss"] = "학카르의 화신, 숨겨진 우두머리",
	["Larion then gives Bloodpetal Zapper in Un'Goro Crater: bring him a Bloodpetal Sprout, and he gives the Bloodpetal Zapper."] = "그 다음 운고로 분화구의 라리온이 '붉은꽃잎 구제장치'를 줍니다. 붉은꽃잎 새싹 1개를 가져가면 붉은꽃잎 구제장치를 줍니다.",
	["Muigin then gives Bloodpetal Sprouts in Un'Goro Crater: bring him 3 Bloodpetal Sprouts."] = "그 다음 운고로 분화구의 무이긴이 '붉은꽃잎 새싹'을 줍니다. 붉은꽃잎 새싹 3개를 가져가십시오.",
	["Jarien and Sothos, hidden bosses"] = "자리엔과 소도스, 숨겨진 우두머리",
	["Bodley gives you the {item:22051:Brazier of Beckoning} with the Jarien and Sothos versions of The Left Piece and The Right Piece of Lord Valthalak's Amulet. Use it in Stratholme to call their spirits, and kill them for the piece."] = "보들리가 '군주 발타라크의 아뮬렛 왼쪽 조각'과 '오른쪽 조각' 퀘스트의 자리엔과 소도스 판과 함께 {item:22051:Brazier of Beckoning}를 줍니다. 스트라솔름에서 이것을 사용해 그들의 영혼을 부르고, 그들을 처치해 조각을 얻으십시오.",
	["Offered once one of the four Components of Importance quests is done. Three Kings of Flame also needs your side's Bodley's Unfortunate Fate, after your class's Anthion's Parting Words."] = "'중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다. '세 고위 정령의 불꽃'을 받으려면 자신의 직업에 맞는 '안시온의 작별 인사' 뒤에 이어지는, 자기 진영의 '보들리의 불행한 운명'도 완료해야 합니다.",
	["Offered once one of the four More Components of Importance quests is done. Three Kings of Flame also needs your side's Bodley's Unfortunate Fate, after your class's Anthion's Parting Words."] = "'또 다른 중요한 요소' 퀘스트 네 가지 중 하나를 완료하면 받을 수 있습니다. '세 고위 정령의 불꽃'을 받으려면 자신의 직업에 맞는 '안시온의 작별 인사' 뒤에 이어지는, 자기 진영의 '보들리의 불행한 운명'도 완료해야 합니다.",
	["Duke Nicholas Zverenhoff then sends you to Lord Maxwell Tyrosus at Light's Hope Chapel, who gives The Argent Hold: open it for a choice of Argent Avenger, Argent Defender or Argent Crusader."] = "그 다음 공작 니콜라스 즈바른호프가 희망의 빛 예배당의 맥스웰 티로서스 경에게 보내고, 그가 '여명회의 궤'를 줍니다. 궤를 열어 은빛 복수자, 은빛 수호자, 은빛 성전사 중 하나를 고르십시오.",
	["Stratholme's Key to the City"] = "스트라솔름의 도시로 통하는 열쇠",
	["Magistrate Barthilas always drops the {item:12382:Key to the City:2}. It is not the key from the City of Dalaran's quest of the same name. In the original game, it opened the Service Entrance's gate from outside, so a group could go straight to the Baron's side. This is not yet checked on Forever."] = "집정관 발실라스는 항상 {item:12382:Key to the City:2}를 떨어뜨립니다. 달라란의 같은 이름 퀘스트에서 얻는 열쇠가 아닙니다. 원래 게임에서는 이 열쇠로 바깥에서 공무용 입구의 문을 열어, 일행이 곧바로 남작이 있는 쪽으로 갈 수 있었습니다. Forever에서는 아직 확인되지 않았습니다.",
	-- Forever's own dungeons: Before you go's notes (the Dark Iron Map, the Titan Relic), the Treaty of Understanding and two quest notes (Unending Torment, part 2; Changing Tastes) (2026-10-30; drafted, to be checked)
	["Treaty of Understanding"] = "상호 이해 조약",
	["The Dark Iron Map"] = "검은무쇠 지도",
	["Dark Iron Spies and Captain Beld, at Ironband's Compound in Dun Morogh, drop the {item:274268:Dark Iron Map:1}. It starts Underground Map: bring it to Earthseer Farsen, at his camp above the Gol'Bolar Quarry, and he gives Old Ironforge Incursion. Optional lead-ins: Beldin Steelgrill's A Visitor to Dun Morogh sends you to Farsen, who then gives Farsen's Watch and Nip 'Em in the Bud, which sends you after the spies."] = "던 모로의 아이언밴드 주둔지에 있는 검은무쇠단 비밀요원과 벨드 대장이 {item:274268:Dark Iron Map:1}를 떨어뜨립니다. 이 지도로 '지하 지도'가 시작됩니다. 골볼라 채석장 위 야영지에 있는 대지예언자 파르센에게 가져가면 '구 아이언포지 침투'를 줍니다. 선택 사항인 사전 퀘스트: 벨딘 스틸그릴의 '던 모로의 방문자'가 파르센에게 보내고, 파르센은 이어서 '파르센의 감시'와 비밀요원을 처치하는 '싹을 자르다'를 줍니다.",
	["New in Forever: part 2, given in the Undercity once the Abominable Head is with Master Apothecary Faranell. He hands you the Head of the Baron: take it to Othmar's body, the Unfinished Abomination."] = "포에버 신규: 2단계. 흉측한 머리를 수석 연금술사 파라넬에게 전달하면 언더시티에서 받습니다. 파라넬이 남작의 머리를 건네주면 미완성 누더기골렘인 오스마르의 몸에 가져가세요.",
	["The Titan Relic"] = "티탄의 유물",
	["The Relic Guardian, the last boss, drops the {item:270865:Titan Relic:1}. It starts Lost Relic Carry: bring it to Prospector Whelgar at Whelgar's Excavation Site, who then gives Prehistoric Prism. Quests that lead here: Seeking Caitlin, from Llana in Astranaar, to Lost in the Thicket Things; Rethiel the Greenwarden's Tramping Paws, Fire Taboo and Blisters on The Land before Horrors in the Highland; James Halloran's Young Crocolisk Skins before Highland Hides."] = "마지막 우두머리인 유물 수호자가 {item:270865:Titan Relic:1}을 떨어뜨립니다. 이 유물로 '잃어버린 유물 운반'이 시작됩니다. 웰가르의 발굴현장에 있는 발굴조사단장 웰가르에게 가져가면 이어서 '선사 시대의 프리즘'을 줍니다. 이곳으로 이어지는 퀘스트: 아스트라나르의 라나가 주는 '케이틀린을 찾아서'는 '덤불 속에서 길을 잃다'로 이어집니다. 신록의수호자 레시엘의 '파괴의 손길', '화재 예방', '대지의 상처'는 '고원의 공포' 전에, 제임스 할로란의 '새끼 악어 가죽'은 '고원의 가죽' 전에 해야 합니다.",
	["The Relic Guardian, the last boss, drops the {item:270866:Titan Relic:1}. It starts Elder Knowledge: take it to Bashana Runetotem on the Elder Rise in Thunder Bluff, who then gives Earthen Echo. Quests that lead here: Zaruk's Dragonmaw Rumors, in the Arathi Highlands, to Open the Maw."] = "마지막 우두머리인 유물 수호자가 {item:270866:Titan Relic:1}을 떨어뜨립니다. 이 유물로 '장로의 지식'이 시작됩니다. 썬더 블러프 장로의 봉우리에 있는 바샤나 룬토템에게 가져가면 이어서 '대지의 메아리'를 줍니다. 이곳으로 이어지는 퀘스트: 아라시 고원에서 자루크가 주는 '용아귀일족에 대한 소문'은 '아귀를 열어라'로 이어집니다.",
	-- Small fixes: Pip Quickwit, Forever's name for Finkle Einhorn; Underground Assault's and The Final Tablets' notes; Gahz'rilla's and the Scepter of Celebras' notes before you go (2026-10-30; drafted, to be checked)
	["Pip Quickwit, At Your Service!"] = "핍 퀵윗, 명을 받듭니다!",
	["Pip Quickwit, inside the dungeon"] = "핍 퀵윗, 던전 내부",
	["After this, Prospector Ironboot sends you to Yeh'kinya in Tanaris with Confront Yeh'kinya, which gives a choice of Faded Hakkari Cloak or Tattered Hakkari Cape."] = "그 후 발굴조사단장 아이언부트가 '예킨야와의 대면' 퀘스트로 타나리스의 예킨야에게 보냅니다. 이 퀘스트는 빛바랜 학카리 망토와 해진 학카리 망토 중 하나를 줍니다.",
	["In the original game, you struck the Gong of Zul'Farrak, inside, with the {item:9240:Mallet of Zul'Farrak} to call him. Qiaga the Keeper, in the Hinterlands, drops the {item:9241:Sacred Mallet}, which you used at the altar atop Jintha'Alor to make the Mallet of Zul'Farrak. This is not yet checked on Forever."] = "원래 게임에서는 던전 안의 줄파락의 징을 {item:9240:Mallet of Zul'Farrak}로 쳐서 그를 불렀습니다. 동부 내륙지의 수호자 키아가가 {item:9241:Sacred Mallet}를 떨어뜨리며, 원래 게임에서는 이것을 진타알로 꼭대기의 제단에서 사용해 줄파락의 망치를 만들었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Cavindra in Desolace gives Legends of Maraudon: get the Celebrian Rod, which Noxxion drops, and the Celebrian Diamond, which Lord Vyletongue drops, and find a way to speak with Celebras. You hand it in inside, to Celebras the Redeemed, who then gives The Scepter of Celebras: help him with the ritual, and he gives you the {item:17191:Scepter of Celebras}. In the original game, it let you use the portal near the entrance to go straight to inner Maraudon. This is not yet checked on Forever."] = "잊혀진 땅의 카빈드라가 '마라우돈의 전설'을 줍니다: 녹시온이 떨어뜨리는 셀레브리안 마법봉과 군주 바일텅이 떨어뜨리는 셀레브리안 다이아몬드를 구하고, 셀레브라스와 대화할 방법을 찾아야 합니다. 이 퀘스트는 던전 안에서 회복된 셀레브라스에게 완료하며, 그가 이어서 '셀레브라스의 홀'을 줍니다: 의식을 도우면 {item:17191:Scepter of Celebras}을 줍니다. 원래 게임에서는 이것으로 입구 근처의 차원문을 사용해 마라우돈 안쪽으로 바로 갈 수 있었습니다. Forever에서는 아직 확인되지 않았습니다.",
	-- The amulet notes that keep what the Quests tab's one-of steps can't show (2026-10-30; drafted, to be checked).
	["Bodley's Unfortunate Fate comes after your class's Anthion's Parting Words."] = "보들리의 불행한 운명은 자신의 직업에 맞는 안시온의 작별 인사 다음에 이어집니다.",
	["In the original game, Isalien's was the one that asks for a Starbreeze Village Relic."] = "원래 게임에서는 별바람 마을 유물을 요구하는 퀘스트가 이살리엔의 것이었습니다.",
	-- The one-of steps' own pages: Bodley's Unfortunate Fate, one for each side (2026-10-30; drafted, to be checked).
	["Bodley's Unfortunate Fate"] = "보들리의 불행한 운명",
	["Deliana, Ironforge"] = "델리아나, 아이언포지",
	["Mokvar, Orgrimmar"] = "모크바르, 오그리마",
	["Bodley, Blackrock Mountain"] = "보들리, 검은바위 산",
	-- Onyxia's Lair: its quests, their start item and notes (2026-10-30; drafted, to be checked)
	["Victory for the Alliance"] = "얼라이언스의 승리",
	["Victory for the Horde"] = "호드의 승리",
	["Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind."] = "오닉시아의 머리를 스톰윈드의 대영주 볼바르 폴드라곤에게 가져가십시오.",
	["Take the Head of Onyxia to Thrall in Orgrimmar."] = "오닉시아의 머리를 오그리마의 스랄에게 가져가십시오.",
	["Head of Onyxia, dropped by Onyxia"] = "오닉시아의 머리, 오닉시아에게서 획득",
	["Head of Onyxia"] = "오닉시아의 머리",
	["Dropped by Onyxia."] = "오닉시아에게서 획득합니다.",
	["Highlord Bolvar Fordragon, Stormwind City"] = "대영주 볼바르 폴드라곤, 스톰윈드",
	["Then Bolvar sends you to Major Mattingly in the Valley of Heroes with Celebrating Good Times, which gives a choice of Onyxia Blood Talisman, Dragonslayer's Signet or Onyxia Tooth Pendant."] = "그 후 볼바르가 '축하의 시간' 퀘스트로 영웅의 계곡의 매팅리 소령에게 보냅니다. 이 퀘스트는 오닉시아 피의 부적, 용사냥꾼의 인장, 오닉시아 이빨 목걸이 중 하나를 줍니다.",
	["Then Thrall sends you to Overlord Runthak in the Valley of Strength with For All To See, which gives a choice of Onyxia Blood Talisman, Dragonslayer's Signet or Onyxia Tooth Pendant."] = "그 후 스랄이 '모두가 볼 수 있도록' 퀘스트로 힘의 골짜기의 대군주 룬탁에게 보냅니다. 이 퀘스트는 오닉시아 피의 부적, 용사냥꾼의 인장, 오닉시아 이빨 목걸이 중 하나를 줍니다.",
	-- Blackrock Depths' A Crumpled Up Note where another dungeon's page shows it, the dungeon named (2026-10-30; drafted, to be checked)
	["A Crumpled Up Note, dropped by foes inside Blackrock Depths"] = "꼬깃꼬깃한 쪽지, 검은바위 나락 내부의 적에게서 획득",
	-- Another dungeon's quest giver on a chain's step, named as several wings share it or by the one wing keeping it (2026-10-30; drafted, to be checked)
	["Ysida Harmon, inside Stratholme"] = "이시다 하몬, 스트라솔름 내부",
	["Ysida Harmon, inside Stratholme: Service Gate"] = "이시다 하몬, 스트라솔름: 공무용 입구 내부",
	["Shen'dralar Ancient, inside Dire Maul: Capital Gardens"] = "셴드랄라 고대인, 혈투의 전장: 수도 정원 내부",
	["Ancient Equine Spirit, inside Dire Maul: Capital Gardens"] = "고대 준마의 영혼, 혈투의 전장: 수도 정원 내부",
	-- Quests that start from an item: where the item is, without "Item start:" or "Use" (the Quests tab shows it on its own line) (2026-10-30; drafted, to be checked)
	["Abominable Head, inside Ruins of Lordaeron"] = "흉측한 머리, 로데론의 폐허 내부",
	["Bloodied Insignia, inside Ruins of Lordaeron"] = "피투성이 휘장, 로데론의 폐허 내부",
	["Crest of Lordaeron, inside Ruins of Lordaeron"] = "로데론의 문장, 로데론의 폐허 내부",
	["Garona: A Study on Stealth and Treachery, inside Dire Maul"] = "가로나: 은신과 기만에 대한 연구, 혈투의 전장 내부",
	["Codex of Defense, inside Dire Maul"] = "방어의 고서, 혈투의 전장 내부",
	["The Arcanist's Cookbook, inside Dire Maul"] = "신비술사의 요리책, 혈투의 전장 내부",
	["The Light and How to Swing It, inside Dire Maul"] = "빛과 정의에 관하여, 혈투의 전장 내부",
	["Harnessing Shadows, inside Dire Maul"] = "지배의 그림자, 혈투의 전장 내부",
	["The Greatest Race of Hunters, inside Dire Maul"] = "사냥꾼의 위대한 혈통, 혈투의 전장 내부",
	["Holy Bologna: What the Light Won't Tell You, inside Dire Maul"] = "성스러운 볼로냐: 빛이 알려주지 않는 것들, 혈투의 전장 내부",
	["Frost Shock and You, inside Dire Maul"] = "냉기 충격과 주술, 혈투의 전장 내부",
	["The Emerald Dream, inside Dire Maul"] = "에메랄드의 꿈, 혈투의 전장 내부",
	["Nostro's Compendium of Dragon Slaying, inside Dire Maul"] = "노스트로의 용사냥 개론, 혈투의 전장 내부",
	["An Unsent Letter, looted from Edwin VanCleef"] = "부치지 않은 편지, 에드윈 밴클리프에게서 획득",
	["Glowing Shard, dropped by Mutanus the Devourer"] = "빛나는 조각, 걸신들린 무타누스에게서 획득",
	["Damp Note, dropped by Blackfathom Tide Priestesses"] = "축축한 쪽지, 검은심연의 바다여사제에게서 획득",
	["Grime-Encrusted Ring, dropped by Dark Iron Agents inside Gnomeregan"] = "꼬질꼬질한 반지, 놈리건 내부의 검은무쇠단 첩보원에게서 획득",
	["Shattered Necklace, dropped by the Shadowforge dwarves and Stonevault troggs around Uldaman"] = "부서진 목걸이, 울다만 일대의 어둠괴철로단 드워프와 바위동굴일족 트로그에게서 획득",
	["Essence of Eranikus, dropped by the Shade of Eranikus inside the dungeon"] = "에라니쿠스의 정수, 던전 내부의 에라니쿠스의 사령에게서 획득",
	-- Blackrock Depths and the Temple of Atal'Hakkar: objectives that say what to do, quest notes (the Relic Coffer Key, the recipe's droppers, what follows Jail Break! and the temple's quests outside), Watchman Doomgrip and Hurley Blackbreath before you go, and the Shadowforge Key's and the Avatar of Hakkar's notes reworded (2026-10-30; drafted, to be checked)
	["Franclorn Forgewright's ghost, in Blackrock Mountain, gives Dark Iron Legacy; you can see him only when you are dead. Inside, kill Fineous Darkvire for the great hammer {item:10999:Ironfel}, and place it on the Monument of Franclorn Forgewright at the Shrine of Thaurissan. That gives the {item:11000:Shadowforge Key}. Franclorn calls it the master key. What it opens is not yet checked on Forever."] = "검은바위 산에 있는 프랑클론 포지라이트의 유령이 '검은무쇠단 유물'을 줍니다. 그는 죽은 상태에서만 보입니다. 던전 안에서 파이너스 다크바이어를 처치해 거대한 망치 {item:10999:Ironfel}을 얻고, 타우릿산의 제단에 있는 프랑클론 포지라이트의 기념비에 놓으십시오. 그러면 {item:11000:Shadowforge Key}를 받습니다. 프랑클론은 이것을 마스터 열쇠라고 부릅니다. 무엇을 여는지는 Forever에서 아직 확인되지 않았습니다.",
	["Yeh'kinya in Tanaris gives The God Hakkar after The Ancient Egg, and hands you the {item:10465:Egg of Hakkar}. Fill it with the {item:10663:Essence of Hakkar}, which the Shade of Hakkar drops in the temple, and take the {item:10662:Filled Egg of Hakkar} back to Yeh'kinya. In the original game, you used the egg at the Altar of Hakkar: Hakkar's guards came, their blood put out the Eternal Flames, and then the Avatar of Hakkar came. This is not yet checked on Forever."] = "타나리스의 예킨야가 '고대의 알'을 마친 뒤 '학카르 신'을 주며 {item:10465:Egg of Hakkar}을 건네줍니다. 사원에서 학카르의 망령이 떨어뜨리는 {item:10663:Essence of Hakkar}로 알을 채운 뒤 {item:10662:Filled Egg of Hakkar}을 예킨야에게 가져가십시오. 원래 게임에서는 학카르 제단에서 알을 사용하면 학카르의 수호병이 나타났고, 그들의 피로 영원의 불꽃을 끄면 학카르의 화신이 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Give the Spectral Chalice 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars."] = "유령의 성배에 별 루비 2개, 금 주괴 20개, 진은 주괴 10개를 바치십시오.",
	["Kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen in Blackrock Depths, then return to Warlord Goretooth in Kargath."] = "검은바위 나락에서 성난모루 경비병 15명, 성난모루 간수 10명, 성난모루 보병 5명을 처치한 뒤 카르가스의 장군 고어투스에게 돌아가십시오.",
	["Kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers in Blackrock Depths, then return to Warlord Goretooth in Kargath."] = "검은바위 나락에서 성난모루 의무병 10명, 성난모루 병사 10명, 성난모루 장교 10명을 처치한 뒤 카르가스의 장군 고어투스에게 돌아가십시오.",
	["Kill Bael'Gar in Blackrock Depths and use the Altered Black Dragonflight Molt on his remains. Bring the Encased Fiery Essence back to Cyrus Therepentous."] = "검은바위 나락에서 밸가르를 처치하고 그 잔해에 변형된 검은용군단 허물을 사용하십시오. 봉인된 불타는 정수를 키루스 테레펜터스에게 가져가십시오.",
	["Bring back Marshal Windsor's Lost Information. He believes Golem Lord Argelmach and General Angerforge hold it."] = "치안대장 윈저의 잃어버린 단서를 되찾으십시오. 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 그것을 가지고 있다고 믿습니다.",
	["Needs a Relic Coffer Key. Many foes in Blackrock Depths drop it."] = "유물 상자 열쇠가 필요합니다. 검은바위 나락의 많은 적이 떨어뜨립니다.",
	["Hurley Blackbreath and his Blackbreath Cronies drop the recipe."] = "헐레이 블랙브레스와 블랙브레스 패거리가 제조법을 떨어뜨립니다.",
	["Then Marshal Maxwell gives Stormwind Rendezvous: meet Marshal Windsor at the gates of Stormwind City. The chain goes on to the Onyxia attunement, which Upper Blackrock Spire and Onyxia's Lair show."] = "그 다음 치안대장 맥스웰이 '스톰윈드 회합'을 줍니다. 스톰윈드 성문에서 치안대장 윈저를 만나십시오. 이 연계 퀘스트는 오닉시아 입장 조율로 이어지며, 검은바위 첨탑 상층과 오닉시아의 둥지에서 볼 수 있습니다.",
	["Watchman Doomgrip, a hidden boss"] = "보초 둠그립, 숨겨진 우두머리",
	["Maxwort Uberglint in the Burning Steppes gives The Heart of the Mountain. It needs a {item:11078:Relic Coffer Key}, which many foes in the Depths drop. In the original game, the keys opened the twelve Relic Coffers in the vault. Once all twelve were open, Watchman Doomgrip came out, and the Heart of the Mountain was in the safe behind him. This is not yet checked on Forever."] = "불타는 평원의 맥스워트 우버글린트가 '산의 정수'를 줍니다. 이 퀘스트에는 {item:11078:Relic Coffer Key}가 필요하며, 나락의 많은 적이 떨어뜨립니다. 원래 게임에서는 이 열쇠로 금고의 유물 상자 열두 개를 열었습니다. 열두 개를 모두 열면 보초 둠그립이 나타났고, 산의 정수는 그 뒤의 금고에 있었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Hurley Blackbreath, a hidden boss"] = "헐레이 블랙브레스, 숨겨진 우두머리",
	["Ragnar Thunderbrew in Kharanos gives Hurley Blackbreath. Hurley and his Blackbreath Cronies drop the {item:11312:Lost Thunderbrew Recipe}. In the original game, they came out when the kegs of Thunderbrew Lager by the Grim Guzzler were broken. This is not yet checked on Forever."] = "카라노스의 라그나르 썬더브루가 '헐레이 블랙브레스'를 줍니다. 헐레이와 블랙브레스 패거리가 {item:11312:Lost Thunderbrew Recipe}을 떨어뜨립니다. 원래 게임에서는 험상궂은 주정뱅이 선술집 옆의 썬더브루 라거 술통을 부수면 그들이 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Shadowmage Vivian Lagrave in Kargath gives Lost Thunderbrew Recipe. Hurley Blackbreath and his Blackbreath Cronies drop the {item:11312:Lost Thunderbrew Recipe}. In the original game, they came out when the kegs of Thunderbrew Lager by the Grim Guzzler were broken. This is not yet checked on Forever."] = "카르가스의 어둠마법사 비비안 라그레이브가 '잃어버린 썬더브루 제조법'을 줍니다. 헐레이 블랙브레스와 블랙브레스 패거리가 {item:11312:Lost Thunderbrew Recipe}을 떨어뜨립니다. 원래 게임에서는 험상궂은 주정뱅이 선술집 옆의 썬더브루 라거 술통을 부수면 그들이 나타났습니다. Forever에서는 아직 확인되지 않았습니다.",
	["After this, The Essence of Eranikus goes on outside: take the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. He then gives In Eranikus' Own Words, which sends you to Winterspring."] = "그 후 '에라니쿠스의 정수'는 던전 밖에서 이어집니다. 속박된 에라니쿠스의 정수를 슬픔의 늪에 있는 이타리우스에게 가져가십시오. 그러면 이타리우스가 '에라니쿠스의 이야기'를 주며, 이 퀘스트는 여명의 설원으로 보냅니다.",
	["After this, Prospector Ironboot in Tanaris gives The Lost Tablets of Mosh'aru, which leads to The Final Tablets in Lower Blackrock Spire."] = "그 후 타나리스의 발굴조사단장 아이언부트가 '모쉬아루의 잃어버린 서판'을 주며, 이 퀘스트는 검은바위 첨탑 하층의 '마지막 서판'으로 이어집니다.",
	["Then the Forest Wisp gives Tyrande and Remulos, which sends you to Keeper Remulos in Moonglade. The chain goes on from there."] = "그 다음 숲 위습이 '티란데와 레물로스'를 주며, 이 퀘스트는 달의 숲의 수호자 레물로스에게 보냅니다. 연계 퀘스트는 거기서 이어집니다.",
	-- Razorfen Kraul and the Scarlet Monastery: where Lonebrow's Journal lies, and Journey to the Marsh's Horde givers (2026-10-30; drafted, to be checked)
	["Henrig Lonebrow's Journal"] = "헨릭 론브로우의 일지",
	["Henrig Lonebrow's Journal, Thousand Needles"] = "헨릭 론브로우의 일지, 버섯구름 봉우리",
	["Ursyn Ghull"] = "우르신 굴",
	["Ursyn Ghull, Thunder Bluff"] = "우르신 굴, 썬더 블러프",
	["Also given by Anastasia Hartwell (Undercity) and Deino (Orgrimmar)."] = "아나스타샤 하트웰(언더시티)과 다이노(오그리마)에게서도 받을 수 있습니다.",
	-- The Valthalak amulet's and the temple's chain steps (the deep audit's plan step 2): Dead Man's Plea's note, the side's and the lead-ins' step names, and the new steps' givers (2026-10-30; drafted, to be checked)
	["Also needs your class's An Earnest Proposition, before A Supernatural Device, and your class's Just Compensation, before In Search of Anthion. Anthion Harmon is a ghost: to see him, use the Extra-Dimensional Ghost Revealer, which Return to Deliana or Return to Mokvar gives you, at the entrance to Stratholme."] = "자기 직업의 '진지한 제안'('초자연적인 장치' 앞)과 자기 직업의 '정당한 보상'('안시온을 찾아서' 앞)도 필요합니다. 안시온 하몬은 유령입니다. 그를 보려면 '델리아나에게 돌아가기' 또는 '모크바르에게 돌아가기'에서 받는 차원 너머 유령 탐지기를 스트라솔름 입구에서 사용하십시오.",
	["A Supernatural Device"] = "초자연적인 장치",
	["Return to Deliana"] = "델리아나에게 돌아가기",
	["Return to Mokvar"] = "모크바르에게 돌아가기",
	["In Search of Anthion"] = "안시온을 찾아서",
	["Elemental Mastery"] = "원소의 지배",
	["Mastering the Elements"] = "원소 다스리기",
	["An Imp's Request"] = "임프의 부탁",
	["Hot and Itchy"] = "뜨거운 소유욕",
	["Beram Skychaser, Thunder Bluff"] = "베람 스카이체이서, 썬더 블러프",
	["Beram Skychaser"] = "베람 스카이체이서",
	["Also given by Sagorne Creststrider (Orgrimmar)."] = "사고른 크레스트스트라이더(오그리마)에게서도 받을 수 있습니다.",
	["Demisette Cloyce, Stormwind City"] = "데미세트 클로이스, 스톰윈드",
	["Demisette Cloyce"] = "데미세트 클로이스",
	["Also given by Briarthorn (Ironforge)."] = "브라이어손(아이언포지)에게서도 받을 수 있습니다.",
	["Zevrost, Orgrimmar"] = "제브로스트, 오그리마",
	["Zevrost"] = "제브로스트",
	["Also given by Kaal Soulreaper (Undercity)."] = "칼 소울리퍼(언더시티)에게서도 받을 수 있습니다.",
	["Mux Manascrambler, Tanaris"] = "먹스 마나스크램블러, 타나리스",
	["Mux Manascrambler"] = "먹스 마나스크램블러",
	["Deliana"] = "델리아나",
	["Mokvar"] = "모크바르",
	-- Dire Maul and Scholomance (the deep audit's plan step 3): the objectives cut short (The Madness Within, The Forging of Quel'Serrar, Kirtonos the Herald), the lorekeepers in Dire Maul, the spells two quests teach, The Last Barov, Kormok's note before you go and Volume III (2026-10-30; drafted, to be checked)
	["Get Onyxia to breathe fire on the Unfired Ancient Blade, then pick up the Heated Ancient Blade before it cools. Kill Onyxia, drive the blade into her corpse, and return to Lorekeeper Lydros."] = "오닉시아가 달궈지지 않은 고대의 검에 화염을 내뿜게 한 후, 식기 전에 달궈진 고대의 검을 집으십시오. 오닉시아를 처치하고 그 시체에 검을 꽂은 후 현자 리드로스에게 돌아가야 합니다.",
	["Kill the guardians at the five pylons that power the Prison of Immol'thar, and its force field goes down. Then kill Immol'thar inside, and Prince Tortheldrin in the Athenaeum. Return to the Shen'dralar Ancient in the courtyard."] = "이몰타르의 감옥에 힘을 주는 다섯 수정탑의 수호자를 처치하면 보호막이 사라집니다. 그런 다음 안에 있는 이몰타르와 도서관의 왕자 토르텔드린을 처치하십시오. 뜰에 있는 셴드랄라 고대인에게 돌아가야 합니다.",
	["Take the Blood of Innocents to Scholomance and place it in the brazier on the porch to call Kirtonos. Kill him and return to Eva Sarkhoff."] = "무고한 자의 피를 스칼로맨스로 가져가 현관의 화로에 놓아 키르토노스를 부르십시오. 그를 처치한 후 에바 사크호프에게 돌아가야 합니다.",
	["Lorekeeper Kildrath, inside Dire Maul"] = "현자 킬드라스, 혈투의 전장 내부",
	["Lorekeeper Javon, inside Dire Maul"] = "현자 야본, 혈투의 전장 내부",
	["Lorekeeper Mykos, inside Dire Maul"] = "현자 마이코스, 혈투의 전장 내부",
	["Teaches Conjure Water."] = "물 창조를 배웁니다.",
	["The summoning is done in the Prison of Immol'thar. Teaches Summon Dreadsteed."] = "소환은 이몰타르의 감옥에서 진행합니다. 공포마 소환을 배웁니다.",
	["Leads to The Last Barov, done outside the dungeon."] = "'최후의 상속자'로 이어지며, 던전 밖에서 진행합니다.",
	["Use the {item:22052:Brazier of Beckoning} to call his spirit. Bodley, inside Blackrock Mountain, gives it with the Kormok versions of The Left Piece and The Right Piece of Lord Valthalak's Amulet."] = "{item:22052:Brazier of Beckoning}을 사용해 그의 영혼을 부르십시오. 검은바위 산 안의 보들리가 '군주 발타라크의 아뮬렛 왼쪽 조각'과 '오른쪽 조각' 퀘스트의 코르모크 판과 함께 이것을 줍니다.",
	["Enchanted Thorium Platemail: Volume III"] = "마력깃든 토륨 갑옷 III",
	["Enchanted Thorium Platemail: Volume III, bound from its two halves"] = "마력깃든 토륨 갑옷 III, 상권과 하권을 합쳐 만든 책",
	["Combine the Top Half (Urok Doomhowl, Lower Blackrock Spire) and the Bottom Half (Black Guard Swordsmith, Stratholme) of Advanced Armorsmithing: Volume III."] = "고급 방어구제작: III 상권(우로크 둠하울, 검은바위 첨탑 하층)과 고급 방어구제작: III 하권(검은호위대 검제작자, 스트라솔름)을 합쳐야 합니다.",
	-- Blackrock Spire (the deep audit's plan step 8): who can do The Demon Forge and Lorax's Tale, Hot Fiery Death without a class limit and with its follow-up, what follows Pip Quickwit, Egg Collection and Return to Bodley outside, and the Horde's Onyxia text naming Upper Blackrock Spire (2026-10-31; drafted, to be checked)
	["For warrior, paladin and shaman blacksmiths with a skill of 270."] = "대장기술 숙련도 270 이상의 전사, 성기사, 주술사 대장장이 전용.",
	["For warrior, paladin and shaman blacksmiths with a skill of 270. Lorax's Tale comes first."] = "대장기술 숙련도 270 이상의 전사, 성기사, 주술사 대장장이 전용. '로락스의 이야기'를 먼저 해야 합니다.",
	["For blacksmiths with a skill of 270. The remains and the gauntlets are by a lava flow, down a tunnel behind the orc tents at the start of the long orc hall before the spiders. Malyfous then offers Fiery Plate Gauntlets, which gives the gauntlets and their plans."] = "대장기술 숙련도 270 이상의 대장장이 전용. 해골과 건틀릿은 거미 구역 앞 긴 오크 전당이 시작되는 곳, 오크 천막 뒤편 터널을 따라 내려간 용암 줄기 옆에 있습니다. 그 뒤 말리퍼스가 '불타는 판금 건틀릿'을 줍니다. 이 퀘스트는 건틀릿과 그 도면을 줍니다.",
	["Then Malyfous's Catalogue, in Everlook, offers Cap of the Scarlet Savant, Leggings of Arcana and Breastplate of Bloodthirst. Each needs a Pristine Hide of the Beast."] = "그 뒤 눈망루 마을에 있는 말리퍼스의 목록에서 '붉은십자군 학자의 모자', '비전의 다리보호구', '피의 갈증 흉갑'을 받을 수 있습니다. 각각 야수의 완벽한 가죽이 필요합니다.",
	["Tinkee then sends you to Leonid Barthalomew in the Eastern Plaguelands. The chain goes on to Dawn's Gambit in Scholomance."] = "그 뒤 팅키가 동부 역병지대의 리어니드 바돌로매에게 보냅니다. 이 퀘스트 줄기는 스칼로맨스의 '여명의 계략'으로 이어집니다.",
	-- Stratholme (the deep audit's plan step 9): the weaponsmith notes on Sweet Serenity, Corruption and Snakestone of the Shadow Huntress, The Medallion of Faith repeatable, The Restless Souls' count, what follows Of Love and Family and Menethil's Gift (2026-10-31; drafted, to be checked)
	["For weaponsmiths with a blacksmithing skill of 250."] = "대장기술 숙련도 250 이상의 무기제작자 전용.",
	["For weaponsmiths with a blacksmithing skill of 250. The Swordsmith appears near Baroness Anastari when you pick up the blacksmithing plans there."] = "대장기술 숙련도 250 이상의 무기제작자 전용. 남작부인 아나스타리 근처에서 대장기술 도면을 집으면 검제작자가 나타납니다.",
	["Repeatable. Malor's Strongbox is on the Scarlet side of Stratholme."] = "반복 가능. 말로의 금고는 스트라솔름의 붉은십자군 구역에 있습니다.",
	["Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan."] = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오! 원혼 15개를 해방한 후 에간에게 돌아가야 합니다.",
	["Then Tirion Fordring gives Find Myranda, which sends you to Myranda the Hag in the Western Plaguelands."] = "그 뒤 티리온 폴드링이 '미란다 찾기'를 줍니다. 서부 역병지대의 노파 미란다에게 가야 합니다.",
	["Then Leonid gives Soulbound Keepsake, which sends you back to Magistrate Marduke in Caer Darrow. The chain ends with The Lich, Ras Frostwhisper, in Scholomance."] = "그 뒤 리어니드가 '영혼이 씌인 유품'을 줍니다. 카엘 다로우의 집정관 마르듀크에게 돌아가야 합니다. 이 퀘스트 줄기는 스칼로맨스의 '리치, 라스 프로스트위스퍼'로 끝납니다.",
	-- Ragefire Chasm, Wailing Caverns and the Stockade (the deep audit's plan step 4): Hidden Enemies' note (the Insignia), The Glowing Shard's note, Mutanus the Devourer before you go (2026-11-03; drafted, to be checked).
	-- Hidden Enemies' last step and In Nightmares are listed again (the owner's rule of 2026-11-03), so the first note keeps only the Insignia and the second is the one it had before (2026-11-03; drafted, to be checked)
	["Needs the two earlier Hidden Enemies steps from Thrall. The first asks for a Lieutenant's Insignia, dropped by the Burning Blade Fanatics and Apprentices in Durotar."] = "스랄에게서 받는 '내부의 배신자' 앞 단계 둘을 먼저 마쳐야 합니다. 첫 단계에는 부관의 휘장이 필요하며, 듀로타의 불타는 칼날단 광신도와 수습생이 떨어뜨립니다.",
	["The quest itself gives no item; its follow-up, In Nightmares, does."] = "이 퀘스트 자체는 아이템을 주지 않으며, 후속 퀘스트인 악몽에서 아이템을 받습니다.",
	["Mutanus the Devourer, a hidden boss"] = "걸신들린 무타누스, 숨겨진 우두머리",
	["Kill the four Fanglords: Lady Anacondra, Lord Cobrahn, Lord Pythas and Lord Serpentis. Then talk to the Disciple of Naralex at the entrance and escort him to Naralex. Mutanus comes at the end of the ritual. He drops the {item:10441:Glowing Shard}, which starts the quest The Glowing Shard."] = "송곳니의 드루이드 우두머리 넷을 처치하십시오: 여군주 아나콘드라, 군주 코브란, 군주 피타스, 군주 서펜티스. 그런 다음 입구에 있는 나랄렉스의 신도와 대화하고 나랄렉스에게까지 호위하십시오. 의식이 끝날 때 무타누스가 나타납니다. 무타누스는 {item:10441:Glowing Shard}을 떨어뜨리며, 이것으로 '빛나는 조각' 퀘스트가 시작됩니다.",
	-- The owner's calls of 2026-11-03: The Test of Righteousness listed as the step done here (its objective), Grubbis before you go, and the Drowned City's two Horde quests (their names and objectives) (2026-11-03; drafted, to be checked)
	["Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge."] = "조던의 무기 설계도를 이용해 흰돌참나무 재목, 베일러의 정제된 광석 상자, 조던의 대장장이 망치, 코르석을 찾아 아이언포지의 조던 스틸웰에게 가져가야 합니다.",
	["Grubbis, a hidden boss"] = "그루비스, 숨겨진 우두머리",
	["The Drowned City"] = "가라앉은 도시",
	["The Only Good Brinescale..."] = "좋은 브라인스케일은 오직...",
	["Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."] = "가죽과 숯으로 가라앉은 도시에 있는 석판들의 탁본을 떠야 합니다.",
	["Slay Var'Taka in the Drowned City."] = "가라앉은 도시에서 바르타카를 처치해야 합니다.",
	-- The owner's calls of 2026-11-03, step O2: Collection of Goods at Stratholme (its objective, note and giver), and the Valthalak amulet's class steps as class quests (their names and objectives; the set's pieces named by slot, as their names in each language are not known here) (2026-11-03; drafted, to be checked)
	["Grimand Elmore, Stormwind City"] = "그리만트 엘모어, 스톰윈드",
	["Grimand Elmore"] = "그리만트 엘모어",
	["Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."] = "룬매듭 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 5병, 150골드를 스톰윈드 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다.",
	["An Earnest Proposition"] = "진지한 제안",
	["Just Compensation"] = "정당한 보상",
	["Anthion's Parting Words"] = "안시온의 작별 인사",
	["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge."] = "여명의 설원 혈액 표본 15개와 20골드, 자기 직업 세트의 손목 방어구를 아이언포지에 있는 델리아나에게 가져가야 합니다.",
	["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge."] = "여명의 설원 혈액 표본 15개와 20골드, 자기 직업 세트의 손목 방어구를 아이언포지에 있는 델리아나에게 가져가야 합니다.",
