	["Return to Mokvar in Orgrimmar with a set of Boots of Valor, Legplates of Valor and Spaulders of Valor."] = "자기 직업 세트의 장화, 다리 방어구, 어깨 방어구를 가지고 오그리마에 있는 모크바르에게 돌아가야 합니다.",
	-- The owner's calls of 2026-11-03, step O3: each Dire Maul quest in the wing where it is done, so East's page names Capital Gardens for the lorekeepers and Falrin (North's keeps "inside Dire Maul"), West's names Gordok Commons for Captain Kromcrush, and notes say where the rest is (the ogres, Telmius's remains) (2026-11-03; drafted, to be checked)
	["Lorekeeper Lydros, inside Dire Maul: Capital Gardens"] = "현자 리드로스, 혈투의 전장: 수도 정원 내부",
	["Lorekeeper Kildrath, inside Dire Maul: Capital Gardens"] = "현자 킬드라스, 혈투의 전장: 수도 정원 내부",
	["Lorekeeper Javon, inside Dire Maul: Capital Gardens"] = "현자 야본, 혈투의 전장: 수도 정원 내부",
	["Lorekeeper Mykos, inside Dire Maul: Capital Gardens"] = "현자 마이코스, 혈투의 전장: 수도 정원 내부",
	["Falrin Treeshaper, inside Dire Maul: Capital Gardens"] = "팔린 트리셰이퍼, 혈투의 전장: 수도 정원 내부",
	["Captain Kromcrush, inside Dire Maul: Gordok Commons"] = "대장 크롬크러쉬, 혈투의 전장: 고르독 광장 내부",
	["Dire Maul's ogres are in Gordok Commons. Lower Blackrock Spire's Spirestone ogres drop the warbeads too."] = "혈투의 전장의 오우거는 고르독 광장에 있습니다. 검은바위 첨탑 하층의 뾰족바위일족 오우거도 전투 목걸이를 떨어뜨립니다.",
	["Telmius Dreamseeker's remains are in the Athenaeum, in Capital Gardens."] = "텔미우스 드림시커의 유해는 수도 정원의 도서관에 있습니다.",
	-- And on North's page, which names no wing for the Athenaeum (2026-11-03; drafted, to be checked)
	["Telmius Dreamseeker's remains are in the Athenaeum, inside Dire Maul."] = "텔미우스 드림시커의 유해는 혈투의 전장 내부의 도서관에 있습니다.",
	-- Quests added on 2026-11-03 (the owner's calls on which quests and chains belong): Furen's Armor and Brutal Hauberk on Razorfen Kraul, Mana Surges and Celestial Power on Uldaman, the Alliance's Seeking the Kor Gem on Blackfathom Deeps, Saving the Best for Last on Upper Blackrock Spire and Scholomance after Back to the Beginning, and the lead-ins to Gahz'rilla, Researching the Corruption and Underground Assault as rows; The Test of Righteousness's Blackfathom note without Thundris (2026-11-03; drafted, to be checked)
	["Spirit of Lord Valthalak, inside Upper Blackrock Spire"] = "군주 발타라크의 영혼, 검은바위 첨탑 상층 내부",
	["Furen's Armor"] = "푸렌의 갑옷",
	["Brutal Hauberk"] = "투사의 사슬 갑옷",
	["Mana Surges"] = "마나 굽이",
	["Celestial Power"] = "천상의 힘",
	["Saving the Best for Last"] = "최고는 마지막에",
	["Back to the Beginning"] = "처음으로 돌아가서",
	["The Brassbolts Brothers"] = "브라스볼츠 형제",
	["The Corruption Abroad"] = "먼 곳에 퍼진 타락",
	["Speak with Shoni"] = "쇼니와의 대화",
	["Talk to Furen Longbeard in Stormwind to get your armour."] = "스톰윈드의 푸렌 롱비어드와 대화하여 갑옷을 받아야 합니다.",
	["Talk to Thun'grim Firegaze in the Barrens to get your armour."] = "불모의 땅의 툰그림 파이어게이즈와 대화하여 갑옷을 받아야 합니다.",
	["Kill 12 Mana Surges in the allowed time limit."] = "제한 시간 안에 마나 굽이 12마리를 처치해야 합니다.",
	["Talk to Tabetha in Dustwallow Marsh for your reward."] = "먼지진흙 습지대의 타베사와 대화하여 보상을 받아야 합니다.",
	["Bring a Kor Gem to Thundris Windweaver in Darkshore."] = "어둠의 해안의 툰드리스 윈드위버에게 코르석을 가져가야 합니다.",
	["Speak with Wizzle Brassbolts in the Shimmering Flats."] = "소금 평원의 위즐 브라스볼츠와 대화해야 합니다.",
	["Travel to Gershala Nightwhisper in Auberdine."] = "아우버다인의 게르샬라 나이트위스퍼에게 가야 합니다.",
	["Speak with Shoni the Shilent in Stormwind."] = "스톰윈드의 소리없는 쇼니와 대화해야 합니다.",
	["Speak with Deliana at The High Seat in Ironforge."] = "아이언포지 왕좌의 전당에 있는 델리아나와 대화해야 합니다.",
	["Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom."] = "오그리마 지혜의 골짜기에 있는 그롬마쉬 요새의 모크바르와 대화해야 합니다.",
	["Give Deliana your Wildheart Cowl and Wildheart Vest."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Beaststalker's Cap and Beaststalker's Tunic."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Magister's Crown and Magister's Robes."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Lightforge Helm and Lightforge Breastplate."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Devout Crown and Devout Robe."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Shadowcraft Cap and Shadowcraft Tunic."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Dreadmist Mask and Dreadmist Robe."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Deliana your Helm of Valor and Breastplate of Valor."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 델리아나에게 주어야 합니다.",
	["Give Mokvar your Wildheart Cowl and Wildheart Vest."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Beaststalker's Cap and Beaststalker's Tunic."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Magister's Crown and Magister's Robes."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Devout Crown and Devout Robe."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Shadowcraft Cap and Shadowcraft Tunic."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Dreadmist Mask and Dreadmist Robe."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Helm of Valor and Breastplate of Valor."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Give Mokvar your Coif of Elements and Vest of Elements."] = "자기 직업 세트의 머리 방어구와 가슴 방어구를 모크바르에게 주어야 합니다.",
	["Thundris Windweaver, Auberdine, Darkshore"] = "툰드리스 윈드위버, 어둠의 해안 아우버다인",
	["Argos Nightwhisper, Stormwind City"] = "아르고스 나이트위스퍼, 스톰윈드",
	["Thundris Windweaver"] = "툰드리스 윈드위버",
	["Klockmort Spannerspan"] = "클락몰트 스패너스판",
	["Wizzle Brassbolts"] = "위즐 브라스볼츠",
	["Argos Nightwhisper"] = "아르고스 나이트위스퍼",
	["Gnoarn"] = "노아른",
	["Shoni the Shilent"] = "소리없는 쇼니",
	["Bodley"] = "보들리",
	["The Mana Surges come out of a rift Tabetha opens by her house. You have 10 minutes."] = "마나 굽이는 타베사가 집 옆에 여는 균열에서 나옵니다. 제한 시간은 10분입니다.",
	["Optional: it leads to Gahz'rilla."] = "선택 사항: '가즈릴라'로 이어집니다.",
	["Optional: it leads to Researching the Corruption."] = "선택 사항: '타락에 대한 연구'로 이어집니다.",
	["Optional: it leads to Underground Assault."] = "선택 사항: '지하 공격'으로 이어집니다.",
	["General Drakkisath drops the chest here. Darkmaster Gandling in Scholomance drops the helm."] = "가슴 방어구는 이곳의 사령관 드라키사스가 떨어뜨립니다. 머리 방어구는 스칼로맨스의 암흑스승 간들링이 떨어뜨립니다.",
	["Darkmaster Gandling drops the helm here. General Drakkisath in Upper Blackrock Spire drops the chest."] = "머리 방어구는 이곳의 암흑스승 간들링이 떨어뜨립니다. 가슴 방어구는 검은바위 첨탑 상층의 사령관 드라키사스가 떨어뜨립니다.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: the Corrupted Kor Gem, from the Blackfathom Sea Witches inside or the Tide Priestesses and Oracles at the entrance in Ashenvale. The rest: Whitestone Oak Lumber in the Deadmines, Jordan's Smithing Hammer in Shadowfang Keep and Jordan's ore shipment in Loch Modan."] = "인간과 드워프 성기사의 퀘스트로, 여러 곳에서 재료를 모아야 합니다. 이곳에서 얻는 재료는 부정한 코르석으로, 던전 안의 검은심연의 바다마녀나 잿빛 골짜기에 있는 입구의 검은심연의 바다여사제와 검은심연의 예언자에게서 획득합니다. 나머지 재료는 죽음의 폐광의 흰돌참나무 재목, 그림자송곳니 성채의 조던의 대장장이 망치, 모단 호수의 조던의 광석 상자입니다.",
	-- Notes that name where a chain goes next, on another page or outside (the owner's calls of 2026-11-03 on which quests and chains belong) (2026-11-03; drafted, to be checked)
	["Leads into a chain that carries on with Bazil Thredd and on to The Stockade Riots in the Stockade."] = "이후 바질 스레드로 이어지고, 스톰윈드 지하감옥의 '감옥 폭동'까지 이어지는 연계 퀘스트가 시작됩니다.",
	["Then Master Apothecary Faranell gives Hearts of Zeal, done in the Scarlet Monastery."] = "그 후 수석 연금술사 파라넬이 '열정의 증거'를 주며, 이 퀘스트는 붉은십자군 수도원에서 진행합니다.",
	["Then Theldurin the Lost gives To Ironforge for Yagyin's Digest (Alliance) or To the Undercity for Yagyin's Digest (Horde), a short chain outside."] = "그 후 실성한 텔두린이 '야긴의 요약서를 찾아 아이언포지로'(얼라이언스)나 '야긴의 요약서를 찾아 언더시티로'(호드)를 줍니다. 던전 밖에서 하는 짧은 연계 퀘스트입니다.",
	["Then High Explorer Magellas gives Portents of Uldum, which goes on to the gates of Uldum in Tanaris."] = "그 후 선임탐험가 마겔라스가 '울둠의 징조'를 주며, 이 퀘스트는 타나리스의 울둠 관문으로 이어집니다.",
	["Then Sage Truthseeker gives Portents of Uldum, which goes on to the gates of Uldum in Tanaris."] = "그 후 현자 트루스시커가 '울둠의 징조'를 주며, 이 퀘스트는 타나리스의 울둠 관문으로 이어집니다.",
	["For alchemists (skill 210), Ghak Healtouch then gives Badlands Reagent Run II, done in the Badlands."] = "연금술사(숙련도 210)에게는 그 후 가크 힐터치가 '황야의 땅에서 재료 찾기 II'를 주며, 이 퀘스트는 황야의 땅에서 진행합니다.",
	["Then Yeh'kinya gives The Ancient Egg, which leads to The God Hakkar in the Sunken Temple."] = "그 후 예킨야가 '고대의 알'을 주며, 이 퀘스트는 가라앉은 사원의 '학카르의 화신'으로 이어집니다.",
	["Then Thadius Grimshade gives The Divination, a chain that ends with Saving Sharpbeak in the Hinterlands."] = "그 후 샤디우스 그림섀이드가 '점술'을 주며, 이 연계 퀘스트는 동부 내륙지의 '날카로운부리 구출'로 끝납니다.",
	["Then Master Gadrin gives Summoning Shadra, done at Shadra'Alor in the Hinterlands."] = "그 후 장로 가드린이 '샤드라 소환'을 주며, 이 퀘스트는 동부 내륙지의 샤드라알로에서 진행합니다.",
	["Then Warlord Goretooth gives Eitrigg's Wisdom, which takes you to Orgrimmar. The chain goes on to For The Horde! in Upper Blackrock Spire, then to the Onyxia attunement."] = "그 후 장군 고어투스가 '아이트리그의 지혜'를 주며, 이 퀘스트는 오그리마로 보냅니다. 연계 퀘스트는 검은바위 첨탑 상층의 '호드를 위하여!'를 거쳐 오닉시아 입장 조율로 이어집니다.",
	["Then Marshal Maxwell gives General Drakkisath's Demise, done in Upper Blackrock Spire."] = "그 후 치안대장 맥스웰이 '사령관 드라키사스 처치'를 주며, 이 퀘스트는 검은바위 첨탑 상층에서 진행합니다.",
	["Then Bodley gives Mea Culpa, Lord Valthalak, done in Upper Blackrock Spire."] = "그 후 보들리가 '군주 발타라크여, 내 탓이오.'를 주며, 이 퀘스트는 검은바위 첨탑 상층에서 진행합니다.",
	["Then Haleh, in Winterspring, gives Wrath of the Blue Flight. The chain goes on to Jeziba in Andorhal, whose Catalogue of the Wayward offers Breastplate of the Chromatic Flight and Legplates of the Chromatic Defier. Each needs Gyth's Chromatic Carapace and 10 Brilliant Chromatic Scales from Upper Blackrock Spire."] = "그 후 여명의 설원의 헬레가 '푸른용군단의 분노'를 줍니다. 연계 퀘스트는 안도할의 제지바에게로 이어지며, 그곳의 '무법의 시대 일람'에서 '오색용군단 흉갑'과 '오색 도전자의 다리보호구'를 받을 수 있습니다. 각각 기스의 오색 껍질과 검은바위 첨탑 상층의 빛나는 오색 비늘 10개가 필요합니다.",
	["Then Duke Hydraxis gives The Molten Core, done in Molten Core."] = "그 후 군주 히드락시스가 '화산 심장부'를 주며, 이 퀘스트는 화산 심장부에서 진행합니다.",
	["Then Falrin Treeshaper gives The Challenge, done at the Ring of Law in Blackrock Depths."] = "그 후 팔린 트리셰이퍼가 '도전'을 주며, 이 퀘스트는 검은바위 나락의 법의 심판장에서 진행합니다.",
	["Then Lord Grayson Shadowbreaker gives The Divination Scryer. The chain ends with Judgment and Redemption in Scholomance."] = "그 후 그레이슨 섀도브레이커 경이 '예언의 탐지기'를 줍니다. 연계 퀘스트는 스칼로맨스의 '심판과 구원의 손길'로 끝납니다.",
	["Then Anthion Harmon gives Anthion's Strange Request. The chain goes on to Anthion's Old Friend in Dire Maul."] = "그 후 안시온 하몬이 '안시온의 이상한 부탁'을 줍니다. 연계 퀘스트는 혈투의 전장의 '안시온의 오랜 친구'로 이어집니다.",
	["Then Duke Nicholas Zverenhoff gives Above and Beyond, done at the Service Gate."] = "그 후 공작 니콜라스 즈바른호프가 '뛰어난 존재'를 주며, 이 퀘스트는 공무용 입구에서 진행합니다.",
	["Optional: it leads to Blackfathom Villainy."] = "선택 사항: '검은심연의 음모'로 이어집니다.",
	-- City of Dalaran: the Horde's Heart of Disruption names who starts the chain, as the Image of Archmage Modera gives the quest itself (2026-11-03; drafted, to be checked)
	["Magus Wordeen Voidglare in Tarren Mill starts the chain with Prison Break In and Key to the City. At the Lordamere Internment Camp, kill four traitors for their artifacts (they take 5 to 10 minutes to come back) and take the Grimy Key from the Warden's Footlocker, upstairs in the two-storey building. Blood in the Streets then leads through the north sewers to the Image of Archmage Modera. It gives the Dalaran Sewer Key, and Shrewd Negotiations follows, to Archmage Celindra. The mote drops from the Shade of the Archmage, the last boss."] = "타렌 밀농장의 학자 워딘 보이드글레어가 '감옥 습격'과 '도시로 통하는 열쇠'로 퀘스트 줄기를 시작합니다. 로다미어 포로수용소에서 배반자 넷을 처치해 유물을 얻고(다시 나타나기까지 5~10분 걸립니다), 2층 건물 위층에 있는 교도관의 사물함에서 더러운 열쇠를 꺼내십시오. 이어지는 '피로 물든 거리'는 북쪽 하수구를 지나 대마법사 모데라의 환영에게로 안내합니다. 이 퀘스트로 달라란 하수구 열쇠를 얻으며, 이어서 '기민한 협상'으로 대마법사 셀린드라에게 갑니다. 티끌은 마지막 우두머리인 대마법사의 망령이 떨어뜨립니다.",
	-- The Deadmines, Shadowfang Keep, Blackfathom Deeps and Gnomeregan (the deep audit's plan step 5): A Moon-Kissed Blade's Kor Gem and what follows it, Seeking the Kor Gem's link back, the Deadmines' chains before you go, The Orb of Soran'ruk's note, the lead-in notes, Rig Wars' level and the Sparklematic machines (2026-11-03; drafted, to be checked)
	["Bring Trevan Rol in the Sepulcher the Whitestone Oak Lumber, the Enchanted Silver Ingot and the Purified Kor Gem he needs."] = "공동묘지에 있는 트레반 롤에게 그가 필요로 하는 흰돌참나무 재목, 마법부여 은 주괴, 정화된 코르석을 가져가야 합니다.",
	["A paladin quest for the Forsaken. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The Purified Kor Gem comes from Seeking the Kor Gem, from Ulric Frostveil at Zoram'gar Outpost; its Corrupted Kor Gem drops in Blackfathom Deeps. Trevan then sends you to Ott, the weaponsmith in Tarren Mill (Hillsbrad Foothills), who forges the Moonsilver Blade. Lumina Windsinger then has you use it on Old Fire-Eye in southern Silverpine, for Wolfsbane."] = "포세이큰 성기사 퀘스트입니다. 이곳에서는 고블린 목공이 떨어뜨리는 흰돌참나무 재목을 얻습니다. 정화된 코르석은 조람가르 전초기지의 울릭 프로스트베일이 주는 '코르석을 찾아서' 퀘스트에서 얻으며, 그 퀘스트의 부정한 코르석은 검은심연 나락에서 얻습니다. 그다음 트레반이 힐스브래드 구릉지 타렌 밀농장의 무기제작자 오트에게 보내고, 오트가 달은빛 검을 벼립니다. 이어서 루미나 윈드싱어가 은빛소나무 숲 남쪽의 늙은 불눈에게 그 검을 쓰게 하며, 보상으로 늑대베기를 줍니다.",
	["A paladin quest for the Horde. The Corrupted Kor Gem drops from the Blackfathom Sea Witches inside, or the Tide Priestesses and Oracles at the entrance. The Purified Kor Gem it gives is for A Moon-Kissed Blade, which Trevan Rol in the Sepulcher takes with lumber from the Deadmines."] = "호드 성기사 퀘스트입니다. 부정한 코르석은 던전 안의 검은심연의 바다마녀나 입구의 검은심연의 바다여사제와 검은심연의 예언자에게서 획득합니다. 이 퀘스트로 받는 정화된 코르석은 '달빛이 깃든 검'에 쓰이며, 그 퀘스트는 죽음의 폐광에서 얻은 목재와 함께 공동묘지의 트레반 롤에게 완료합니다.",
	["The Defias Brotherhood chain"] = "'데피아즈단' 연계 퀘스트",
	["Alba Fairmoon's chain"] = "알바 페어문의 연계 퀘스트",
	["Alba Fairmoon at Sentinel Hill gives Destruction in Deadmines at the end of a chain of quests in Westfall and Stormwind. On the way, Sprite Jumpsprocket in the Dwarven District of Stormwind asks for 10 Coarse Dynamite: make it, trade for it or buy it at the auction house."] = "감시의 언덕의 알바 페어문이 서부 몰락지대와 스톰윈드를 오가는 연계 퀘스트 마지막에 '죽음의 폐광 파괴 작전'을 줍니다. 도중에 스톰윈드 드워프 지구의 스프라이트 점프스프로켓이 일반 다이너마이트 10개를 요구합니다. 직접 만들거나, 거래하거나, 경매장에서 사면 됩니다.",
	["A warlock quest. Here: the Large Soran'ruk Fragment, from Shadowfang Darksouls. The 3 small ones drop from Twilight Acolytes in Blackfathom Deeps."] = "흑마법사 퀘스트입니다. 이곳에서는 그림자송곳니일족 검은영혼에게서 큰 소랜루크 조각을 획득합니다. 작은 조각 3개는 검은심연 나락의 황혼의망치단 수행사제에게서 획득합니다.",
	["Sovik in Orgrimmar sends you to Scooty in Booty Bay. Take Rig Wars from Nogg first (from level 25); you need not finish it. Scooty's Gnomer-gooooone! gives the {item:9173:Goblin Transponder:1}. In the quest's own words, it lets you step on Scooty's pad in Booty Bay to go to Gnomeregan, and the pad there brings you back. This is not yet checked on Forever."] = "오그리마의 소빅이 무법항의 스쿠티에게 보냅니다. 먼저 노그에게서 '기술 전쟁'을 받아 두세요(25레벨부터). 완료할 필요는 없습니다. 스쿠티의 '놈리거어어어언!' 퀘스트가 {item:9173:Goblin Transponder:1}를 줍니다. 퀘스트 내용에 따르면 이것을 가지고 무법항에 있는 스쿠티의 발판에 올라서면 놈리건으로 가고, 그곳의 발판으로 돌아올 수 있습니다. Forever에서는 아직 확인되지 않았습니다.",
	["There are three Sparklematic 5200 machines, and each gives its own version of this quest. Once you do it at one, the other two close."] = "삐까뻔쩍세척기 5200은 세 대가 있으며, 각각 이 퀘스트의 다른 버전을 줍니다. 한 대에서 완료하면 나머지 두 대의 버전은 닫힙니다.",
	["Repeatable. Each go costs 3 silver. There are three Sparklematic 5200 machines, and each gives its own version of this quest. Once you do it at one, the other two close."] = "반복 가능. 한 번에 3실버가 듭니다. 삐까뻔쩍세척기 5200은 세 대가 있으며, 각각 이 퀘스트의 다른 버전을 줍니다. 한 대에서 완료하면 나머지 두 대의 버전은 닫힙니다.",
	-- The quest review of 2026-11-03: where a chain goes next split off its note (shown on the quest's own page alone), every lead-in row marked optional and the quests it leads to no longer naming it, Seeking the Kor Gem given only while The Test of Righteousness is in the log, the Deadmines' Defias Brotherhood chain before you go, and More Sparklematic Action's note (2026-11-03; drafted, to be checked)
	["Then Bodley gives Components of Importance. The amulet's quests go on in Blackrock Spire, Dire Maul, Scholomance and Stratholme."] = "그 후 보들리가 '중요한 요소'를 줍니다. 아뮬렛 퀘스트는 검은바위 첨탑, 혈투의 전장, 스칼로맨스, 스트라솔름에서 이어집니다.",
	["Then Bodley gives Final Preparations, which goes on in Blackrock Spire."] = "그 후 보들리가 '마지막 준비'를 주며, 이 퀘스트는 검은바위 첨탑에서 이어집니다.",
	["A step of the paladin's charger quests. The Stratholme Holy Water comes from supply crates inside Stratholme."] = "성기사 군마 퀘스트의 한 단계입니다. 스트라솔름 성수는 스트라솔름 안의 보급품 상자에서 나옵니다.",
	["Then Lord Grayson Shadowbreaker gives Ancient Equine Spirit, done in Dire Maul's Capital Gardens."] = "그 후 그레이슨 섀도브레이커 경이 '고대 준마의 영혼'을 주며, 이 퀘스트는 혈투의 전장 수도 정원에서 진행합니다.",
	["A step of the warlock's Dreadsteed quests."] = "흑마법사 공포마 퀘스트의 한 단계입니다.",
	["With Arcanite, it leads to Dreadsteed of Xoroth, done in Dire Maul's Capital Gardens."] = "'아케이나이트'와 함께 '소로스의 공포마'로 이어지며, 이 퀘스트는 혈투의 전장 수도 정원에서 진행합니다.",
	["For alchemists (skill 210), Jarkal Mossmeld then gives Badlands Reagent Run II, done in the Badlands."] = "연금술사(숙련도 210)에게는 그 후 자칼 모스멜드가 '황야의 땅에서 재료 찾기 II'를 주며, 이 퀘스트는 황야의 땅에서 진행합니다.",
	["Part of the chain The Unsent Letter starts, from Edwin VanCleef in the Deadmines."] = "죽음의 폐광의 에드윈 밴클리프에게서 얻는 '부치지 않은 편지'로 시작하는 연계 퀘스트의 일부입니다.",
	["Warden Thelwater then gives The Curious Visitor, which goes on in Stormwind."] = "그 후 교도소장 델워터가 '수상한 방문자'를 주며, 이 퀘스트는 스톰윈드에서 이어집니다.",
	["Techbot stands outside the instance, in Dun Morogh."] = "첨단로봇은 인스턴스 밖, 던 모로에 있습니다.",
	["A White Punch Card drops from mobs outside the instance; run it through Matrix Punchograph 3005-A (Train Depot, outside), 3005-B (the Dormitory), 3005-C (Electrocutioner 6000's platform) and 3005-D (lower Engineering Labs) to get the Prismatic Punch Card."] = "백색 천공 카드는 던전 밖의 몬스터에게서 획득합니다. 이 카드를 행렬 천공기록기 3005-A(바깥쪽 병참 보급창), 3005-B(거주 지구), 3005-C(기계화 문지기 6000의 발판), 3005-D(기계공학 연구소 아래층)에 차례로 넣어 오색 천공 카드를 얻으십시오.",
	["Optional: it leads to Hurley Blackbreath."] = "선택 사항: '헐레이 블랙브레스'로 이어집니다.",
	["Optional: it leads to Ribbly Screwspigot."] = "선택 사항: '리블리 스크류스피곳'으로 이어집니다.",
	["Optional: it leads to Lost Thunderbrew Recipe."] = "선택 사항: '잃어버린 썬더브루 제조법'으로 이어집니다.",
	["Optional: it leads to Doomrigger's Clasp."] = "선택 사항: '파멸의 기념물'로 이어집니다.",
	["Optional: it leads to The Darkstone Tablet."] = "선택 사항: '다크스톤 서판'으로 이어집니다.",
	["Optional: it leads to Egg Freezing."] = "선택 사항: '알껍질 냉동'으로 이어집니다.",
	["Optional: it leads to Save Techbot's Brain!"] = "선택 사항: '고장난 첨단로봇 수리'로 이어집니다.",
	["Optional: it leads to Essential Artificials."] = "선택 사항: '필수 인공장치'로 이어집니다.",
	["Optional: it leads to Gnogaine."] = "선택 사항: '폐기물 수집'으로 이어집니다.",
	["Optional: it leads to Data Rescue."] = "선택 사항: '자료 회수'로 이어집니다.",
	["Optional: it leads to Lost in the Thicket Things."] = "선택 사항: '덤불 속에서 길을 잃다'로 이어집니다.",
	["Optional: it leads to The Essence of Aku'Mai."] = "선택 사항: '아쿠마이의 정수'로 이어집니다.",
	["Optional: it leads to Lethtendris's Web. Also from Courier Hammerfall in Ironforge and Herald Moonstalker in Darnassus."] = "선택 사항: '레스텐드리스의 그물'로 이어집니다. 아이언포지의 급사 해머폴과 다르나서스의 전령 문스토커에게서도 받을 수 있습니다.",
	["Optional: it leads to Lethtendris's Web. Also from Harbinger Balthazad in Undercity and Bluff Runner Windstrider in Thunder Bluff."] = "선택 사항: '레스텐드리스의 그물'로 이어집니다. 언더시티의 선구자 발타자드와 썬더 블러프의 포고꾼 윈드스트라이더에게서도 받을 수 있습니다.",
	["Repeatable. Thundris gives it only while The Test of Righteousness is in your quest log. The Corrupted Kor Gem drops from the Blackfathom Sea Witches inside, or the Tide Priestesses and Oracles at the entrance."] = "반복 가능. 툰드리스는 퀘스트 목록에 '정의의 시험'이 있을 때만 이 퀘스트를 줍니다. 부정한 코르석은 던전 안의 검은심연의 바다마녀나 입구의 검은심연의 바다여사제와 검은심연의 예언자에게서 획득합니다.",
	["Gryan Stoutmantle at Sentinel Hill in Westfall starts The Defias Brotherhood. Its first steps take you to Lakeshire and Stormwind and back, then send you after a Defias Messenger in Westfall. Then you escort the Defias Traitor to the Brotherhood's hideout. After that, Gryan gives the step done here, and Scout Riell gives Red Silk Bandanas."] = "서부 몰락지대 감시의 언덕의 그라이언 스타우트맨틀이 '데피아즈단'을 시작합니다. 첫 단계들은 레이크샤이어와 스톰윈드를 오가게 하고, 서부 몰락지대에서 데피아즈단 전령을 쫓게 합니다. 그다음 데피아즈단 배신자를 데피아즈단의 은신처까지 호위합니다. 그 뒤에야 그라이언이 이곳에서 하는 단계를, 정찰병 리엘이 '붉은 비단 복면'을 줍니다.",
	["Repeatable. Each go costs 3 silver."] = "반복 가능. 한 번에 3실버가 듭니다.",
	-- Razorfen Kraul: Speak with Thun'grim, Brutal Armor's lead-in, as a row marked optional as every other lead-in is: its name, objective, giver, giver's map label and note (Brutal Armor's shorter note already has its key, shared with Fire Hardened Mail) (2026-11-04; drafted, to be checked)
	["Speak with Thun'grim"] = "툰그림과의 대화",
	["Speak with Thun'grim Firegaze in the Barrens."] = "불모의 땅의 툰그림 파이어게이즈와 대화해야 합니다.",
	["Ruga Ragetotem, Camp Taurajo, The Barrens"] = "루가 분노토템, 불모의 땅 타우라조 야영지",
	["Ruga Ragetotem"] = "루가 분노토템",
	["Optional: it leads to Brutal Armor."] = "선택 사항: '투사의 방어구'로 이어집니다.",
	-- The steps the Quests tab now opens as parts of a row of same-named quests (Hidden Enemies, The Defias Brotherhood, The Test of Righteousness, Test of Lore, A Sign of Hope, The Rise of the Machines, Of Love and Family, The Restless Souls, Explosive Consultation): their objectives (2026-11-04; drafted, to be checked)
	["Gryan Stoutmantle wants you to talk to Wiley in Lakeshire."] = "그라이언 스타우트맨틀이 레이크샤이어의 와일리와 대화하기를 원합니다.",
	["Take Wiley's Note to Gryan Stoutmantle in Westfall."] = "와일리의 쪽지를 서부 몰락지대의 그라이언 스타우트맨틀에게 가져가십시오.",
	["Take Wiley's Note to Mathias Shaw in Stormwind."] = "와일리의 쪽지를 스톰윈드의 마티아스 쇼에게 가져가십시오.",
	["Take Shaw's report to Gryan Stoutmantle in Westfall."] = "쇼의 보고서를 서부 몰락지대의 그라이언 스타우트맨틀에게 가져가십시오.",
	["Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."] = "서부 몰락지대에서 데피아즈단 전령을 찾아 그의 전갈을 스타우트맨틀에게 가져가십시오.",
	["Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information."] = "데피아즈단 배신자를 데피아즈단의 비밀 은신처까지 호위하십시오. 배신자가 밴클리프와 그의 부하들이 숨어 있는 곳을 알려 주면, 그 정보를 가지고 그라이언 스타우트맨틀에게 돌아가십시오.",
	["Find Prospector Ryedol and let him know Hammertoe Grez is alive."] = "발굴조사단장 라이돌을 찾아 해머토 그레즈가 살아 있다고 알리십시오.",
	["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "돌발톱 산맥의 탈론딥 길 입구 근처에서 브라우그 딤스피릿을 찾으십시오.",
	["Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "위상들의 유산을 찾아 돌발톱 산맥의 탈론딥 길 입구 근처에 있는 브라우그 딤스피릿에게 가져가십시오.",
	["Find Parqual Fintallas in Undercity."] = "언더시티에서 파쿠알 핀탈라스를 찾으십시오.",
	["Speak to Jordan Stilwell in Ironforge"] = "아이언포지의 조던 스틸웰과 대화하십시오",
	["Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards."] = "불타는 평원으로 가서 대사제 테오도라 멀바다니아를 위해 부서진 정령 파편 10개를 구해 오십시오. 테오도라가 그 지역의 골렘과 정령에게서 이 파편을 얻을 수 있다고 했던 것이 기억납니다.",
	["Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east."] = "정령 파편 견본을 로트윌 베리아투스에게 가져가십시오. 테오도라가 로트윌이 동쪽의 야영지에 있다고 했던 것이 기억납니다.",
	["Find Egan. You only know that he was last seen around Stratholme."] = "에간을 찾으십시오. 그가 마지막으로 목격된 곳이 스트라솔름 근처라는 것밖에 모릅니다.",
	["Bring a Lieutenant's Insignia to Thrall in Orgrimmar."] = "부관의 휘장을 오그리마의 스랄에게 가져가십시오.",
	["Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."] = "부관의 휘장을 네루 파이어블레이드에게 가져가 대화하십시오. 그가 당신을 불타는 칼날의 일원으로 믿는지 살핀 뒤 오그리마의 스랄에게 돌아가십시오.",
	["Speak to Neeru Fireblade in Orgrimmar."] = "오그리마의 네루 파이어블레이드와 대화하십시오.",
	["Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."] = "역병지대 중남부에 있는 카엘 다로우 섬으로 가서 그림의 행방에 대한 단서를 찾아보십시오.",
	["Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."] = "브라우그 딤스피릿의 질문에 올바르게 답한 뒤 다시 말을 거십시오. 준비가 될 때까지 그는 돌발톱 산맥에 머뭅니다.",
	["Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."] = "파쿠알 핀탈라스의 질문에 올바르게 답한 뒤 다시 말을 거십시오. 준비가 될 때까지 그는 언더시티에 머뭅니다.",
	["Travel to the Dwarven District in Stormwind and find an engineer who can help."] = "스톰윈드의 드워프 지구로 가서 도움을 줄 수 있는 기술자를 찾으십시오.",
	["Return to Alba Fairmoon in Westfall."] = "서부 몰락지대의 알바 페어문에게 돌아가십시오.",
	-- The steps the Quests tab now lists one by one in a chain, numbered as parts of a name (The Tome of Valor, The True Masters, Down the Scarlet Path, Prospect of Faith, Passing Word of a Threat, The Smoldering Ruins of Thaurissan, Detonation at a Distance): their objectives and givers (2026-11-06; drafted, to be checked)
	["Talk to someone in Stormwind Intelligence about acquiring a remote detonator."] = "원격 기폭 장치를 구하는 일에 대해 스톰윈드 정보국의 누군가와 대화하십시오.",
	["Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind."] = "원격 기폭 장치 꾸러미를 스톰윈드 드워프 지구의 스프라이트 점프스프로켓에게 가져가십시오.",
	["Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."] = "언데드 약탈자 30마리를 처치한 후 나이젤의 야영지에 있는 수도사 안톤에게 돌아가십시오.",
	["Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."] = "수도사 안톤의 추천서를 사우스쇼어의 경건한 신자 랄레이에게 가져가십시오.",
	["Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."] = "해머토의 아뮬렛을 황야의 땅에 있는 발굴조사단장 라이돌에게 가져가십시오.",
	["Take Hammertoe's Amulet to Historian Karnik in Ironforge."] = "해머토의 아뮬렛을 아이언포지의 역사가 카르닉에게 가져가십시오.",
	["Find Advisor Belgrum and give him his note."] = "조언자 벨그룸을 찾아 그의 쪽지를 전하십시오.",
	["Speak to Historian Karnik."] = "역사가 카르닉과 대화하십시오.",
	["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."] = "레이크샤이어로 가서 헬렌디스 리버혼의 편지를 치안판사 솔로몬에게 전하십시오.",
	["Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep."] = "스톰윈드로 가서 솔로몬의 탄원서를 대영주 볼바르 폴드라곤에게 전하십시오. 볼바르는 스톰윈드 왕궁에 있습니다.",
	["Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."] = "카트라나 프레스터 부인과 대화한 후 대영주 볼바르 폴드라곤과 대화하십시오.",
	["Take Bolvar's Decree to Magistrate Solomon in Lakeshire."] = "볼바르의 칙령을 레이크샤이어의 치안판사 솔로몬에게 가져가십시오.",
	["Speak with Marshal Maxwell in the Burning Steppes."] = "불타는 평원의 치안대장 맥스웰과 대화하십시오.",
	["Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north."] = "털보 존과 대화하여 치안대장 윈저가 어떻게 되었는지 알아낸 다음 치안대장 맥스웰에게 돌아가십시오. 치안대장 맥스웰이 북쪽 동굴에서 그를 찾아보라고 했던 것이 기억납니다.",
	["Listen to Royal Historian Archesonus recant the history of Thaurissan."] = "왕실 역사가 아케소누스가 들려주는 타우릿산의 역사를 들으십시오.",
	["Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."] = "불타는 평원의 타우릿산 폐허로 가서 타우릿산 유물에서 정보를 얻으십시오. 정보를 얻으면 왕실 역사가 아케소누스에게 돌아가십시오.",
	["Speak to Duthorian Rall in Stormwind."] = "스톰윈드의 두소리안 랄과 대화하십시오.",
	["Find Daphne Stilwell in Westfall."] = "서부 몰락지대에서 다프네 스틸웰을 찾으십시오.",
	["Defend Daphne Stilwell from the Defias attack. Neither of your spirits must be released from their mortal coils if you wish to succeed. After you are successful, speak to Daphne Stilwell again."] = "데피아즈단의 공격으로부터 다프네 스틸웰을 지키십시오. 성공하려면 둘 중 누구도 죽어서는 안 됩니다. 성공하면 다프네 스틸웰과 다시 대화하십시오.",
	["Sprite Jumpsprocket, Stormwind City"] = "스프라이트 점프스프로켓, 스톰윈드",
	["Jasper Fel, Stormwind City"] = "재스퍼 펠, 스톰윈드",
	["Brother Anton, Desolace"] = "수도사 안톤, 잊혀진 땅",
	["Raleigh the Devout, Hillsbrad Foothills"] = "경건한 신자 랄레이, 힐스브래드 구릉지",
	["Historian Karnik, Ironforge"] = "역사가 카르닉, 아이언포지",
	["Advisor Belgrum, Ironforge"] = "조언자 벨그룸, 아이언포지",
	["Magistrate Solomon, Redridge Mountains"] = "치안판사 솔로몬, 붉은마루 산맥",
	["Royal Historian Archesonus, Ironforge"] = "왕실 역사가 아케소누스, 아이언포지",
	["Duthorian Rall, Stormwind City"] = "두소리안 랄, 스톰윈드",
	["Daphne Stilwell, Westfall"] = "다프네 스틸웰, 서부 몰락지대",
	-- Ruins of Lordaeron: Unending Torment's objectives (parts 2, 4 and 5), and where Remember That I Love You
	-- goes next (2026-11-10; drafted, to be checked)
	["Bring the Head of the Baron to Othmar's body, the Unfinished Abomination, in the Undercity."] = "남작의 머리를 언더시티에 있는 미완성 누더기골렘인 오스마르의 몸에 가져가야 합니다.",
	["Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the herbalism trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter, for Master Apothecary Faranell."] = "상업 지구의 토니 그리제트에게서 독성 두건버섯을, 약초 채집 전문가 근처에서 물집풀을, 도적 지구의 독 상인에게서 고통의 정수를 구해 수석 연금술사 파라넬에게 가져가야 합니다.",
	["Inject the Hissing Serum into the system above Othmar's body, then report to Master Apothecary Faranell."] = "오스마르의 몸 위에 있는 장치에 쉭쉭거리는 혈청을 주입한 뒤 수석 연금술사 파라넬에게 보고해야 합니다.",
	["Then Orphan Matron Nightingale gives Remember That I Love You: take the Blood-Stained Letter to Avette Fellwood in Duskwood."] = "그 후 보육원 원장님 나이팅게일이 '사랑한다는 걸 잊지 마'를 주며, 피로 얼룩진 편지를 그늘숲의 아베트 펠우드에게 가져가야 합니다.",
	-- The quest check of 2026-11-05 (the owner's calls of that day): Elemental Aid's second giver, and Before you go's Viewing Room Key, Postmaster Malown, Stratholme's Scarlet Key and Uldaman's Keystone (2026-11-05; drafted, to be checked)
	["Rau Cliffrunner (or Prate Cloudseer), Thousand Needles"] = "라우 클리프러너(또는 프레이트 클라우드시어), 버섯구름 봉우리",
	["The Viewing Room Key"] = "스칼로맨스 강당 열쇠",
	["Rattlegore drops the {item:13873:Viewing Room Key:1}. In the original game, it opened the Viewing Room door, the way on to Vectus and Marduk Blackpool, and one key did for the whole group. This is not yet checked on Forever."] = "들창어금니가 {item:13873:Viewing Room Key:1}를 떨어뜨립니다. 원래 게임에서는 이 열쇠로 스칼로맨스 강당 문을 열었고, 그 문을 지나야 벡투스와 마르두크 블랙풀에게 갈 수 있었으며, 일행 중 한 명만 열쇠가 있으면 됐습니다. Forever에서는 아직 확인되지 않았습니다.",
	["Postmaster Malown, a hidden boss"] = "우체국장 말로운, 숨겨진 우두머리",
	["The Stratholme Courier drops the city's postbox keys. In the original game, each locked postbox you opened brought out guards, and Postmaster Malown came with the third. This is not yet checked on Forever."] = "스트라솔름 급사가 도시의 우체통 열쇠를 떨어뜨립니다. 원래 게임에서는 잠긴 우체통을 열 때마다 경비병이 나왔고, 세 번째에 우체국장 말로운이 나왔습니다. Forever에서는 아직 확인되지 않았습니다.",
	["{item:7146:The Scarlet Key:2} is in Doan's Strongbox, in the Scarlet Monastery's Library. In the original game, it also opened the Bastion Door and the door of the Hall of High Command here, and a rogue could pick both locks. This is not yet checked on Forever."] = "{item:7146:The Scarlet Key:2}는 붉은십자군 수도원 도서관의 도안의 금고에 들어 있습니다. 원래 게임에서는 이 열쇠로 이곳의 성채 문과 최고 사령부 전당의 문도 열 수 있었고, 도적은 두 자물쇠를 모두 딸 수 있었습니다. Forever에서는 아직 확인되지 않았습니다.",
	["The Keystone"] = "쐐기돌",
	-- Uldaman's Keystone for both sides, reworded: the owner's report, 2026-11-05 (drafted, to be checked)
	["Revelosh drops {item:7741:The Shaft of Tsol:1}. Put together with the {item:7740:Gni'kiv Medallion} from Baelog's Chest, behind the Lost Dwarves, it makes the {item:7733:Staff of Prehistoria}, which works the Keystone in the Map Chamber, past Revelosh, and opens Ironaya's door. This is not yet checked on Forever."] = "레벨로쉬가 {item:7741:The Shaft of Tsol:1}를 떨어뜨립니다. 길 잃은 드워프 뒤에 있는 밸로그의 궤짝에서 나오는 {item:7740:Gni'kiv Medallion}과 합치면 {item:7733:Staff of Prehistoria}가 되며, 이 지팡이로 레벨로쉬를 지나 지도의 방에 있는 쐐기돌을 작동시켜 아이로나야의 문을 엽니다. Forever에서는 아직 확인되지 않았습니다.",
}

-- The client's own names for the bosses, factions and places, which what it says of them (and the
-- routes the player saved) are matched by (Core/Registry.lua's ns.KeepClientNames).
if client then client.BOSS_NAMES, client.FACTION_NAMES, client.STRINGS = L.BOSS_NAMES, L.FACTION_NAMES, L.STRINGS end
